) as v (wger_id, wger_uuid, name, category, muscles_primary, muscles_secondary, equipment, license, license_author,
        source_url)
on conflict (wger_id) do update set
  wger_uuid = excluded.wger_uuid, name = excluded.name, category = excluded.category,
  muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary,
  equipment = excluded.equipment, license = excluded.license, license_author = excluded.license_author,
  source_url = excluded.source_url, archived_at = null;

insert into public.exercise_translations (exercise_id, locale, name, description)
select e.id, v.locale::public.app_locale, v.name, v.description
from (values
  (9, 'en', '2 Handed Kettlebell Swing', 'Two Handed Russian Style Kettlebell swing'),
  (12, 'en', 'Seated Hip Adduction', 'Starting Position: Sit on the machine with your knees inward and against the pads. Pull the pin to release the pads. Grab the handles on the sides.b'),
  (12, 'ru', 'Сведение ног в тренажёре сидя', null),
  (20, 'en', 'Arnold Shoulder Press', 'Very common shoulder exercise.
As shown here: https://www.youtube.com/watch?v=vj2w851ZHRM'),
  (20, 'ru', 'Жим Арнольда', null),
  (31, 'en', 'Axe Hold', 'Grab dumbbells and extend arms to side and hold as long as you can'),
  (41, 'en', 'Barbell Ab Rollout', 'Place a barbell on the floor at your feet.
Bending at the waist, grip the barbell with a shoulder with overhand grip.
With a slow controlled motion, roll the bar out so that your back is straight.
Roll back up raising your hips and butt as you return to the starting position.'),
  (43, 'en', 'Barbell Hack Squats', 'Perform leg squats with barbell behind your legs'),
  (43, 'ru', 'Гакк-приседания со штангой', null),
  (46, 'en', 'Barbell Lunges Standing', 'Put barbell on the back of your shoulders. Stand upright, then take the first step forward. Step should bring you forward so that your supporting legs knee can touch the floor. Then stand back up and repeat with the other leg.
Remember to keep good posture.'),
  (46, 'ru', 'Выпады со штангой на месте', null),
  (48, 'en', 'Barbell Reverse Wrist Curl', 'Sitting on a bench, grab a barbell with your palms facing down and your hands shoulder-width apart. Rest your forearms on your thighs and allow your wrists to hang over your knees.
Curl your knuckles towards your face, lifting the barbell. Pause for a moment in the top position, then slowly return the barbell to the starting position.'),
  (50, 'en', 'Barbell Triceps Extension', 'Position barbell overhead with narrow overhand grip.
Lower forearm behind upper arm with elbows remaining overhead. Extend forearm overhead. Lower and repeat.'),
  (51, 'en', 'Barbell Wrist Curl', 'Sitting on a bench, grab a barbell with your palms facing up and your hands shoulder-width apart. Rest your forearms on your thighs and allow your wrists to hang over your knees. Perform the movement by curling your palms and wrists towards your face.
Pause for a moment in the top position, then slowly return the barbell to the starting position.'),
  (56, 'en', 'Abdominal Stabilization', null),
  (57, 'en', 'Bear Walk 2', '-Rest your weight on your palms and the balls of your feet, not dissimilar to normal pushup position
-Move by stepping with your R palm and L foot, then your L palm and R foot. Basically, walk like a lumbering bear.
-Move as fast as you can. Measure your reps/sets in either distance (i.e. 40 yards) or time (i.e. 45 seconds)
-Works your Pecs, Deltoids, Triceps, Traps, Lats, Abs and Lower Back, Hip Flexors, Quads, Glutes and Calves'),
  (71, 'en', 'Single Leg Extension', null),
  (73, 'en', 'Bench Press', 'Lay down on a bench, the bar should be directly above your eyes, the knees are somewhat angled and the feet are firmly on the floor. Concentrate, breath deeply and grab the bar more than shoulder wide. Bring it slowly down till it briefly touches your chest at the height of your nipples. Push the bar up.
If you train with a high weight it is advisable to have a spotter that can help you up if you can''t lift the weight on your own.
With the width of the grip you can also control which part of the chest is trained more:
• wide grip: outer chest muscles
• narrow grip: inner chest muscles and triceps'),
  (73, 'ru', 'Жим штанги лёжа', null),
  (75, 'en', 'Benchpress Dumbbells', '•
Setup and Starting Position: Sit at the end of a flat bench with a dumbbell resting vertically against each thigh. Carefully lean back while driving the dumbbells toward your chest with your knees.
•
The “Leg Drive” and Posture: Plant your feet firmly on the floor. Retract your shoulder blades (press them together against the bench) and maintain a slight natural lumbar curve.
•
Starting Position: Push the dumbbells toward the ceiling. Your wrists should be aligned with your elbows. Rotate the dumbbells slightly inward (about 45 degrees) so that your elbows do not splay out too far to the sides, thereby protecting your shoulders.
•
Eccentric Phase (Lowering): Lower the dumbbells in a controlled manner toward the sides of your chest. Your elbows should lower at an angle of about 45–60 degrees relative to your body. Feel the stretch in the lower part of your chest.
•
Concentric Phase (Lift): Push the weight upward in a slight arc (toward the center), without letting the dumbbells collide at the top or fully locking out your elbows to maintain muscle tension. Exhale as you lift.
Translated with DeepL.com (free version)'),
  (75, 'ru', 'Жим гантелей лёжа', null),
  (76, 'en', 'Bench Press Narrow Grip', '• Setup: Lie flat on the bench and grip the bar at shoulder-width (closer than a standard bench press).
• Descent: Lower the bar with control to your lower chest.
• Form: Keep your elbows tucked in tight against your torso—do not let them flare out.
• Ascent: Press the bar straight back up, squeezing your triceps at the top.'),
  (76, 'ru', 'Жим штанги лёжа узким хватом', null),
  (79, 'en', 'Bent High Pulls', 'Bend over slightly while holding two dumbbells. Pull the dumbbells up to your chest, keeping your elbows as high as you can.'),
  (81, 'en', 'Bent Over Dumbbell Rows (Single Arm)', 'With dumbbells in hand, bend at the hip until hands hang just below the knees (similar to straight-legged-deadlift starting position). Keep upper body angle constant while contracting your lats to pull you ellbows back pinching the shoulder blades at the top. Try not to stand up with every rep, check hands go below knees on every rep.'),
  (81, 'ru', 'Тяга гантели одной рукой в наклоне', null),
  (82, 'en', 'Bent-over Lateral Raises', 'Sit on bench while holding weights. Bend forward as far as possible, with arms slightly bent at the elbow. Perform a lateral raise while maintaining the bend in your elbow.'),
  (82, 'ru', 'Махи гантелями в наклоне', null),
  (83, 'en', 'Bent Over Rowing', '• Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.
• Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.
• Then inhale and slowly lower the barbell back to the starting position.
• Repeat for the recommended amount of repetitions.'),
  (84, 'en', 'Bent Over Rowing Reverse', 'The same as regular rowing, but holding a reversed grip (your palms pointing forwards):
Grab the barbell with a wide grIp (slightly more than shoulder wide) and lean forward. Your upper body is not quite parallel to the floor, but forms a slight angle. The chest''s out during the whole exercise.
Pull now the barbell with a fast movement towards your belly button, not further up. Go slowly down to the initial position. Don''t swing with your body and keep your arms next to your body.'),
  (91, 'en', 'Biceps Curls With Barbell', 'Hold the Barbell shoulder-wide, the back is straight, the shoulders slightly back, the arms are streched. Bend the arms, bringing the weight up, with a fast movement. Without pausing, let down the bar with a slow and controlled movement.
Don''t allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows).'),
  (91, 'ru', 'Подъём штанги на бицепс', null),
  (92, 'en', 'Biceps Curls With Dumbbell', 'Hold two dumbbells, the arms are streched, the hands are on your side, the palms face inwards. Bend the arms and bring the weight with a fast movement up. At the same time, rotate your arms by 90 degrees at the very beginning of the movement. At the highest point, rotate a little the weights further outwards. Without a pause, bring them down, slowly.
Don''t allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows).'),
  (92, 'ru', 'Подъём гантелей на бицепс', null),
  (94, 'en', 'Biceps Curls With SZ-bar', 'Hold the SZ-bar shoulder-wide, the back is straight, the shoulders slightly back, the arms are streched. Bend the arms, bringing the weight up, with a fast movement. Without pausing, let down the bar with a slow and controlled movement.
Don''t allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows).'),
  (95, 'en', 'Biceps Curl With Cable', 'Stand around 30 - 40cm away from the cable, the feet are firmly on the floor. Take the bar and lift the weight with a fast movements. Lower the weight as with the dumbbell curls slowly and controlled.'),
  (95, 'ru', 'Сгибание рук на нижнем блоке', null),
  (112, 'en', 'Body-Ups', '• Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torso straight. Your forearms should be shoulder-width apart. This will be your starting position.
• Pressing your palms firmly into the ground, extend through the elbows to raise your body from the ground. Keep your torso rigid as you perform the movement.
• Slowly lower your forearms back to the ground by allowing the elbows to flex.
• Repeat as needed.'),
  (124, 'en', 'Braced Squat', 'Stand with feet slightly wider than shoulder-width apart, while standing as tall as you can.
Grab a weight plate and hold it out in front of your body with arms straight out. Keep your core tight and stand with a natural arch in your back.
Now, push hips back and bend knees down into a squat as far as you can. Hold for a few moments and bring yourself back up to the starting position.'),
  (129, 'en', 'Chest Press', '• Adjust the seat height so that the grips are parallel to your chest.
• Use your legs to push the foot forward pedal.
• Bring the handles to the start position.
• Keep your back in contact with the back pad, press outwards.
• Press the handles away from your chest and exhale.
• Allow the handles to come in gently until they reach your chest.
• Allow the handles to return to your chest as you inhale.'),
  (129, 'ru', 'Жим от груди в тренажёре', null),
  (132, 'en', 'Burpees', 'Jump, lay down on your chest, do a pushup then jump, repeat'),
  (132, 'ru', 'Бёрпи', null),
  (135, 'en', 'Butterfly', 'Sit on the butterfly machine, the feet have a good contact with the floor, the upper arms are parallel to the floor. Press your arms together till the handles are practically together (but aren''t!). Go slowly back. The weights should stay all the time in the air.'),
  (137, 'en', 'Butterfly Narrow Grip', 'The movement is the same as with a regular butterfly, only that the grip is narrow:
Sit on the butterfly machine, the feet have a good contact with the floor, the upper arms are parallel to the floor. Press your arms together till the handles are practically together (but aren''t!). Go slowly back. The weights should stay all the time in the air.'),
  (139, 'en', 'Butterfly Reverse', null),
  (142, 'en', 'Cable External Rotation', 'Steps:
• Start off placing an extension band around a post or in a secure position where it will not release and is at elbow level.
• Position yourself to the side of the band and with your hand that is opposite of the band, reach out and grab the handle.
• Bring the band to your chest keeping your elbow bent in a 90 degree angle then slowly rotate your arm in a backhand motion so that the band externally rotates out
• Continue out as far as possible so that you feel a stretch in your shoulders, hold for a count and then return back to the starting position.
• Repeat for as many reps and sets as desired.'),
  (145, 'en', 'Cable Woodchoppers', 'Set cable pulley slightly lower than chest height. Keep body facing forward with hips stable. Grab the pulley handle, fully extend your arms and bring your arms forward and across your body. Hold for 1 second at the end of the movement and slowly return to starting position.'),
  (146, 'en', 'Calf Press Using Leg Press Machine', 'Put the balls of your feet on an extended leg press pad. Use your calves to press the weight by flexing your feet/toes into a pointed position, and releasing back into a relaxed position.
This exercise builds mass and strength in the Gastrocnemius and Soleus muscles as well, if not better, than any calf exercise.'),
  (148, 'en', 'Calf Raises on Hackenschmitt Machine', 'Place yourself on the machine with your back firmly against the backrest, the feet are on the platform for calf raises. Check that the feet are half free and that you can completely stretch the calf muscles down.
With straight knees pull up your weight as much as you can. Go with a fluid movement down till the calves are completely stretched. Repeat.'),
  (152, 'en', 'Chin Up', 'The chin-up (also known as a chin or chinup) is a strength training exercise. People frequently do this exercise with the intention of strengthening muscles such as the latissimus dorsi and biceps, which extend the shoulder and flex the elbow, respectively. In this maneuver, the palms are faced towards the body. It is a form of pull-up in which the range of motion is established in relation to a person''s chin.'),
  (152, 'ru', 'Подтягивания обратным хватом', null),
  (158, 'en', 'Close-grip Lat Pull Down', 'Grip the pull-down bar with your hands closer than shoulder width apart, with your palms facing away from you. Lean back slightly. Pull the bar down towards your chest, keeping your elbows close to your sides as you come down. Pull your shoulders back at the end of the motion.'),
  (161, 'en', 'Cross-Bench Dumbbell Pullovers', 'Grasp a moderately weighted dumbbell so your palms are flat against the underside of the top plates and your thumbs are around the bar. Lie on your back across a flat bench so only your upper back and shoulders are in contact with the bench. Your feet should be set about shoulder-width apart and your head should hang slightly downward. With the dumbbell supported at arm''s length directly about your chest, bend your arms about 15 degrees and keep them bent throughout the movement. Slowly lower the dumbbell backward and downward in a semicircle arc to as low a position as is comfortably possible. Raise it slowly back along the same arc to the starting point, and repeat for the required number of repetitions.'),
  (165, 'en', 'Ball crunches', null),
  (167, 'en', 'Crunches', 'Lay down on your back a soft surface, the feet are on the floor. Ask a partner or use some other help (barbell, etc.) to keep them fixed, your hands are behind your head. From this position move your upper body up till your head or elbows touch your knees. Do this movement by rolling up your back.'),
  (167, 'ru', 'Скручивания', null),
  (171, 'en', 'Incline Crunches', 'Lay down on your back on a inclined bench, feet are on one end of the bench. Ask a partner or use some other help (barbell, etc.) to keep them fixed, your hands are behind your head. From this position move your upper body up till your head or elbows touch your knees. Do this movement by rolling up your back.'),
  (172, 'en', 'Crunches on Machine', 'The procedure is very similar as for regular crunches, only with the additional weight of the machine. Sit on the machine, put both feet firmly on the ground. Grab the to the weights, cables, etc. and do a rolling motion forwards (the spine should ideally lose touch vertebra by vertebra). Slowly return to the starting position.'),
  (173, 'en', 'Crunches With Cable', 'Take the cable on your hands and hold it next to your temples. Knee down and hold your upper body straight and bend forward. Go down with a fast movement, rolling your back in (your ellbows point to your knees). Once down, go slowly back to the initial position.'),
  (174, 'en', 'Crunches With Legs Up', 'On your back, legs extended straight up, reach toward your toes with your hands and lift your shoulder blades off the ground and back.'),
  (177, 'en', 'Cycling', 'Cycling, also called bicycling or biking, is the use of bicycles for transport, recreation, exercise or sport. People engaged in cycling are referred to as cyclists, bicyclists, or bikers. Apart from two-wheeled bicycles, cycling also includes the riding of unicycles, tricycles, quadracycles, recumbent and similar human-powered vehicles.'),
  (177, 'ru', 'Велосипед', 'занятие на велотренажоре'),
  (178, 'en', 'Deadbug', 'Lie on your back, with your hips and knees bent to 90°. Raise both arms toward the ceiling. Pull your lower back to the floor to eliminate the gap. Start by pressing one leg out, and tapping the heel to the floor. "As you extend one leg, exhale as much as you can, keeping your lower back glued to the floor," Dunham says. When you can’t exhale any more, pull your knee back to the starting position. Make this more difficult by holding weight in your hands, or by lowering opposite arm and leg.'),
  (178, 'ru', 'Мёртвый жук', null),
  (182, 'en', 'Deadhang', 'Deadhang performed on an edge either with or without added weight (adujst edge or weight to adjust difficulty)'),
  (184, 'en', 'Deadlifts', 'Stand firmly, with your feet slightly more than shoulder wide apart. Stand directly behind the bar where it should barely touch your shin, your feet pointing a bit out. Bend down with a straight back, the knees also pointing somewhat out. Grab the bar with a shoulder wide grip, one overhand, one underhand (mixed grip).
Pull the weight up. At the highest point make a slight hollow back and pull the bar back. Hold 1 or 2 seconds that position. Go down, making sure the back is not bent. Once down you can either go back again as soon as the weights touch the floor, or make a pause, depending on the weight.'),
  (184, 'ru', 'Становая тяга', null),
  (185, 'en', 'Decline Bench Press Barbell', 'Lay down on a decline bench, the bar should be directly above your eyes, the knees are somewhat angled and the feet are firmly on the floor. Concentrate, breath deeply and grab the bar more than shoulder wide. Bring it slowly down till it briefly touches your chest at the height of your nipples. Push the bar up.'),
  (185, 'ru', 'Жим штанги лёжа головой вниз', null),
  (186, 'en', 'Decline Bench Press Dumbbell', 'Take two dumbbells and sit on a decline bench, the feet are firmly on the floor, the head is resting the bench. Hold the weights next to the chest, at the height of your nipples and press them up till the arms are stretched. Let the weight slowly and controlled down.'),
  (189, 'en', 'Deficit Deadlift', 'Preparation
Stand on weight plate, bumper plate, or shallow elevated platform with loaded bar above feet. Squat down and grasp bar with shoulder width or slightly wider overhand or mixed grip.
Execution
Lift bar by extending hips and knees to full extension. Pull shoulders back at top of lift if rounded. Return weights to floor by bending hips back while allowing knees to bend forward, keeping back straight and knees pointed same direction as feet. Repeat.
Comments
Throughout lift, keep hips low, shoulders high, arms and back straight. Knees should point same direction as feet throughout movement. Keep bar close to body to improve mechanical leverage. Grip strength and strength endurance often limit ability to perform multiple reps at heavy resistances. Gym chalk, wrist straps, grip work, and mixed grip can be used to enhance grip. Mixed grip indicates one hand holding with overhand grip and other hand holding with underhand grip. Lever barbell jack can be used to lift barbell from floor for easier loading and unloading of weight plates.
Barbell Deficit Deadlift emphasizes building strength through lowest portion of Deadlift. Target muscle is exercised isometrically. Heavy barbell deadlifts significantly engages Latissmus Dorsi. See Barbell Deficit Deadlift under Gluteus Maximus. Also see Deadlift Analysis.'),
  (193, 'en', 'Diagonal Shoulder Press', 'You sit at the bench press device, back slightly tilted to the back. The bar should be about 20 cm in front of you. Then you push the bar and take it back again, as you would with a bench press.
In this position you strain your chest muscles a lot less, which is nice if you want to train, but your chest hasn''t recovered yet.'),
  (194, 'en', 'Dips', 'A dip is an upper-body strength exercise. Narrow, shoulder-width dips primarily train the triceps, with major synergists being the anterior deltoid, the pectoralis muscles (sternal, clavicular, and minor), and the rhomboid muscles of the back (in that order).[1] Wide arm training places additional emphasis on the pectoral muscles, similar in respect to the way a wide grip bench press would focus more on the pectorals and less on the triceps.'),
  (194, 'ru', 'Отжимания на брусьях', null),
  (197, 'en', 'Dips Between Two Benches', 'Put two benches so far appart, that you can hold onto one with your hands and are just able to reach the other with your feet. The legs stay during the exercise completely stretched. With your elbows facing back, bend them as much as you can. Push yourself up, but don''t stretch out the arms.'),
  (197, 'ru', 'Обратные отжимания от скамьи', null),
  (202, 'en', 'Dumbbell Concentration Curl', 'Sit on bench. Grasp dumbbell between feet. Place back of upper arm to inner thigh. Lean into leg to raise elbow slightly.'),
  (202, 'ru', 'Концентрированный подъём гантели на бицепс', null),
  (203, 'en', 'Dumbbell Goblet Squat', 'Grasp dumbbell with both hands at the sides of the upper plates. Hold dumbbell in front of chest, close to torso. Place feet about shoulderwide apart, keep knees slightly bent.
Squat down until thighs are parallel to floor. Keep back straight, bend and move hips backward to keep knees above feet. Return, keep knees slightly flexed. Repeat.
Keep bodyweight on heels and look ahead or slightly above to keep back straight.'),
  (203, 'ru', 'Гоблет-приседания с гантелью', null),
  (204, 'en', 'Dumbbell Incline Curl', '• Setup: Set an adjustable bench to an incline of approximately 45 to 60 degrees.
• Starting Position: Sit back against the bench with a dumbbell in each hand. Let your arms hang straight down toward the floor with your palms facing forward (supinated grip).
• The Curl: Keeping your upper arms stationary and shoulders pinned back against the bench, exhale and curl the weights upward toward your shoulders.
• Peak Contraction: Squeeze your biceps hard at the top of the movement, ensuring your elbows do not swing forward.
• The Descent: Inhale and slowly lower the dumbbells back to the starting position, maintaining full control and feeling the stretch in the biceps.'),
  (205, 'en', 'Dumbbell Lunges Standing', '.'),
  (205, 'ru', 'Выпады с гантелями на месте', null),
  (206, 'en', 'Dumbbell Lunges Walking', '• Starting Position: Stand with feet hip-width apart and hands either on your hips or holding dumbbells at your sides.
• The Stride: Take a wide step forward with your right leg.
• The Descent: Lower your hips until both knees are bent at approximately 90-degree angles.
• The Transition: Drive through your front heel to stand up, bringing your back foot forward to step directly into the next lunge.'),
  (206, 'ru', 'Выпады с гантелями в ходьбе', null),
  (208, 'en', 'Dumbbells on Scott Machine', null),
  (211, 'en', 'Dumbbell Triceps Extension', 'Position one dumbbell over head with both hands under inner plate (heart shaped grip).
With elbows over head, lower forearm behind upper arm by flexing elbows. Flex wrists at bottom to avoid hitting dumbbell on back of neck. Raise dumbbell over head by extending elbows while hyperextending wrists. Return and repeat.'),
  (222, 'en', 'Facepull', 'Attach a rope to a pulley station set at about chest level.
Step back so you''re supporting the weight with arms completely outstretched and assume a staggered (one foot forward) stance. Bend the knees slightly for a stable base.
Retract the scapulae (squeeze your partner''s finger with your shoulder blades) and pull the center of the rope slightly up towards the face. A good cue is to think about pulling the ends of the rope apart, not just pulling back.
As you near your face, externally rotate so your knuckles are facing the ceiling.
Hold for one second at the top position and slowly lower.'),
  (222, 'ru', 'Тяга каната к лицу', null),
  (235, 'en', 'Flutter Kicks', '-Laying on the back, lift your straightened legs from the ground at a 45 degree angle.
-As your Left foot travels downward and nearly touches the floor, your Right foot should seek to reach a 90 degree angle, or as close to one as possible.
-Bring your R foot down until it nearly touches the floor, and bring your L foot upwards. Maintain leg rigidity throughout the exercise. Your head should stay off the ground, supported by tightened upper abdominals.
-(L up R down, L down R up, x2) ^v, v^, ^v, v^ = 1 rep
-Primarily works the Rectus Abdominus, the hip flexors and the lower back. Secondarily works the Obliques. Emphasis placed on the lower quadrant of the abs.'),
  (237, 'en', 'Fly With Cable', 'cable machine, two steps forward, straight back'),
  (238, 'en', 'Fly With Dumbbells', 'Take two dumbbells and lay on a bench, make sure the feet are firmly on the ground and your back is not arched, but has good contact with the bench. The arms are stretched in front of you, about shoulder wide. Bend now the arms a bit and let them down with a half-circle movement to the side. Without changing the angle of the elbow bring them in a fluid movement back up.'),
  (238, 'ru', 'Разводка гантелей лёжа', null),
  (239, 'en', 'Fly With Dumbbells, Decline Bench', 'The exercise is the same as with a regular bench:
Take two dumbbells and lay on a bench, make sure the feet are firmly on the ground and your back is not arched, but has good contact with the bench. The arms are stretched in front of you, about shoulder wide. Bend now the arms a bit and let them down with a half-circle movement to the side. Without changing the angle of the elbow bring them in a fluid movement back up.'),
  (245, 'en', 'Skullcrusher Dumbbells', 'Hold the dumbbells and lay down on a flat bench in such a way that around 1/4 of your head is over the edge. Stretch arms straight up and then lean dumbbells away from your toes to a 10-20 degree angle. Keep upper arm at this angle throughout exercise. Dumbbell shall not be amed at your head, but away over your head. This will maximise gain from exercise with load on triceps all the time.
Pay attention to your elbows and arms: only the triceps are doing the work, the rest of the arms should not move.'),
  (245, 'ru', 'Французский жим с гантелями', null),
  (246, 'en', 'Skullcrusher SZ-bar', 'Hold the SZ-bar and lay down on a flat bench in such a way that around 1/4 of your head is over the edge. Stretch your arms with the bar and bend them so that the bar is lowered. Just before it touches your forehead, push it up.
Pay attention to your elbows and arms: only the triceps are doing the work, the rest of the arms should not move.'),
  (246, 'ru', 'Французский жим с EZ-грифом', null),
  (254, 'en', 'Front Raises with Plates', 'The plate front raise is a variation of the dumbbell front raise where the lifter holds a weight plate between two hands, rather than using a dumbbell, barbell, or other weight. It can provide variety in a shoulder-focused muscle-building workout, or as part of an upper body or full-body circuit.
• While standing straight, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended and locked with a slight bend at the elbows and the plate should be down near your waist in front of you as far as you can go. Tip: The arms will remain in this position throughout the exercise. This will be your starting position.
• Slowly raise the plate as you exhale until it is a little above shoulder level. Hold the contraction for a second. As you inhale, slowly lower the plate back down to the starting position.
• Repeat for the recommended amount of repetitions.'),
  (256, 'en', 'Front Raises', 'To execute the exercise, the lifter stands with their feet shoulder width apart and weights or resistance handles held by their side with a pronated (overhand) grip.
The movement is to bring the arms up in front of the body to eye level and with only a slight bend in the elbow. This isolates the anterior deltoid muscle (front of the shoulder) and uses the anterior deltoid to lift the weight.
When lifting it is important to keep the body still so the anterior deltoid is fully utilised; if the weight cannot be lifted by standing still then it is too heavy and a lower weight is needed. It is important to keep a slight bend in the elbow when lifting as keeping the elbow locked will add stress to the elbow joint and could cause injury.
A neutral grip, similar to that used in the hammer curl, can also be used. With this variation the weight is again raised to eye level, but out to a 45 degree angle from the front of the body. This may be beneficial for those with shoulder injuries, particularly those related to the rotator cuff.'),
  (256, 'ru', 'Подъём гантелей перед собой', null),
  (257, 'en', 'Front Squats', 'This variation of the squat trains the hamstrings and gluteus maximus. It also works the back extensors and abductors.'),
  (257, 'ru', 'Фронтальные приседания со штангой', null),
  (258, 'en', 'Front pull wide', null),
  (259, 'en', 'Front Pull narrow', null),
  (260, 'en', 'Full Sit Outs', '(A) Get in high plank position on your hands and toes.(B) Shift your weight to your left hand as you turn your body to the right; bend your right leg behind you and extend your right arm up. Return to the center and repeat on the opposite side. Continue, alternating sides.Make it easier: Don’t raise your arm after you bend your leg behind you.Make it harder: Balance with your arm and leg extended for two counts.'),
  (265, 'en', 'Glute Bridge', 'Lie on you back with your hips and knees flexed, feet on the ground. From this position, raise your butt off of the ground to a height where your body makes a straight line from your knees to your shoulders. To make the exercise more intense, you can add weight by letting a barbell rest on your hips as you complete the motion, or you can put your feet on a slightly higher surface such as a step or a bench.'),
  (265, 'ru', 'Ягодичный мостик', null),
  (272, 'en', 'Hammer Curls', '• Start: Hold dumbbells at your sides with palms facing your torso.
• Curl: Lift the weights toward your shoulders while maintaining the neutral grip (like holding a hammer).
• Squeeze: Contract the biceps at the top without moving your elbows forward.
• Lower: Slowly return to the starting position with full control.'),
  (272, 'ru', 'Молотки с гантелями', null),
  (275, 'en', 'Hammercurls on Cable', 'Take a cable in your hands (palms parallel, point to each other), the body is straight. Bend the arms and bring the weight up with a fast movement. Without any pause bring it back down with a slow, controlled movement, but don''t stretch completely your arms.
Don''t swing your body during the exercise, the biceps should do all the work here. The elbows are at your side and don''t move.'),
  (279, 'en', 'Hand Grip', 'chrome Hand Flex Grip to build up forearms muscles'),
  (282, 'en', 'Handstand Pushup', 'The handstand push-up (press-up) - also called the vertical push-up (press-up) or the inverted push-up (press-up) also called commandos- is a type of push-up exercise where the body is positioned in a handstand. For a true handstand, the exercise is performed free-standing, held in the air. To prepare the strength until one has built adequate balance, the feet are often placed against a wall, held by a partner, or secured in some other way from falling. Handstand pushups require significant strength, as well as balance and control if performed free-standing.'),
  (282, 'ru', 'Отжимания в стойке на руках', null),
  (283, 'en', 'Hanging Leg Raises', 'Hanging from bar or straps, bring legs up with knees extended or flexed'),
  (283, 'ru', 'Подъём ног в висе', null),
  (284, 'en', 'Hercules Pillars', 'Grab two cables stand in the middle so both have tension and hold'),
  (285, 'en', 'High Knee Jumps', '• Start with legs slightly wider than shoulder width
• Drop into a bodyweight squat
• As you hit the bottom of the squat, explode upwards into a jump while simultaneously tucking your knees into your chest midflight. Remain tucked until the apex of your jump.
• Land on both feet, making sure your knees are not locked so as to avoid excessive strain upon your joints. Collect yourself into the next rep as quickly but under control as possible.'),
  (289, 'en', 'High Pull', 'Use a light barbell, perform explosive lift up starting from underneath knee cap level. Lift/raise explosively using hips, at shoulder level. Tempo: 2111'),
  (291, 'en', 'Hindu Squats', 'Start with your feet shoulder width apart and arms slightly behind your back.
As you descend towards the floor, raise your heels off the ground, while keeping your back as vertical as possible.
Upon attaining the bottom position, touch the hands to the heels.
Then stand up ending with the heels on the ground, arms extended in front of the chest then rowing into the start position.'),
  (292, 'en', 'Hip Raise, Lying', 'Lying down on your back, with your feet flat on the floor. Raise your hips up evenly as high as you can and hold for as long as you can.'),
  (294, 'en', 'Hip Thrust', 'The bar should go directly on your upper thigh, directly below your crotch. Your feet should be directly under your knees. Push your hips up so that you form a straight line from your knees to your shoulders. Use a pad for comfort.'),
  (294, 'ru', 'Хип-траст', null),
  (297, 'en', 'Hollow Hold', 'Get on a mat and lie on your back. Contract your abs, stretch your arms and legs and raise them (your head and shoulders are also be raised). Make sure your lower back remains in contact with the mat.'),
  (301, 'en', 'Hyperextensions', 'Lie on the hyperextension pillow with your navel at the front edge, allowing your upper body to hang freely. Tighten all your back muscles and raise your torso until you''re horizontal, but no higher. Lower yourself slowly, maintaining a steady flow of muscles.'),
  (301, 'ru', 'Гиперэкстензия', 'Гиперэкстензия – это упражнение, преимущественно на разгибание в поясничной области. Начните с того, что лягте на живот на специальный тренажёр, закрепив ноги в замках у его основания. Ваши бёдра должны лежать на подушечке, а тело свисать вниз. Руки можно положить на грудь или за голову. Разгибайте тело вверх, поднимая верхнюю часть тела до тех пор, пока оно не будет в одной линии с бедрами. Затем медленно вернитесь в исходное положение. Главное – делать движение аккуратно, избегая резких движений и перегибов в пояснице.'),
  (308, 'en', 'Incline Dumbbell Fly', 'Use inclined bench. Hold dumbbells straight out to your sides, elbows slightly bent. Bring arms together above you, keeping angle of elbows fixed.'),
  (308, 'ru', 'Разводка гантелей на наклонной скамье', null),
  (310, 'en', 'Incline Dumbbell Row', '• Using a neutral grip, lean into an incline bench.
• Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.
• Retract the shoulder blades and flex the elbows to row the dumbbells to your side.
• Pause at the top of the motion, and then return to the starting position.'),
  (312, 'en', 'Incline Plank With Alternate Floor Touch', 'Perform the plank with legs elevated, feet on a gymball. Once stabilised, slowly move one foot sideways off the ball, then make it touch the floor, then come back to starting position. Alternate with the other foot.
This is a core exercise.'),
  (314, 'en', 'Isometric Wipers', 'Assume push-up position, with hands slightly wider than shoulder width.
Shift body weight as far as possible to one side, allowing the elbow on that side to flex.
Reverse the motion, moving completely over to the other side.
Return to the starting position, and repeat for the desired number of repetitions.'),
  (319, 'en', 'Jogging', 'Get your shoes on, go outside and start running at a moderate pace.'),
  (319, 'ru', 'Бег', 'Бег предоставляет хорошие условия в качестве аэробной тренировки, которая увеличивает порог выносливости, положительно влияет на сердечно-сосудистую систему, повышает обмен веществ в организме и, таким образом, помогает осуществлять контроль за весом тела. Бег позитивно влияет на иммунную систему и улучшает тонус кожи. Укрепление мускулатуры ног и улучшение обмена веществ помогает предотвратить и устранить целлюлит.
https://ru.wikipedia.org/wiki/%D0%91%D0%B5%D0%B3'),
  (320, 'en', 'Jumping Jacks', 'A jumping jack or star jump, also called side-straddle hop in the US military, is a physical jumping exercise performed by jumping to a position with the legs spread wide and the hands going overhead, sometimes in a clap, and then returning to a position with the feet together and the arms at the sides'),
  (320, 'ru', 'Джампинг-Джек', '• Встаньте так, чтобы ноги были вместе, а руки по бокам
• Прыгните в положение, когда ноги широко расставлены, а руки касаются над головой
• Повторите'),
  (323, 'en', 'Cable Cross-over', 'Begin with cables at about shoulder height, one in each hand. Take a step forward so that one foot is in front of the other, for stability, and so that there is tension on the cables. Bring hands together in front of you. Try to make your hands overlap (so that the cables cross) a few inches.'),
  (323, 'ru', 'Сведение рук в кроссовере', null),
  (331, 'en', 'Kettlebell Swings', 'Hold the kettlebell securely in both hands. Keep your back flat throughout the move, avoiding any rounding of the spine.Keeping your knees "soft", hinge your hips backwards, letting the kettlebell swing between your knees.
You want to bend from the hips as far as you can without letting your back round forwards. Then, snap your hips forwards quickly and standing up straight, locking your body in an upright posture.
The speed you do this will cause your arms and the kettlebell to swing up in front of you. Don''t try to lift the kettlebell with your arms. The snapping forwards of your hips will cause the kettlebell to swing forwards through momentum. Depending on the weight of the kettlebell and the speed of your hip movement, your arms will swing up to about shoulder height. At the top of this swing, let your hips hinge backwards again as the kettlebell swings back down to between your legs and the start of the next repetition.'),
  (331, 'ru', 'Махи гирей', null),
  (341, 'en', 'Squats on Multipress', null),
  (341, 'ru', 'Приседания в тренажёре Смита', null),
  (346, 'en', 'Landmine press', null),
  (348, 'en', 'Lateral Raises', 'This exercise works the deltoid muscle of the shoulder. The movement starts with the arms straight, and the hands holding weights at the sides or in front of the body. Body is in a slight forward-leaning position with hips and knees bent a little. Arms are kept straight or slightly bent, and raised through an arc of movement in the coronal plane that terminates when the hands are at approximately shoulder height. Weights are lowered to the starting position, completing one rep. When using a cable machine the individual stands with the coronal plane in line with the pulley, which is at or near the ground.[9] The exercise can be completed one shoulder at a time (with the other hand used to stabilize the body against the weight moved), or with both hands simultaneously if two parallel pulleys are available.'),
  (348, 'ru', 'Махи гантелями в стороны', null),
  (349, 'en', 'Lateral Rows on Cable, One Armed', 'Set cable at waist height, start with arm across your belly and move han over and out too other side, one arm at the time.'),
  (351, 'en', 'Lateral-to-Front Raises', '-(1) Perform a lateral raise, pausing at the top of the lift (2).
-Instead of lowering the weight, bring it to the front of your body so that you appear to be at the top position of a front raise. You will do this by using a Pec Fly motion, maintaining straight arms. (3)
-Now lower the weight to your quadriceps, or, in other words, lower the dumbbells as though you are completing a Front Raise repetition. (4)
-Reverse the motion: Perform a front raise (5), at the apex of the lift use a Reverse Fly motion to position the weights at the top of a Lateral Raise (6), and finally, lower the weights until your palms are essentially touching the sides of your thighs (7). THIS IS ONE REP.
(1) l front view(2) -l- FV (3) l- side view (4) l SV/FV (5) l- SV (6) -l- FV (7) l FV/SV'),
  (354, 'en', 'Lat Pull Down (Leaning Back)', 'Lean Back, Pull into chest'),
  (355, 'en', 'Lat Pull Down (Straight Back)', 'The lat pull down is an exercise used to build the muscles of the back. While the exercise will primarily target the lats, you will also notice a fair amount of bicep and middle back activation.'),
  (364, 'en', 'Leg Curl', 'The leg curl, also known as the hamstring curl, is an isolation exercise that targets the hamstring muscles. The exercise involves flexing the lower leg against resistance towards the buttocks. Other exercises that can be used to strengthen the hamstrings are the glute-ham raise and the deadlift.'),
  (364, 'ru', 'Сгибание ног в тренажёре', null),
  (365, 'en', 'Leg Curls (laying)', 'Lay on a bench and put your calves behind the leg holder (better if they are hold on around the lower calves). Hold a grip on the bars to make sure the body is firmly in place. Bend your legs bringing the weight up, go slowly back. During the exercise the body should not move, all work is done by the legs.'),
  (365, 'ru', 'Сгибание ног лёжа', null),
  (366, 'en', 'Leg Curls (sitting)', null),
  (366, 'ru', 'Сгибание ног сидя', null),
  (367, 'en', 'Leg Curls (standing)', null),
  (369, 'en', 'Leg Extension', 'The leg extension is a resistance weight training exercise that targets the quadriceps muscle in the legs. The exercise is done using a machine called the Leg Extension Machine. There are various manufacturers of these machines and each one is slightly different. Most gym and weight rooms will have the machine in their facility. The leg extension is an isolated exercise targeting one specific muscle group, the quadriceps. It should not be considered as a total leg workout, such as the squat or deadlift. The exercise consists of bending the leg at the knee and extending the legs, then lowering them back to the original position.'),
  (369, 'ru', 'Разгибание ног в тренажёре', null),
  (371, 'en', 'Leg Press', 'The leg press is a weight training exercise in which the individual pushes a weight or resistance away from them using their legs.'),
  (371, 'ru', 'Жим ногами', null),
  (373, 'en', 'Leg Presses (narrow)', 'The exercise is very similar to the wide leg press:
Sit on the machine and put your feet on the platform so far apart that you could just put another foot in between them. The feet are parallel and point up.
Lower the weight so much, that the knees form a right angle. Push immediately the platform up again, without any pause. When in the lower position, the knees point a bit outwards and the movement should be always fluid.'),
  (374, 'en', 'Leg Presses (wide)', 'Sit on the machine and put your feet on the platform, a bit more than shoulder wide. The feet are turned outwards by a few degrees.
Lower the weight so much, that the knees form a right angle. Push immediately the platform up again, without any pause. When in the lower position, the knees point a bit outwards and the movement should be always fluid.'),
  (375, 'en', 'Leg Press on Hackenschmidt Machine', null),
  (376, 'en', 'Leg Raise', 'The leg raise is a strength training exercise which targets the iliopsoas (the anterior hip flexors). Because the abdominal muscles are used isometrically to stabilize the body during the motion, leg raises are also often used to strengthen the rectus abdominis muscle and the internal and external oblique muscles.'),
  (376, 'ru', 'Подъём ног', null),
  (377, 'en', 'Leg Raises, Lying', 'Lay down on a bench and hold onto the recliner with your hands to keep you stable. Hold your legs straight and lift them till they make an angle of about 45°. Make a short pause of 1 sec. and go slowly down to the initial position. To increase the intensity you can make a longer pause of 7 sec. every 5th time.'),
  (377, 'ru', 'Подъём ног лёжа', null),
  (378, 'en', 'Leg Raises, Standing', 'Put your forearms on the pads on the leg raise machine, the body is hanging freely. Lift now your legs with a fast movement as high as you can, make a short pause of 1sec at the top, and bring them down again. Make sure that during the exercise your body does not swing, only the legs should move.'),
  (379, 'en', 'Leverage Machine Chest Press', 'Be sure to adjust seat height so that the handles are towards the bottom of your pectorals.'),
  (380, 'en', 'Leverage Machine Iso Row', 'Adjust seat height so that the handles are at the bottom of your pectorals or just below.'),
  (382, 'en', 'L Hold', 'Hold the L position for as long as possible'),
  (386, 'en', 'Diamond push ups', 'Start: Get into a plank. Place hands close together under your chest so thumbs and index fingers form a diamond shape.
Lower: Bend your elbows to lower your chest toward your hands. Keep your body straight.
Push: Push back up until arms are fully extended.
New note Keep elbows close to your body and core tight.'),
  (394, 'en', 'Long-Pulley (low Row)', 'Sit down, put your feet on the supporting points and grab the bar with a wide grip. Pull the weight with a rapid movement towards your belly button, not upper. Keep your arms and elbows during the movement close to your body. Your shoulders are pulled together. Let the weight slowly down till your arms are completely stretched.'),
  (395, 'en', 'Long-Pulley, Narrow', 'The exercise is the same as the regular long pulley, but with a narrow grip:
Sit down, put your feet on the supporting points and grab the bar with a wide grip. Pull the weight with a rapid movement towards your belly button, not upper. Keep your arms and elbows during the movement close to your body. Your shoulders are pulled together. Let the weight slowly down till your arms are completely stretched.'),
  (397, 'en', 'Low Box Squat - Wide Stance', 'Unrack the bar and set your stance wide, beyond your hips. Push your hips back and sit down to a box that takes you below parallel. Sit completely down, do not touch and go. Then explosively stand up. Stay tight in your upper back and torso throughout the movement.'),
  (406, 'en', 'Lying Rotator Cuff Exercise', 'This is an excercise for problems with the rotator cuff. Primary Infraspinatus, secondary Teres Minor.
Lying on side. Keep elbow on waist and in 90 dgr angle. Rotate towards stomach. Add weight as fit.'),
  (418, 'en', 'Military Press mit SZ-Bar', 'On an SZ-bar grip your hands on the outside of each bend and stand with your arms straight down, palms facing your legs. Pull the bar (bending your arms at the elbow) to your chest, and the push the bar above your head (arms as straight as possible). Return the bar to your chest by dropping your arms at the elbows. Return the bar to it''s origional position (stand with your arms straight down, palms facing your legs.)'),
  (423, 'en', 'Muscle up', 'The body is then explosively pulled up by the arms in a radial pull-up, with greater speed than a regular pull-up. When the bar approaches the upper chest, the wrists are swiftly flexed to bring the forearms above the bar. The body is leaned forward, and the elbows are straightened by activating the triceps. The routine is considered complete when the bar is at the level of the waist and the arms are fully straight.
To dismount, the arms are bent at the elbow, and the body is lowered to the floor, and the exercise can be repeated.
As a relatively advanced exercise, muscle-ups are typically first learned with an assistive kip. The legs swing (kip) up and provide momentum to assist in the explosive upward force needed to ascend above the bar. More advanced athletes can perform a strict variation of the muscle-up which is done slowly, without any kip. This variation begins with a still dead hang and uses isometric muscle contraction to ascend above the bar in a slow, controlled fashion.'),
  (423, 'ru', 'Выход силой', null),
  (427, 'en', 'Negative Crunches', 'Sit yourself on the decline bench and fix your legs. Cross your arms over the chest and bring with a rolling movement your upper body up, go now without a pause and with a slow movement down again. Don''t let your head move during the exercise.'),
  (439, 'en', 'Overhand Cable Curl', 'Hands at shoulder height, curl arms in toward head, then back out.'),
  (441, 'en', 'Overhead Squat', 'The barbell is held overhead in a wide-arm snatch grip; however, it is also possible to use a closer grip if balance allows.'),
  (445, 'en', 'Pause Bench', 'Lower the bar to your chest and pause (but do not rest) there for 2 seconds. Press back up. use the same weight you would on bench press, but perform only single reps. Total the number of reps you did in one set of bench press (if you did 3 sets of 8 do 8 sinlge pause bench reps.'),
  (448, 'en', 'Pendelay Rows', 'Back excercise with a barbell with a starting position which is in a bent over position with the back paralell to the ground. The barbell is on the ground at chest level.For the movement grab the barbell at shoulder width grip and pull towards your chest without losing the bent over position and without moving anything but your arms'),
  (448, 'ru', 'Тяга Пендлея', null),
  (454, 'en', 'Pike Push Ups', 'Push Up performed from a pike position (optional to have feet elevated).'),
  (454, 'ru', 'Отжимания пайк', null),
  (456, 'en', 'Pistol Squat', '• Stand with feet hip-width apart, toes pointed forward, and chest tall.
• Extend your leg straight out; extend both arms in front of you, at shoulder level. Brace your core and look straight ahead.
• Slowly squat down.
• (optional) pause at the bottom.
Keep your (free) leg and arms extended for the whole duration.'),
  (456, 'ru', 'Пистолетик (приседание на одной ноге)', null),
  (458, 'en', 'Plank', 'Get into a position on the floor supporting your weight on your forearms and toes. Arms are bent and directly below the shoulder.
Keep your body straight at all times and hold this position as long as possible. To increase difficulty an arm or leg can be raised while performing this exercise.'),
  (458, 'ru', 'Планка', null),
  (465, 'en', 'Preacher Curls', 'Place the EZ curl bar on the rest handles in front of the preacher bench. Lean over the bench and grab the EZ curl bar with palms up. Sit down on the preacher bench seat so your upper arms rest on top of the pad and your chest is pressed against the pad. Lower the weight until your elbows are extended and arms are straight. Bring the weights back up to the starting point by contracting biceps. Repeat'),
  (465, 'ru', 'Сгибание рук на скамье Скотта', null),
  (468, 'en', 'Prone Scapular Retraction - Arms at Side', 'Lying on stomach with head on towel.
Stretch arms straight out to your sides.
Slowly lift your arms, pulling your shoulderblades together, hold for 3 seconds.'),
  (475, 'en', 'Pull-ups', 'Grab the pull up bar with a wide grip, the body is hanging freely. Keep your chest out and pull yourself up till your chin reaches the bar or it touches your neck, if you want to pull behind you. Go with a slow and controlled movement down, always keeping the chest out.'),
  (475, 'ru', 'Подтягивания', null),
  (477, 'en', 'Pull Ups on Machine', null),
  (478, 'en', 'Push Press', 'Clean your dumbbells onto your shoulders, palms facing in. Take a breath and brace your core. (picture 1)Dip at the knees and use your legs to help (picture 2) press your dumbbells overhead. Lower under control with a slow tempo to your shoulders and repeat.'),
  (478, 'ru', 'Жимовой швунг', null),
  (484, 'en', 'Rack Deadlift', 'Deadlift to be done using a Smith machine or a free rack. Bar or barbell hould be just right under the knee cap level. Lift using the glutes and through the heels, then come back to starting postion with a control movement of 2 seconds.
This exercise targets mainly the lower back and glutes.'),
  (484, 'ru', 'Становая тяга со стоек', null),
  (487, 'en', 'Rear Delt Raises', 'Seated on a bench with the dumbbells on the floor bend over at 45 Degrees and then slowly raise each dumbbell to shoulder height and hold for a couple seconds before lowering to the starting position.'),
  (490, 'en', 'Renegade Row', 'Get into pushup position gripping some dumbbells. Perform one pushup, then drive your left elbo up, bringing the dumbell up to your body. Return the dumbell to starting position.
Perform another pushup and then row with the other arm to complete one rep.'),
  (493, 'en', 'Reverse Bar Curl', 'Hold bar with reverse (or "overhand") grip, palms facing the floor.'),
  (495, 'en', 'Reverse Curl', 'The reverse-grip barbell curl is a variation on the biceps curl where the palms face downward. The switch from an underhand to an overhand grip brings the forearm and brachialis muscles more into the exercise.'),
  (498, 'en', 'Reverse Grip Bench Press', 'Upper chest focuses exercise that also works triceps'),
  (500, 'en', 'Reverse Plank', 'Plank with stomach towards ceiling'),
  (501, 'en', 'Ring Dips', 'Dips peformed on gymnastic rings.'),
  (505, 'en', 'Roman Chair Crunch', 'Crunches on roman chair. Keep your torso straight, abs tight, and don''t come up all the way vertical or lie flat to keep constant tension on your abs.'),
  (507, 'en', 'Romanian Deadlift', 'DL from top to pos 2: https://www.youtube.com/watch?v=WtWtjViRsKo'),
  (507, 'ru', 'Румынская тяга', null),
  (508, 'en', 'Row', 'In strength training, rowing (or a row, usually preceded by a qualifying adjective — for instance a seated row) is an exercise where the purpose is to strengthen the muscles that draw the rower''s arms toward the body (latissimus dorsi) as well as those that retract the scapulae (trapezius and rhomboids) and those that support the spine (erector spinae). When done on a rowing machine, rowing also exercises muscles that extend and support the legs (quadriceps and thigh muscles). In all cases, the abdominal and lower back muscles must be used in order to support the body and prevent back injury.'),
  (510, 'en', 'Rowing, Lying on Bench', null),
  (512, 'en', 'Rowing seated, narrow grip', '• Tighten muscles
• Controlled movement
• Slow movement
• Keep upper body upright
• Do not lean back
• Pull toward chest'),
  (513, 'en', 'Rowing, T-bar', 'The execution of this exercise is very similar to the regular bent over rowing, only that the bar is fixed here.
Grab the barbell with a wide grip (slightly more than shoulder wide) and lean forward. Your upper body is not quite parallel to the floor, but forms a slight angle. The chest''s out during the whole exercise. Pull now the barbell with a fast movement towards your belly button, not further up. Go slowly down to the initial position. Don''t swing with your body and keep your arms next to your body.'),
  (513, 'ru', 'Тяга Т-грифа', null),
  (516, 'en', 'Front Wood Chop', null),
  (527, 'en', 'Run', 'Running or jogging outside in a park, on the tracks,...'),
  (527, 'ru', 'Бег', null),
  (529, 'en', 'Run - Interval Training', 'Run and do some interval trainings such as hill repat, fartlek,..'),
  (530, 'en', 'Run - Treadmill', 'Run on a treadmill'),
  (530, 'ru', 'Бег на дорожке', null),
  (537, 'en', 'Incline Bench Press - Dumbbell', 'This is a variation of the flat bench press designed to emphasize the clavicular head of the pectoralis major (the upper portion). By tilting the torso, the angle of the push changes, shifting more tension to the upper chest and shoulders, which helps achieve a more aesthetic, balanced, and three-dimensional development of the torso.
•
Bench Adjustment and Preparation: Set the bench to an incline of between 30 and 45 degrees (an incline greater than 45° will place too much strain on the shoulders and reduce the stimulus to the chest). Sit down with a dumbbell on each thigh.
•
Starting position: Lean back, resting your back against the bench, while using your knees one after the other to push the dumbbells upward to shoulder height.
•
Anatomical Stabilization: Plant your feet firmly on the floor. Retract your scapulas (bring your shoulder blades together and press them into the bench) to protect your shoulders and stabilize the load.
•
Eccentric Phase (Lowering): Lower the dumbbells slowly and in a controlled manner toward the upper part of your chest. Your elbows should not splay out to the sides (90°); maintain a safe angle of about 45 to 60 degrees relative to your torso.
•
Concentric Phase (Lift): Push the dumbbells vertically upward as you exhale. Follow a slightly converging path (without letting them touch at the top). Stop the movement just before locking out your elbows to maintain muscle tension in the upper pectoral.'),
  (537, 'ru', 'Жим гантелей на наклонной скамье', null),
  (538, 'en', 'Incline Bench Press - Barbell', 'To do slowly, tempo is 4010'),
  (538, 'ru', 'Жим штанги на наклонной скамье', null),
  (539, 'en', 'Incline Bench Press - MP', null),
  (543, 'en', 'Shoulder Press, on Machine', null),
  (545, 'en', 'Scissors', 'Scissors is an abdominal exercise that strengthens the transverse abdominals, helping flatten your belly and strengthen your entire core. Scissors is not only a core strength move, but it is also a great stretch for your hamstrings and your lower back. Everyone is looking for new ways to work the core, to flatten the belly and to improve flexibility. If you learn how to do Scissors you will get everything rolled together in one move.'),
  (549, 'en', 'Seated Triceps Press', 'Sit down on a back (better with back support). Take a dumbbell firmly with both hands and hold it with extended arms over your head. With your palms facing upward and holding the weight of the dumbbell, slowly lower the weight behind your head.'),
  (556, 'en', 'Side Bends on Machine', null),
  (562, 'en', 'Shotgun Row', '• Attach a single handle to a low cable.
• After selecting the correct weight, stand a couple feet back with a wide-split stance. Your arm should be extended and your shoulder forward. This will be your starting position.
• Perform the movement by retracting the shoulder and flexing the elbow. As you pull, supinate the wrist, turning the palm upward as you go.
• After a brief pause, return to the starting position.'),
  (566, 'en', 'Shoulder Press, Barbell', 'Sit on a bench, the back rest should be almost vertical. Take a barbell with a shoulder wide grip and bring it up to chest height. Press the weight up, but don''t stretch the arms completely. Go slowly down and repeat.'),
  (566, 'ru', 'Жим штанги стоя', null),
  (567, 'en', 'Shoulder Press, Dumbbells', 'Sit on a bench, the back rest should be almost vertical. Take two dumbbells and bring them up to shoulder height, the palms and the elbows point during the whole exercise to the front. Press the weights up, at the highest point they come very near but don''t touch. Go slowly down and repeat.'),
  (567, 'ru', 'Жим гантелей сидя', null),
  (569, 'en', 'Shoulder Press, on Multi Press', 'The exercise is basically the same as with a free barbell:
Sit on a bench, the back rest should be almost vertical. Take a bar with a shoulder wide grip and bring it down to chest height. Press the weight up, but don''t stretch the arms completely. Go slowly down and repeat.'),
  (570, 'en', 'Shoulder Shrug', 'The shoulder shrug (usually called simply the shrug) is an exercise in weight training used to develop the upper trapezius muscle. The lifter stands erect, hands about shoulder width apart, and raises the shoulders as high as possible, and then lowers them, while not bending the elbows, or moving the body at all. The lifter may not have as large a range of motion as in a normal shrug done for active flexibility. It is usually considered good form if the slope of the shoulders is horizontal in the elevated position.'),
  (571, 'en', 'Shrugs, Barbells', 'Take a barbell and stand with a straight body, the arms are hanging freely in front of you. Lift from this position the shoulders as high as you can, but don''t bend the arms during the movement. On the highest point, make a short pause of 1 or 2 seconds before returning slowly to the initial position.
When training with a higher weight, make sure that you still do the whole movement!'),
  (571, 'ru', 'Шраги со штангой', null),
  (572, 'en', 'Shrugs, Dumbbells', 'Stand with straight body, the hands are hanging freely on the side and hold each a dumbbell. Lift from this position the shoulders as high as you can, but don''t bend the arms during the movement. On the highest point, make a short pause of 1 or 2 seconds before returning slowly to the initial position.
When training with a higher weight, make sure that you still do the whole movement!'),
  (572, 'ru', 'Шраги с гантелями', null),
  (575, 'en', 'Shrugs on Multipress', null),
  (576, 'en', 'Side Crunch', 'Hold weight in one hand. Bend side ways to the knee. Pull upo to upright position using your obliquus.'),
  (577, 'en', 'Side Dumbbell Trunk Flexion', 'AKA dumbbell side bends. Stand in line with the hips with slightly bent knees, maintain the natural curvature of the spine, hand stretched by the body, grip the barbell with one hand. Make slow and controlled torso side flexions till you reach the angle of approximately 45°.'),
  (578, 'en', 'Side-lying External Rotation', 'With a weight in one hand, lie on your side opposite the weight. Keep your knees slightly bent. Hold your elbow against your side, and extend your upper arm straight ahead of you. While continuing to hold your elbow against your side, rotate your upper arm 90 degrees upwards.
It is helpful to place a towel under your armpit to help with the form on this exercise. Placing a support under your head for the duration of the exercise is also a good idea.'),
  (580, 'en', 'Side Plank', 'Works your obliques and helps stabilize your spine. Lie on your side and support your body between your forearm and knee to your feet.'),
  (580, 'ru', 'Боковая планка', null),
  (583, 'en', 'Side to Side Push Ups', '-start in push up position
-lean the body weight to the right side, and complete a push up with the chest over the right hand
-come back to the centered position
-on rep 2, lean to the left side'),
  (584, 'en', 'Single-arm Preacher Curl', 'Sit on the preacher curl bench and perform a bicep curl with a dumbbell in one hand. Your other hand can be at rest, or beneath your curling arm''s elbow.'),
  (590, 'en', 'Sitting Calf Raises', 'Sit on a bench for calf raises and check that the feet are half free and that you can completely stretch the calf muscles down. Pull your calves up, going as far (up) as you can. Make at the highest point a short pause of 1 or 2 seconds and go down.'),
  (590, 'ru', 'Подъём на носки сидя', null),
  (591, 'en', 'Sit-ups', 'Sit on a mat, your calves are resting on a bench, the knees make a right angle. Hold your hands behind your neck. Go now up with a rolling movement of your back, you should feel how the individual vertebrae lose contact with the mat. At the highest point, contract your abs as much as you can and hold there for 2 sec. Go now down, unrolling your back.'),
  (591, 'ru', 'Подъём корпуса из положения лёжа', null),
  (595, 'en', 'Skipping - Standard', 'Do a single, double footed jump for each swing of the rope.
Work on a smooth, rhythmical movement, bouncing lightly on the balls of your feet.'),
  (598, 'en', 'Smith Machine Close-grip Bench Press', 'Perform a standard bench press on the smith machine, but have your hands on the bar about shoulder width apart, and keep your elbows close to your body.'),
  (599, 'en', 'Snatch', 'Stand with your feet at hip width and your shins against the bar. Grasp the bar at double shoulder width and, keeping your lower back flat, drive your heels into the floor to begin lifting the bar. When it''s above your knees, explosively extend your hips and shrug your shoulders. Let the momentum carry the weight overhead.'),
  (599, 'ru', 'Рывок', null),
  (604, 'en', 'Speed Deadlift', 'Deadlift with short (less than one 1min) rest between sets.'),
  (607, 'en', 'Splinter Sit-ups', 'Lie on your back with your legs straight and arms at your sides, keeping your elbows bent at 90 degrees. As you sit up, twist your upper body to the right and bring your left knee toward your right elbow while you swing your left arm back. Lower your body to the starting position, and repeat to your right. That''s 1 rep.'),
  (614, 'en', 'Squat Jumps', 'Jump wide, then close'),
  (614, 'ru', 'Выпрыгивания из приседа', null),
  (615, 'en', 'Squats', 'Place a barbell in a rack just below shoulder-height. Dip under the bar to put it behind the neck across the top of the back, and grip the bar with the hands wider than shoulder-width apart. Lift the chest up and squeeze the shoulder blades together to keep the straight back throughout the entire movement. Stand up to bring the bar off the rack and step backwards, then place the feet so that they are a little wider than shoulder-width apart. Sit back into hips and keep the back straight and the chest up, squatting down so the hips are below the knees. From the bottom of the squat, press feet into the ground and push hips forward to return to the top of the standing position.'),
  (615, 'ru', 'Приседания', 'При выполнении приседаний можно варьировать положение ног, но обычно рекомендуют ставить носки врозь, а ноги примерно на ширине плеч. Хват грифа должен выполняться всей кистью, его нельзя держать одними пальцами или прижимать ладонью к плечам. Спина должна держаться прямо, не округляться (держать поясницу «лодочкой»), корпус нельзя слишком наклонять вперёд; чтобы помочь держать спину прямо, рекомендуется смотреть прямо перед собой или немного вверх. Носки должны быть слегка развёрнуты в стороны, чтобы колени и носки смотрели строго в одном направлении, позволяя предотвратить излишнюю нагрузку на связки коленных суставов, то есть при вставании нельзя сильно сдвигать колени внутрь или разводить их наружу. Подошвы ступней не должны отрываться от пола, что наблюдается у начинающих атлетов. В начальной фазе упражнения делается вдох, в конечной фазе — выдох.'),
  (616, 'en', 'Squat Thrust', 'The burpee, or squat thrust, is a full body exercise used in strength training and as an aerobic exercise. The basic movement is performed in four steps and known as a four-count burpee: Begin in a standing position. Move into a squat position with your hands on the ground. (count 1) Kick your feet back into a plank position, while keeping your arms extended. (count 2) Immediately return your feet into squat position. (count 3) Stand up from the squat position (count 4)'),
  (621, 'en', 'Standing Bicep Curl', 'Stand holding dumbbells at shoulder width apart. Face forearm upward and keep upper arm still while raising each dumbbell up to your shoulder.'),
  (622, 'en', 'Standing Calf Raises', 'Get onto the calf raises machine, you should able to completely push your calves down. Stand straight, don''t make a hollow back and don''t bend your legs. Pull yourself up as high as you can. Make a small pause of 1 - 2 seconds and go slowly down.'),
  (622, 'ru', 'Подъём на носки стоя', null),
  (623, 'en', 'Standing Rope Forearm', 'Grab a wrist roller tool with both hands while standing with your feet about shoulder width apart. If your gym does not have a wrist roller tool, you can easily put one together. All you need is a 5 or 10 pound weight plate, a strong thin rope about 3 feet long and a 6-8 inch stick or bar. Securely fasten the rope to the middle of the bar/stick and tie the other end of the rope to the weight plate. To begin this exercise, grab the bar/stick with both hands using an overhand grip. Extend both arms straight out in front of you, parallel to the floor. Next, roll the weight up from the floor by rapidly twisting the bar/stick with your hands and wrists. Once the weight reaches the top, slowly lower the plate back to the floor by reversing the motion of your hands and wrists. Repeat (if you can!).'),
  (624, 'en', 'Stationary Bike', 'Ride a Stationary Bike with various tensions.'),
  (627, 'en', 'Stiff-legged Deadlifts', '• Keep legs straight
• Keep back straight'),
  (627, 'ru', 'Становая тяга на прямых ногах', null),
  (628, 'en', 'Straight-arm Pull Down (bar Attachment)', 'Use the straight bar attachment on a high pulley. Grasp the two ends of the bar with your palms facing downward and your arms straight out in front of you. Pull your hands down towards your hips, while keeping your arms straight, then raise them back up to the starting position.'),
  (629, 'en', 'Straight-arm Pull Down (rope Attachment)', 'Use the rope attachment on a high pulley. Grasp the two ends of the rope with your arms straight out in front of you. Pull your hands down towards your hips, while keeping your arms straight, then raise them back up to the starting position.'),
  (630, 'en', 'Sumo Deadlift', '• Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.
• Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.
• As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.
• Return the weight to the ground by bending at the hips and controlling the weight on the way down.'),
  (630, 'ru', 'Становая тяга сумо', null),
  (632, 'en', 'Sumo Squats', 'Stand with your feet wider than your shoulders, with your toes pointed out at a 45 degree angle and barbell on your shoulder.
While keeping your back straight, descend slowly by bending at the knees and hips as if you are sitting down (squatting).
Lower yourself until your quadriceps and hamstrings are parallel to the floor.
Return to the starting position by pressing upwards and extending your legs while maintaining an equal distribution of weight on your forefoot and heel.'),
  (632, 'ru', 'Приседания сумо', null),
  (636, 'en', 'Superman', 'Lay flat on your stomach with your arms extended in front of you on the ground as your legs are lying flat. Lift both your arms and legs at the same time, as if you were flying, and contract the lower back. Make sure that you are breathing and, depending on your fitness level, hold the movement for at least two to five seconds per repetition.'),
  (636, 'ru', 'Супермен', null),
  (650, 'en', 'Thruster', '• Start by doing a front squat
• At the top position, push the bar above your head (similar to a press)
• Lower the bar to the shoulders'),
  (650, 'ru', 'Трастер', null),
  (655, 'en', 'Tricep Dumbbell Kickback', '• Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.
• Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm.
• After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.
• Repeat the movement for the prescribed amount of repetitions.
Variations: This exercise can be executed also one arm at a time much like the one arm rows are performed.
Also, if you like the one arm variety, you can use a low pulley handle instead of a dumbbell for better peak contraction. In this case, the palms should be facing up (supinated grip) as opposed to the torso (neutral grip).'),
  (655, 'ru', 'Разгибание руки с гантелью в наклоне', null),
  (659, 'en', 'Triceps Extensions on Cable', 'Grab the cable, stand with your feet shoulder wide, keep your back straight and lean forward a little. Push the bar down, making sure the elbows don''t move during the exercise. Rotate your hands outwards at the very end and go back to the initial position without pause.'),
  (660, 'en', 'Triceps Extensions on Cable With Bar', 'Grab the bar, stand with your feet shoulder wide, keep your back straight and lean forward a little. Push the bar down, making sure the elbows don''t move during the exercise. Without pause go back to the initial position.'),
  (661, 'en', 'Triceps on Machine', 'Sit down and hold the bar firmly with your hands. Now press the weight upwards (don''t fully extend your arms) and lower it slowly again. As with other triceps exercises, it''s important not to move your upper arms.'),
  (672, 'en', 'Trunk Rotation With Cable', 'Seated trunk rotation with cable'),
  (674, 'en', 'Rowing with TRX band', 'Rowing with resistance bands - Bodyweight Exercise'),
  (675, 'en', 'Turkish Get-Up', 'Starting on back, move to the standing position with dumbbell in one hand. Switch hands between reps.'),
  (675, 'ru', 'Турецкий подъём', null),
  (683, 'en', 'Power Clean', 'Olympic weight lifting'),
  (683, 'ru', 'Силовое взятие на грудь', null),
  (684, 'en', 'Underhand Lat Pull Down', 'Grip the pull-down bar with your palms facing you and your hands closer than shoulder-width apart. Lean back slightly and keep your back straight. Pull the bar down towards your chest, pulling your shoulders back slightly at the end of the motion.'),
  (687, 'en', 'Overhead Press', null),
  (687, 'ru', 'Армейский жим', null),
  (688, 'en', 'Upper External Oblique', 'Exercise for upper external oblique muscles'),
  (691, 'en', 'Upright Row, on Multi Press', 'The movements are basically the same as with an SZ-bar, but you use the bar on the multi press:
Stand straight, your feet are shoulder-width apart. Hold the bar with an overhand grip on your thighs, the arms are stretched. Lift the bar close to the body till your chin. The elbows point out so that at the highest point they form a V. Make here a short pause before going slowly down and repeating the movement.'),
  (693, 'en', 'Upright Row, SZ-bar', 'Stand straight, your feet are shoulder-width apart. Hold the SZ-bar with an overhand grip on your thighs, the arms are stretched. Lift the bar close to the body till your chin. The elbows point out so that at the highest point they form a V. Make here a short pause before going slowly down and repeating the movement.'),
  (693, 'ru', 'Тяга EZ-грифа к подбородку', null),
  (694, 'en', 'Upright Row w/ Dumbbells', 'Hold a dumbbell in each hand in front of your body. Keep your palms towards your body. Lift you hands straight up until your hands are under your chin, then lower them. Repeat the exercise.'),
  (694, 'ru', 'Тяга гантелей к подбородку', null),
  (695, 'en', 'V-Bar Pulldown', 'Pulldowns using close grip v-bar.'),
  (702, 'en', 'Calf raises, one legged', null),
  (711, 'en', 'Wall Handstand', 'Handstand against a wall for support (chest facing wall).'),
  (713, 'en', 'Wall Pushup', 'Pushup against a wall'),
  (716, 'en', 'Wall Slides', 'Stand with heels, shoulders, back of head, and hips touching the wall. Start with biceps straight out and elbows at a 90 degree angle. Straighten the arms while remaining againstthe wall without arching the back off of the wall, mimicking a shoulder press movement.'),
  (718, 'en', 'Wall Squat', 'Find a nice flat piece of wall and stand with your back leaning against the wall. Slowly slide down the wall while moving your feet away from it, until your thighs are parallel to the ground and both your knees and your hips are bent at a 90° angle. Cross your arms in front of your chest and hold this position for 30 seconds.
Variant: put a big inflated rubber ball (like a small basketball) between your knees and squeeze the ball while holding the squat position'),
  (718, 'ru', 'Приседание у стены', null),
  (722, 'en', 'Weighted Step-ups', 'box step ups w/ barbell and 45''s on each side'),
  (723, 'en', 'Wide-grip Pulldown', '•
Starting position:
• Arms extended overhead, feeling a stretch in your lats.
• Keep your shoulders depressed (don’t shrug upward).
•
Pulling phase (concentric):
• Pull the bar down to your upper chest or collarbone area by driving your elbows down and back.
• Keep your chest lifted and squeeze your shoulder blades together at the bottom.'),
  (723, 'ru', 'Тяга верхнего блока широким хватом', null),
  (801, 'en', 'Dumbbell Push-Up', 'Normal Push-ups on Dumbbells, this brings a further range of movement'),
  (802, 'en', 'Barbell Lunges Walking', null),
  (802, 'ru', 'Выпады со штангой в ходьбе', null),
  (803, 'en', 'One Arm Triceps Extensions on Cable', null),
  (804, 'en', 'Sloper hanging', 'Hanging on sloper holds of a fingerboard for a amount of seconds'),
  (805, 'en', 'Tricep Pushdown on Cable', 'The cable rope push-down is a popular exercise targeting the triceps muscles. It''s easy to learn and perform, making it a favorite for everyone from beginners to advanced lifters. It is usually performed for moderate to high reps, such as 8-12 reps or more per set, as part of an upper-body or arm-focused workout.'),
  (820, 'en', 'Fingerboard 20 mm edge', 'Hang for 10 seconds on a fingerboard with a 20 mm edge'),
  (821, 'en', 'Pullup on fingerboard', 'Pullup on a choosen edge of a fingerboard / hangboard'),
  (822, 'en', 'Cable Rear Delt Fly', 'The reverse cable fly, also known as the cable rear delt fly, is a deltoid muscle strengthening and definition exercise. It’s one of the best isolation exercises for your back and posterior deltoid.This workout targets your posterior (back) deltoids while using a range of upper body muscles.
• Adjust the weight and the pulleys to the right height. You should be able to see the pulleys because they should be above your head.
• With your right hand, grab the left pulley, and with your left hand, grab the right pulley, crossing them in front of you. This is where you’ll begin your journey.
• Start the movement by moving your arms back and forth while keeping your arms straight.
• Pause at the finish of the move for a brief moment before returning the handles to their starting positions.'),
  (828, 'en', 'Incline Bench Reverse Fly', 'The incline dumbbell reverse fly is an upper-body exercise targeting the posterior or rear deltoids, as well as the postural muscles of the upper back. Because it targets such small muscles, this exercise is usually performed with light weight for high reps, such as 10-15 reps per set or more.'),
  (908, 'en', 'Zone 2 Running', 'Zone two Cardio for endurance, you should be able to speak while running'),
  (909, 'en', 'Reverse Nordic Curl', 'Natural Leg Extension is alternative to Leg Extension machine with no equipment.'),
  (910, 'en', 'Nordic Curl', 'The Nordic hamstring curl is one of the best lower-body exercises to build posterior leg strength, improve knee health, and prevent injury.'),
  (910, 'ru', 'Нордические сгибания', null),
  (911, 'en', 'Incline Skull Crush', 'Siting in a 45 Degree Angle, using DB to do Incline Skull Crush'),
  (912, 'en', 'Straight Bar Cable Curls', 'Standing upright in front of Cable Tower using a straight bar'),
  (913, 'en', 'Reverse Preacher Curl (Close Grip)', 'Sitting reverse on a Biceps Bench with a close grip'),
  (914, 'en', 'Reverse EZ Bar Cable Curls', 'Standing in front of cable tower using a SZ Bar'),
  (915, 'en', 'Bus Drivers', 'Sitting with a Weight Plate, used as wheel, in both hands; raised slightly below eye level'),
  (916, 'en', 'Smith Press', 'Sitting almost 90 degree angle, smith machine'),
  (917, 'en', 'Straight Bar Cable Front Raise', 'Back to cable tower, cable between legs, SZ Bar'),
  (918, 'en', 'Seated Dumbbell Side Lateral', 'seated slightly leaned forward at beginning of exercise'),
  (919, 'en', 'T-Bar row', 'bent over with triangle grip, slightly bent knees'),
  (922, 'en', 'Seated Cable Mid Trap Shrug', 'seated straight back, slight hold at top'),
  (923, 'en', 'Lying Dumbbell Row SS Seated Shrug', 'laying on the stomach on a bench with slight angle'),
  (925, 'en', 'Smith Machine Slight Incline Press', '* Execution * Start position:
• Unrack the bar and hold it above your upper chest with arms fully extended.
• Keep your shoulder blades retracted and pressed into the bench.
• Lowering phase (eccentric):
• Slowly bring the bar down to just below your collarbone or upper chest.
• Maintain control — don’t bounce the bar.
• Pressing phase (concentric):
• Push the bar upward in a straight line until your arms are fully extended.
• Focus on squeezing your upper chest at the top.
• Lock and repeat:
• Complete your reps, then safely rack the bar back into the hooks.'),
  (926, 'en', 'Machine chest fly', 'seated machine, straight back, slow exercise'),
  (927, 'en', 'Suspended crossess', 'Suspension exercise with trx for chest training'),
  (957, 'en', 'Quadriped Arm and Leg Raise', 'In this exercise, the back muscles and the muscles of the back of the leg and back of the arm are activated by lifting the crossed arm and leg at the same time in the crawling position. It also improves balance and proprioception. The movement is done symmetrically.
• Get into a crawling posture.2. Draw your abdomen in, then raise your right leg and left arm.3. You should keep your abdomen in for 8 seconds.4. After 8 seconds, slowly lower your arm and leg.5. Then release your muscle.'),
  (958, 'en', 'Biceps with TRX', 'Grab the handles of the TRX straps, lean your body back, arms and legs extended, with your body positioned in a single straight line. (This is an arm exercise, not an abdominal one.)'),
  (959, 'en', 'TRX Rows', 'This exercise serves as a lead-up to Pull Ups.'),
  (960, 'en', 'Kettlebell Swing', 'While kettlebell swings are a full-body workout, they mostly target the muscles along the posterior chain (back of the body). The main muscles used are the glutes, hamstrings, spinal erectors, and muscles of the upper back.'),
  (960, 'ru', 'Свинг с гирей', null),
  (961, 'en', 'Swimming 50m sprints', '50m swimming sprints at 1min'),
  (962, 'en', 'Elliptical', 'It improves muscle toning, strengthens the leg muscles (quads, glutes, calves), helps vascularisation and increases resistance. The elliptical is also very useful if you aim to lose weight. Teste'),
  (962, 'ru', 'Эллиптический тренажёр', null),
  (974, 'en', 'Curl with kettlebell two hands', 'Stand upright and grip the kettlebell with both hands. Perform the elbow flexion motion, starting from a fully extended position until your hand reaches shoulder height. Spread your legs a little for stability and, to perform the exercise correctly, try not to push with your back or body in general. Change the weight of the kettlebell to adjust the difficulty.'),
  (975, 'en', 'one-handed kettlebell curls', 'Standing with the kettlebell in one hand and bent at the elbow, start from a fully extended position until your hand reaches shoulder height. To perform the movement correctly, try not to push with your back or body.'),
  (976, 'en', 'Medicine ball booklet crunch', 'Using a medicine ball as an overload will make the exercise heavier.'),
  (977, 'en', 'Box squat', '• Set up the box: Position the box behind you, about 3 feet from a squat rack if you''re using a barbell. Choose a height that allows you to squat down and gently tap your glutes on the box with your back straight.
• Stand with proper form: Stand with your feet shoulder-width apart, toes pointed slightly outward. Engage your core and keep your back neutral. If using a barbell, rack it at shoulder height.
• Lower down: Sit back as if going to sit on a chair, bending your knees and lowering your hips towards the box. Keep your core tight and back straight throughout the movement.
• Controlled descent: Descend in a controlled manner until your glutes gently touch the box. Don''t plop down.
• Pause and press up: Briefly pause at the bottom with your back straight and core engaged. Then, press through your heels to drive yourself back up to the starting position.
Improvements in coordination, balance and endurance, toning of the leg and buttock muscles and an overall increase in bone density eliminating the risk of osteoporosis.'),
  (977, 'ru', 'Приседания на ящик', null),
  (978, 'en', 'Knee Raises', 'The 90° leg raise on the bar is a very intense exercise that involves all the abdominal muscles.'),
  (979, 'en', 'Leg raises pull up bar', 'with a firm grip with both hands on the bar, raise your outstretched legs, until you reach a 90° angle with your torso.'),
  (980, 'en', 'commando pull-ups', 'variation of the pull-up exercise, it is performed with a grip of one hand supine and one hand prone, do not twist the torso to get back to the front, the head passes once to one side, once to the other.'),
  (981, 'en', 'Step-ups', 'Starting position:
Stand facing a chair.
Steps:
• Step up onto the chair.
• Step off the chair.
• Repeat.'),
  (981, 'ru', 'Зашагивания на платформу', null),
  (983, 'en', 'High knees', 'Starting positionStand straight.
Steps:
• Run in place, putting knees as high up as is comfortable and switching legs at a quick pace.'),
  (984, 'en', 'Lunges', 'Starting position:
Stand with back straight.
Steps:
• Take a large step forward with your left leg.
• Bring your pelvis down until you almost touch the floor with your right knee.
• Bring your pelvis back up.
• Return to the starting position by stepping back.
• Repeat, switching legs each time.'),
  (984, 'ru', 'Выпады', null),
  (985, 'en', 'Push-up rotations', 'Starting position:
Get into the starting push-up position, with your hands and toes touching the ground and back, arms and legs straight. To get to this position, you can lie down on your stomach, place your hands facing down next to your head, and lifting your arms up until they are straight.
Steps:
• Perform a standard push-up:
1.a Bend arms until chest almost touches the ground, making sure the back is straight.1.b Use your arms to lift yourself back up to starting position.
• Rotate your body to the side so that the back is straight, the bottom hand supporting the body is fully extended, and only the bottom hand and foot touch the floor.
• Repeat, changing sides at step 2 each time.'),
  (986, 'en', 'Side split squats left', 'Starting position:
• Stand tall and take a wide lateral stride, just greater than shoulder width.
Steps:
• Bend one knee until your thigh is parallel to the floor. The bent knee must be in line with the foot.
• Push back to the starting position.
• Repeat.'),
  (987, 'en', 'Side split squats right', 'Starting position:
• Stand tall and take a wide lateral stride, just greater than shoulder width.
Steps:
• Bend one knee until your thigh is parallel to the floor. The bent knee must be in line with the foot.
• Push back to the starting position.
• Repeat.'),
  (988, 'en', 'Bulgarian split squats left', '• Stand tall in front of a chair and take a large step. Put the upper part of one of your feet on the chair.
• Bend the front knee, balancing with arms until the back knee almost touches the ground.
• Push back to the starting position and repeat.'),
  (989, 'en', 'Bulgarian split squats right', '• Stand tall in front of a chair and take a large step. Put the upper part of one of your feet on the chair.
• Bend the front knee, balancing with arms until the back knee almost touches the ground.
• Push back to the starting position and repeat.'),
  (990, 'en', 'Kneeling kickbacks', 'Starting position:
Get down on all fours.
Steps:
• Push one foot back until fully extended, concentrating on the gluteus muscles.
• Stay for one second, then return to the initial position.
• Repeat, alternating feet.'),
  (991, 'en', 'Split squats left', 'Starting position:
Stand with your back straight. Take a large step forward with your left leg.
Steps:
• Bring your pelvis down until you almost touch the floor with your right knee.
• Bring your pelvis back up.
• Repeat.'),
  (992, 'en', 'Split squats right', 'Starting position:
Stand with your back straight. Take a large step forward with your right leg.
Steps:
• Bring your pelvis down until you almost touch the floor with your left knee.
• Bring your pelvis back up.
• Repeat.'),
  (993, 'en', 'Jump rope: basic jumps', 'Starting position:
Put your feet close together, bend the knees a bit, keep your head and body straight, keep elbows in, open your arms.
Steps:
• Spin only your wrists with enough force to make the rope spin.
• Jump just high enough to pass the rope below your feet.
• Repeat.
Notes:
This exercise requires a jump rope. Make sure the rope length is adjusted to your height. One way to check is to grab both handles with one hand and stand on the middle of the rope hanging on the ground with one foot. If the rope (excluding the handles) reaches just below your chest, its length is right. A shorter rope would be hazardous, as you might hit yourself, and a longer rope would make for bad form.'),
  (993, 'ru', 'Скакалка: базовые прыжки', null),
  (994, 'en', 'Forward arm circles', 'Starting position:
Stand tall with your back straight.
Steps:
• Keeping your arms straight, bring them in front of you, move them down, behind your back, then over your head, and back to the initial position.
• Keep circling your arms as described in step 1.'),
  (995, 'en', 'Backward arm circles', 'Starting position:
Stand tall with your back straight.
Steps:
• Keeping your arms straight, bring them in front of you, raise them over your head, then continue the motion behind your back and down to the initial position.
• Keep circling your arms as described in step 1.'),
  (996, 'en', 'Mountain climbers', 'Starting position:
Start in the upright push-up position, aka. the high plank position.Hands should be directly under your shoulders.Keep your head in line with your back, facing the floor.Feet should be about hip-width apart.
Steps:
• Move one knee toward the center of your body, towards your elbows, keeping the other leg extended.
• In a quick jumping movement, straighten the bent leg out and pull the other knee toward your body.
• Keep repeating step 2, alternating legs.
Notes:
Throughout the exercise, your back should remain as straight as possible – avoid a hump or a sagging back.'),
  (996, 'ru', 'Скалолаз', null),
  (997, 'en', '4-count burpees', 'Starting position:
Stand straight, feet hip-width apart.
Steps:
• Squat low and support yourself on the floor with your hands between the knees and in front of your feet, your back straight.
• Keeping your hands on the floor, jump your legs backward into high plank position.
• Jump your feet forward to return to the squat position.
• Repeat.'),
  (998, 'en', 'No push-up burpees', 'Starting position:
Stand straight, feet hip-width apart.
Steps:
• Squat low and support yourself on the floor with your hands between the knees and in front of your feet, your back straight.
• Keeping your hands on the floor, jump your legs backward into high plank position.
• Jump your feet forward to return to the squat position.
• Jump up.
• Repeat.'),
  (999, 'en', 'Reverse lunges', 'Starting position:
Stand straight, feet hip-width apart.
Steps:
• Step backward with one leg so it can bend comfortably to a 90 degree angle.
• Slowly bend both knees to form 90 degree angles.
• Return to the starting position.
• Repeat, alternating legs.'),
  (999, 'ru', 'Обратные выпады', null),
  (1000, 'en', 'Floor dips', 'Starting position:
Sit with your arms behind you, supporting your back.Your fingers should point forward.Your knees should be bent, feet together.
Steps:
• Raise your hips off the ground, straightening your arms.
• Bend your elbows, bringing your hips down.
• Straighten your arms, returning to the previous position.
• Repeat steps 2 and 3.
Notes:
The exercise''s difficulty depends on how high you bring your hips.'),
  (1001, 'en', 'High plank', 'Starting position:
Get into the high plank position:your hands and toes should be touching the ground, your back, arms and legs should be straight.To get to this position, you can lie down on your stomach, place your hands facing down next to your head, and lifting your arms up until they are straight.
Steps:
• Maintain the starting position for the entire duration of the exercise.'),
  (1002, 'en', 'Child''s pose', 'Starting position:
Start on all fours, knees, toes, and hands touching the ground. Your two big toes should be touching.
Steps:
• Move your knees so that they''re about hip-width apart.
• On an exhale, move your pelvis back to sit on your heels. Your hands should still be touching the ground.
• Relax your upper body, lowering your forehead to the floor and letting your hands move forward naturally.
• Stay in this pose.
Tips:
• To leave the pose, walk your arms back under your shoulders and move your upper body up into a seated position.'),
  (1003, 'en', 'Kettlebell deadlifts', 'Starting position:
Stand hip-width apart, with your kettlebell centered between your ankles. Your back should be straight, your head facing forward.
Steps:
• Hinge at the hips and slightly bend at the knees to put your hands on the kettlebell handles. Your back should be straight as you perform the movement.
• Grab the kettlebell handles, with your hands pushing in opposite directions as if to pull the handle apart.
• While contacting your abs and glutes, stand straight up.
• Hinge at the hips again to bring the kettlebell back down, similarly to step 1.
• Repeat from step 3.
Tips:
• Be sure you''re performing the movements correctly, as doing otherwise can lead to injury. For example, do not squat instead of hinging at the hips, do not round your back while reaching for the kettlebell, and do not lean back while standing up.'),
  (1004, 'en', 'Forward shoulder rotation', 'Starting position:
Sit or stand with your back straight.
Steps:
• Place your hands on your shoulders.
• Repeatedly rotate both shoulder joints in a circular motion at a moderate pace.'),
  (1005, 'en', 'Backward shoulder rotation', 'Starting position:
Sit or stand with your back straight.
Steps:
• Place your hands on your shoulders.
• Repeatedly rotate both shoulder joints in a circular motion at a moderate pace.'),
  (1006, 'en', 'Chin tuck', 'Starting position:
Sit or stand with your back straight.
Steps:
• Use fingers on your chin to slowly tuck your chin in, moving your head back to align it with your spine.
• Hold for 5 seconds.
• Go back to normal head position and repeat.'),
  (1007, 'en', 'Head turns', 'Starting position:
Sit or stand with your back straight and shoulders down.
Steps:
• Sit or stand up straight, shoulders dropped.
• Turn your head to the side as far as possible. Stop when you hit a barrier and hold for 5 seconds.
• Return to center position and repeat, changing sides.'),
  (1007, 'ru', 'Повороты головы', null),
  (1008, 'en', 'Left neck stretch', 'Starting position:
Sit or stand with your back straight.
Steps:
• Tilt your head to the side.
• Take the hand closer to your head and use it to grab your head from the other side.
• Push with your hand against your head and with your head against your hand so that the forces balance out and your head stays still.
• Maintain this tension until the end of the exercise.'),
  (1009, 'en', 'Right neck stretch', 'Starting position:
Sit or stand with your back straight.
Steps:
• Tilt your head to the side.
• Take the hand closer to your head and use it to grab your head from the other side.
• Push with your hand against your head and with your head against your hand so that the forces balance out and your head stays still.
• Maintain this tension until the end of the exercise.'),
  (1010, 'en', 'Back neck stretch', 'Starting position:
Sit upright on a chair or a firm pillow.
Steps:
• Breathe out and tilt your head forward, chin to chest, putting hands behind your head.
• Use your hands to pull your head down lightly and press against your hands with your head to balance out the force.
• Hold for a bit.
• Relax your arms and head, opening up a bit with your shoulders.
• Keep repeating this from step 2 onward.'),
  (1011, 'en', 'Front neck stretch', 'Starting position:
Sit or stand with your back straight.
Steps:
• Open mouth wide.
• Slowly tilt head back with mouth opened. If you feel the need for support, clasp your hands behind your head.
• Very slowly close and open your mouth.
• At the end, slowly return to starting position and close mouth.'),
  (1012, 'en', 'Alternating bicep curls', 'Starting position:
Start standing up with dumbbells in each hand, your back straight and feet hip-width apart. Your arms should be relaxed, pointing down. Your knees should be slightly bent, your abs contracted, and your shoulders down.
Steps:
• Bend one arm at the elbow, bringing the dumbbell up to your shoulder. Your upper arm should remain motionless during this movement.
• Bring the dumbbell back down until your arm is in its original relaxed position.
• Repeat, switching arms.'),
  (1013, 'en', 'Left levator scapulae stretch', 'Starting position:
Start standing up or sitting down. Turn your head to the left, around 45 degrees or just above your nipple. Place your right hand behind your back or sit on it. Take your left hand and use it to hold the back of your head. Lean your head down slightly.
Steps:
• After assuming the starting position, press your head against your left hand with slight force. Your hand should press back with equal force, so that your head doesn''t move. Hold this position.'),
  (1014, 'en', 'Right levator scapulae stretch', 'Starting position:
Start standing up or sitting down. Turn your head to the right, around 45 degrees or just above your nipple. Place your left hand behind your back or sit on it. Take your right hand and use it to hold the back of your head. Lean your head down slightly.
Steps:
• After assuming the starting position, press your head against your right hand with slight force. Your hand should press back with equal force, so that your head doesn''t move. Hold this position.'),
  (1015, 'en', 'Clockwise neck circles', 'Starting position:
Start sitting or standing. Drop your head down, bringing your chin toward your chest, but not pushing.
Steps:
In a slower fluid motion and with your head relaxed and not pushing in any direction:
• lean toward your right shoulder.
• then bring your head back, facing up.
• then lean toward your left shoulder.4.and back toward the starting position.
Keep repeating this as part of one slower fluid motion.'),
  (1016, 'en', 'Counterclockwise neck circles', 'Starting position:
Start sitting or standing. Drop your head down, bringing your chin toward your chest, but not pushing.
Steps:
In a slower fluid motion and with your head relaxed and not pushing in any direction:
• lean toward your left shoulder.
• then bring your head back, facing up.
• then lean toward your right shoulder.4.and back toward the starting position.
Keep repeating this as part of one slower fluid motion.'),
  (1017, 'en', 'Neck half circles', 'Starting position:
Start sitting or standing. Lean your head against one of your shoulders, but don''t push.
Steps:
In one slower fluid motion and with your head relaxed and not pushing in any direction:
• bring your head down toward your chest.
• then lean back aganst your other shoulder.
• then back toward the chest again.4.and finally toward the starting position.
Keep repeating this.'),
  (1018, 'en', 'Head tilts', 'Starting position:
Sit or stand with your back straight.
Steps:
• Tilt your head to one side and hold for a bit.2.Return your head to neutral position and hold for a bit.
• Tilt your head to the other side and hold for a bit.
• Return your head to neutral position yet again and hold for a bit.
• Repeat.'),
  (1019, 'en', 'Side plank right', 'Starting position:
Lie down on your side, with your bottom elbow at a right angle, arm sticking out. Lift your pelvis off the floor by lifting your bottom shoulder up, keeping the forearm on the floor; your head, pelvis, and feet should be in a straight line.
Steps:
• Hold this position.'),
  (1020, 'en', 'Pistol squats right', '• Stand on one leg, with your other leg straight and slightly forward.
• Bend one knee slowly, descending into a squat and keeping your back and your other leg straight.
• Slowly raise yourself from the squat, straightening the bent knee and keeping the other leg straight.
• Repeat.'),
  (1021, 'en', 'Calf raises, right leg', '• Stand on the floor or on the edge of a step to increase the range of movement.
• Raise one foot.
• Lift your heel until you''re standing on your toes.
• (variable) Stay in this position for three seconds
• Slowly lower your foot until you almost touch the ground with your heel - don''t slam your foot!'),
  (1022, 'en', 'Single Arm Plank to Row', 'Start position as row, extend to plank and back. Finish with row and repeat'),
  (1027, 'en', 'Elevated prayer stretch', 'Starting position:
Kneel in front of a bench, far enough so that your torso can fit between your knees and the bench. With your back straight, place your elbows on the bench, with palms together, hands pointing up.
Steps:
• On exhale, stretch your chest down toward the floor without moving your lower back. At the same time, bring your hands toward your shoulders, keeping palms together and elbows on the bench.
• Hold for a few seconds.
• On inhale, relax your back to return to the starting position.
•
• Repeat.'),
  (1028, 'en', 'Quadruped thoracic rotation left', 'Starting position:
Start kneeling on all fours, knees shoulder-width apart. Place your left hand behind your head while keeping your right hand outstretched and touching the floor.
Steps:
• On inhale, move your left elbow toward your right hand, keeping your left hand behind your head.
• On exhale, move your left elbow to point up toward the ceiling.
• Repeat.'),
  (1029, 'en', 'Quadruped thoracic rotation right', 'Starting position:
Start kneeling on all fours, knees shoulder-width apart. Place your right hand behind your head while keeping your left hand outstretched and touching the floor.
Steps:
• On inhale, move your right elbow toward your left hand, keeping your right hand behind your head.
• On exhale, move your right elbow to point up toward the ceiling.
• Repeat.'),
  (1080, 'en', 'Hindu Pushups', 'Exercise to strengthen the shoulders and pectorals. Its name is due to the fact that it begins in the Yoga position "Dog Facing Down", passing to "Cobra" but without resting the legs or torso on the ground to finally end with a normal flexion. The exercise can also be performed backwards (back to the starting position). As a variation, after doing the push-up, the hip can be raised to return to downward facing dog.'),
  (1081, 'en', 'Shoulder dislocates', 'Starting position:
Stand up with your back straight and a resistance band, towel, or broomstick handle in hand. With your hands straight in front of your body and the band between your hands, push your hands apart to both be at around 45 degrees from your body, thumbs facing down. If using a towel or broomstick handle instead, grab it with an overhand grip.
Steps:
• Keeping your arms outstretched, rotate at the shoulders to bring your arms overhead and then down toward your glutes.
• Rotate at the shoulders in the opposite direction — overhead and then toward your groin.
• Repeat.'),
  (1082, 'en', 'Bent over row to external rotation', 'Starting position:
Stand behind a chair or in front of a table. Bend at the waist to put your forehead on the chair''s headrest or table, keeping your back straight. Your arms should be hanging straight down, pointed at the floor.
Steps:
• Bring your elbows up to shoulder height. Your forearms should be pointing down, perpendicular to your biceps. Your biceps should be at the same height as your back and perpendicular to your spine.
• Hold for a bit.
• Rotate at your elbows to bring your hands as far up as you can.
• Hold for a bit.
• Rotate at your elbows back to the previous position.
• Bring your arms down to the original position.
• Repeat.'),
  (1083, 'en', 'YWTs', 'Starting position:
Lie down, preferably on a mat. Stretch your arms above your head in a "Y" position (arms pointing up diagonally at around 45 degrees). Your thumbs should be pointing up.
Steps:
• With arms in the Y position, lift your chest slightly from the ground, creating a pull tension in your arms upward.
• Hold this position for several seconds (15–30 is ideal).
• Keeping your chest up, bend at your elbows to move from a Y position to a "W" position, with arms bent at the elbows and maintaining the upward tension.
• Hold for around as long as with the Y position.
• Still with your chest up, move to a "T" position, straightening your arms out to the side to be perpendicular to your body.
• Hold for around as long as you held the W position.
• Move from the T position to the W position, then from the W position to the Y position.
• Repeat.'),
  (1084, 'en', 'Dumbbell Floor Press', 'Grab your dumbbells and lay flat on your back with your knees bent and your feet flat on the ground (use a bench if you have one). Press the weights up, locking out your elbows (A). Lower them slowly until your upper arms are resting on the floor (B) close to your body. Pause here before explosively pressing back up. Squeeze your chest hard and repeat.'),
  (1086, 'en', 'Close-grip Press-ups', 'Drop into a strong plank position, bringing your hands close together until they''re almost touching. (picture 1)Bend your elbows to slowly bring your chest to the floor (picture 2). Keep your elbows close to your body as you push back up explosively. Repeat. Ensure you take your time lowering on each rep, keeping your form sharp.'),
  (1087, 'en', 'Dumbbell Hang Power Cleans', 'On your feet, stand tall with your dumbbells, holding them at your sides. Hinge at the hips to lower them to your knees (picture 1). Stand back up with a slight jump, using the momentum to pull the dumbbells up on to your shoulders (picture 2). Stand up straight, then lower under control to your sides and repeat. Keep this fast and explosive; if your heart rate doesn’t hit the roof, you’re doing them wrong.'),
  (1088, 'en', 'Dumbbell sumo deadlift', 'Lower your dumbbell to the ground between your legs. Assume a wide stance and with a straight back squat down. With the dumbbell standing upright, grip it by the top of the ‘head’ (picture 1).Keeping your chest up and core braced, push the floor away, driving back upwards to a standing position (picture 2). Repeat. If you can easily achieve 20-30 reps, use two dumbbells.'),
  (1089, 'en', 'Medicine ball twist', 'In a seated position, the torso is rotated from side to side without forcing, approaching the knees and making the ball touch the ground from time to time'),
  (1090, 'en', 'Vpushup', 'Lift your body off the ground by pushing your arms upwards'),
  (1091, 'en', 'Plank Shoulder Taps', 'In the correct plank position, place your feet slightly wider than shoulder-width apart. alternately lift and touch the opposite shoulder with one hand.'),
  (1092, 'en', 'Bag training', 'Bag training improves muscle definition of: deltoids; rear deltoids; triceps; biceps, as well as being a great cardio exercise'),
  (1093, 'en', 'Rowing Machine', 'Sit on a rowing machine with your back straight.'),
  (1093, 'ru', 'Гребной тренажёр', null),
  (1094, 'en', 'Seated Bench Press', 'Set up the chest press machine so that the grips are aligned with your lower chest when you sit down. Make sure you''re sitting with your back flat against the seat. Grab a handle in each hand, stick your chest out, and keep your head against the headrest. Breathe deeply and slowly push the handles forward until your arms are almost fully extended. Pause just before the lockout, then slowly return the handles to the starting position. Pause just before the handles come to a complete stop and perform another repetition.'),
  (1096, 'en', 'Abduction while standing', 'Training a stable stance, predominantly on one leg, is crucial for both sides. On the one hand, it prevents discomfort and, on the other, it establishes a stable foundation. The practitioner assumes the usual standing position and, with a stable upper body, attempts to repeatedly lift the unloaded leg, bend it at the hip and knee, and then lower it again. The movement is also repeated on the other side. The exercise trains the stability of the hip-surrounding muscles.'),
  (1098, 'en', 'Seated rear delt rise', 'Seated, bent 45 deg forward. Arms fully stretched out, raise arms up to shoulder height and back down'),
  (1099, 'en', 'Dynamic side hold', 'Sling a rubber band on a kettlebell and lift the kettlebell by the rubber band. Let it hang by your side and stand on one leg, switch leg while continuing hold. Repeat with other hand'),
  (1100, 'en', 'Wall balls', 'Get a medicine ball, shoulder width stance, squat, thrust the ball as high as possible against the wall and catch'),
  (1101, 'en', 'Horizontal traction isometry', 'Perform a timed isometric pull-up on the bar'),
  (1102, 'en', 'Alternate back lunges', 'The posterior muscles of the buttocks, hamstrings, soleus and gastrocnemius are trained more'),
  (1103, 'en', 'walking bridge', 'from a standing position with knees slightly bent and hands resting on the floor. From here, proceed forward with your hands keeping your buttocks contracted and without losing control of your lower back.'),
  (1104, 'en', 'Walking', 'Walking outdoor or indoor, try keeping a pace of at list 100 steps per minute.'),
  (1104, 'ru', 'Ходьба', null),
  (1105, 'en', 'Seated Knee Tuck', 'Sit on floor or mat. Place arms slightly behind you. Raise legs. Now extend your legs and pull them back.'),
  (1109, 'en', 'Cable Concentration Curl', 'The concentration curl is a classic exercise for building the biceps one arm at a time. It can be performed bent over or kneeling, but is more often performed seated on a bench. It''s great for emphasizing the biceps peak and is often used to finish a biceps workout'),
  (1111, 'en', 'Push-Ups | Incline', 'Inclined push-ups primarily target the chest muscles (pectoralis major and minor), but also work the triceps, shoulders, and core to a lesser extent. Because the upper body is elevated, the incline push-up places less emphasis on the triceps compared to regular push-ups, which may be beneficial for individuals looking to specifically target their chest muscles.'),
  (1112, 'en', 'Push-Ups | Decline', 'Decline push-ups are another modified version of the traditional push-up that target the upper body muscles in a different way. To perform a decline push-up, elevate your feet on an elevated surface, such as a bench, chair, or step, while placing your hands on the ground in a push-up position. Lower your body towards the ground while maintaining a straight line from your shoulders to your ankles, and then push back up to the starting position.
Unlike the inclined push-up, the decline push-up places more emphasis on the shoulders and triceps, while still engaging the chest muscles to a lesser extent. By elevating your feet, you increase the difficulty of the exercise by placing more weight on your upper body, forcing your shoulders and triceps to work harder to push your body back up. The decline push-up can be a great way to challenge your upper body strength and improve your ability to perform other push-up variations. As with any exercise, be sure to use proper form and start with a height that is appropriate for your strength and fitness level.'),
  (1113, 'en', 'Push-Ups | Parallettes', 'Parallettes push-ups are a variation of the traditional push-up that are performed with the hands on parallel bars, known as parallettes. To perform a parallettes push-up, assume a push-up position with your hands on the parallettes and your feet on the ground. Lower your body towards the ground while keeping your elbows close to your sides, and then push back up to the starting position.
Parallettes push-ups place more emphasis on the chest and shoulders compared to traditional push-ups, as they allow for a greater range of motion in the shoulder joint. This increased range of motion can also help to improve shoulder stability and mobility. Additionally, parallettes push-ups engage the core muscles more than traditional push-ups, as the instability of the parallettes requires greater activation of the core muscles to maintain proper form.
The added challenge of balancing on the parallettes also requires greater upper body strength and control, making parallettes push-ups a more advanced variation of the traditional push-up. They can be a great way to challenge yourself and add variety to your upper body workout routine. As always, be sure to use proper form and start with a level that is appropriate for your strength and fitness level.'),
  (1114, 'en', 'Rest (for timed workouts)', 'When creating a workout based on time, add this to add rest time in the program'),
  (1115, 'en', '3D lunge warmup', 'As a warmup, use light dumbbells, one in each hand. Lunge in alternating directions, forward, sideways, backwards and 45 degree angles.'),
  (1116, 'en', 'Dumbbell farmer''s carry', 'Grab half your body weight in each hand and walk.'),
  (1116, 'ru', 'Прогулка фермера с гантелями', null),
  (1117, 'en', 'Seated Cable Row', '• Take a seat on the machine with your feet planted, a little wider than shoulder width. Drive the heels, and squeeze the glutes. Grab onto the cable handle.
• Sit up tall with a slight bend through the knees. Tighten up the abs and low back to maintain a perpendicular angle to the floor with your torso.
• Roll the shoulders back and down. Squeeze them together as you row, thinking about pinching a pencil in between them. As you do this, pull the handle back towards you, landing right above your belly button.
• Pause here for a moment before returning the handle, still squeezing the shoulder blades. Once you''ve returned the weight to the stack, then allow the shoulder blades to relax, without pulling the torso forward.
• Repeat the movement.'),
  (1117, 'ru', 'Тяга нижнего блока сидя', null),
  (1119, 'en', 'Remo maquina agarre estrecho', 'Remo en máquina con barra en agarre estrecho'),
  (1120, 'en', 'Remo maquina agarre estrecho supino', 'Remo en máquina o polea con agarre cerrado supino'),
  (1125, 'en', 'Wide-grip supinated lat pulldown', 'Downward movement
• Pull the bar down so that it passes close to your chin and touches the upper part of your chest.
• Keep the rest of your body still.'),
  (1127, 'en', 'Close-grip supinated lat pulldown', 'Downward movement
• Pull the bar down so that it passes close to your chin and touches the upper part of your chest.
• Keep the rest of your body still.'),
  (1131, 'en', 'Cable glute extension', 'This exercise lets you work the upper, or larger, part of the glutes. For that reason, it should never be missing from your routine of isolated exercises for training the glutes.
Stand in front of a cable machine and locate the low pulley. Then attach the ankle strap to work on the low pulley. As for your posture, you should stay upright at all times. Pay special attention to your back to keep it straight and avoid injury.
It is advisable to hold on to the machine for better balance. With the leg that is holding the weight of the cable, perform a slow stretch backward without bending the knee.'),
  (1132, 'en', 'Machine glute extension', 'A GHD hip extension is one of the best exercises for the glutes. While the exercise mainly targets the glutes, it is also excellent for the lower back, the calves and the hamstrings.'),
  (1136, 'en', 'Neutral-grip chest pulldown', 'The lat pulldown is an important exercise for strengthening the back and improving posture, which can contribute to a healthier life. To perform this exercise correctly and avoid injury, it is important to follow a few key steps:
•
Position yourself in front of the cable machine with your knees slightly bent and your feet on the floor.
•
Grip the cable handle with your palms facing each other and your hands shoulder-width apart.
•
Pull the handle down until it touches or comes close to your chest, holding the position for one or two seconds.
•
Slowly raise the handle back to the starting position, making sure to keep your arms and hands straight and your back straight throughout the movement.'),
  (1137, 'en', 'High-pulley pullover', 'Stand facing the machine, feet slightly apart, gripping the bar with an overhand grip, arms extended, hands shoulder-width apart.
• Keeping your back fixed and your abdominal muscles contracted, inhale and bring the bar down to your thighs while keeping your arms extended (or your elbows slightly bent).
Exhale at the end of the movement.'),
  (1138, 'en', 'Incline bench pulldown', 'Lying face down on the incline bench facing the cable machine, perform the pulldown.'),
  (1141, 'en', 'Arabesque', 'Take all your weight onto one leg and you''re going to maintain that position, keeping your hips and pelvis level the whole time. With your back in a neutral position you want to tilt yourself forward kicking your leg back up and then slowly with your glutes bring yourself back up to neutral.'),
  (1143, 'en', 'Back extensión', 'Espalda en maquina de extensión con peso'),
  (1185, 'en', 'Triceps Pushdown', 'Triceps pushdown on cable using lat bar.'),
  (1185, 'ru', 'Разгибание рук на блоке', null),
  (1186, 'en', 'One Arm Bent Row', 'One arm bent over row on cable with a machine'),
  (1188, 'en', 'Side bend', 'With a weight in one hand, extend that arm down and bend the other arm, resting your hand on your head. Now move the hand holding the weight by rotating your torso up and down.'),
  (1192, 'en', 'Alternating Biceps Curls With Dumbbell', 'Hold two dumbbells, the arms are streched, the hands are on your
side, the palms face inwards. Bend one arm at a time and bring the weight with a
fast movement up. At the same time, rotate your arms by 90 degrees at
the very beginning of the movement. At the highest point, rotate a
little the weights further outwards. Without a pause, bring the arm back down, slowly, and do the same with the other arm.
Don''t allow your body to swing during the exercise, all work is done
by the biceps, which are the only mucles that should move (pay attention
to the elbows).'),
  (1193, 'en', 'Russian Twist', '• Hold a dumbbell, barbell weight or something else that is heavy with both hands, but make sure it is not too heavy and you are able to keep in form.
• Lean back to a 45-degree angle from the floor. For an extra challenge, lift your feet off the floor.
• Rotate your arms to one side to the same level as your chest, touch the floor for a little extra challenge, and then do the same to the other side. When you''re back in your original position after doing both sides it will count as 1 rep.'),
  (1193, 'ru', 'Русские скручивания', null),
  (1194, 'en', 'Pallof Press', 'The Pallof press is an anti-rotation exercise that trains the larger and smaller muscles around the spine to resist rotation.
• Stand parallel to the cable machine or to the anchor point to the
resistance band and clasp with the handle or band with both hands.
• Make sure your torso is front on and bring your hands to the center of your chest and slowly press out.
• Slowly return your hands to the chest and repeat.'),
  (1194, 'ru', 'Жим Паллофа', null),
  (1195, 'en', 'Side Slides + Squats', 'With feet a little wider than shoulder-width apart and staying low to mimic a defensive position, you should step with their lead leg and push off with their plant leg.
After three slides, rotate your body for 180 degree on the guiding (/outer) leg and do a squat. Continue.'),
  (1196, 'en', 'Wall Drills', 'Exercises for strengthening knee and leg musculature.
• Lateral Wall Drills March - https://youtu.be/9RiTlJ6Mmek
• Lateral Wall Drills OPEN - https://youtu.be/ADRlN8-Wfdg
• Lateral Wall Drills CROSS - https://youtu.be/hGH2sj0Tzu4'),
  (1198, 'en', 'Inverted Rows', 'Maintain a straight body, retract your shoulder blades, and pull your
chest to the bar for an effective back and upper body workout.'),
  (1198, 'ru', 'Горизонтальные подтягивания', null),
  (1200, 'en', 'Tibialis raises', '• Stand up straight
• Lift the balls of your feet, resting on your heels.'),
  (1201, 'en', 'Dragon squat', 'Start standing with your feet hip-width apart. Cross your right foot behind you to the left corner and back of the room while bending both knees. Return and repeat, alternating sides. Keep your hips and shoulders forward as you cross your feet and bend your knees.'),
  (1202, 'en', 'Side Lying Hip Abduction', '• Begin by lying down on your side with your top leg straight and your bottom leg bent for support.
• Lift your top leg off the ground
• (optional) - Hold position at the top
Resources:
• 40 seconds YouTube video: https://www.youtube.com/watch?v=g9FtnmsIYgI'),
  (1203, 'en', 'Calf raises, left leg', '• Stand on the floor or on the edge of a step to increase the range of movement.
• Raise one foot.
• Lift your heel until you''re standing on your toes.
• (variable) Stay in this position for three seconds
• Slowly lower your foot until you almost touch the ground with your heel - don''t slam your foot!'),
  (1204, 'en', 'Cycling cardio session', 'Cardio session on a Technogym Bike Excite 1000 stationary bike.'),
  (1205, 'en', 'Wrist curl, dumbbells', '• Sitting on a bench, grab the dumbbell with your palms facing up
and your hands shoulder-width apart. Rest your forearms on your thighs
and allow your wrists to hang over your knees.
• Perform the movement by
curling your palms and wrists towards your face.
• (optional/variable) Pause at the top.
• Slowly return to the starting position.'),
  (1207, 'en', 'Scorpion Kick', 'Get into the push-up position with your shoulders directly above your hands and your feet hip-width apart.
Make sure that your body forms a straight line from your head to your heels.
Now pull your right knee towards your chest. While keeping your knee bent, lift your right leg as high as possible with your lower right leg pointing straight up.
Now rotate your hips so that your right foot swings over your left leg.
Continue to rotate and move your right foot towards the floor until you are forced to roll onto the outside of your left standing foot. Make sure that you do not rotate your upper body.
Now return to the starting position and repeat the exercise with your left leg.'),
  (1208, 'en', 'Prisoner Squat', 'Stand upright with your chest slightly raised, your feet hip-width apart and your toes pointing straight ahead.
Bring your hands to the back of your head with your fingers slightly interlaced and your elbows pointing to the side. Push your hips back and bend your knees, keeping your upper body as upright as possible.
Push your knees outwards, they must never point towards each other. If your upper body moves slightly forward, make sure that it does not bend. Always keep your elbows level with your ears by tensing the muscles between your shoulder blades. If you are flexible enough, you can sink down until your buttocks touch your calves.
However, make sure that you do not bend your spine.
Before this happens, reverse the movement and use your heels and glutes to push yourself upwards with so much momentum that your feet lift off briefly and you do a little hop.
If necessary, correct the position of your feet, arms and upper body before you move on to the next repetition.
Translated with www.DeepL.com/Translator (free version)'),
  (1209, 'en', 'Shoulder width three-point push-up', 'Get into a push-up position with your shoulders directly above your hands and your feet hip-width apart. Draw your belly button in towards your spine and tighten your abdominal muscles. Lift your left foot about five centimetres off the floor. Point your toes straight down. Do not move your hips. Your body forms a straight line from your head to your heels throughout the exercise. Now bend your elbows, lower your chest to the floor and push yourself back up. Repeat the exercise on the other side.'),
  (1210, 'en', 'Skydiver with arms in T-position', 'Lie on your stomach with your legs more than shoulder-width apart and your feet up. Your arms are stretched out to the side and form a T with your upper body, your palms are on the floor. Now raise your upper body, arms and legs as high as you can while keeping your body under tension. Turn your thumbs towards the ceiling and pull your shoulder blades together. While keeping your upper body and all limbs in the air, bring your legs together and then spread them again, keeping them constantly in the air. For the remaining repetitions, only move your legs open and closed.'),
  (1214, 'en', 'Front lever tuck', 'The muscles involved in the Front Lever, most subjected to stress, are mainly the extensors such as: the latissimus dorsi, the teres major, the posterior deltoid and the long head of the biceps.'),
  (1215, 'en', 'Reverse Snow Angel', 'Lay flat on your stomach with your arms extended in front of you on the ground as your legs are lying flat. Lift both your arms and move them to your side slowly. Then, move them back.'),
  (1216, 'en', 'Recruitment Pulls', 'Find a few specific edge sizes on a hangboard, get fixed underneath them with the board overhead, and pull with max effort, 1 arm at a time, for 3-5 seconds. When positioning for this get set up with a large elbow angle (120-150 degrees) and not in full extension.'),
  (1217, 'en', 'Finger Pushup', '• Hand Positioning:
• Start in a plank position with your hands directly beneath your shoulders.
• Spread your fingers wide apart, placing them firmly on the ground.
• Finger Placement:
• Gradually lift your palms off the ground, shifting the weight onto your fingers.
• Focus on distributing the load evenly across your fingertips and thumbs.
• Body Alignment:
• Maintain a straight line from head to heels to engage your core.
• Keep your body in a controlled and stable position throughout the exercise.
• Lowering Phase:
• Slowly bend your elbows, lowering your chest towards the ground.
• Ensure controlled movement, maintaining stability on your fingertips.
• Pushing Up:
• Press through your fingertips to straighten your arms, returning to the starting position.
• Emphasize the engagement of your fingers and thumbs throughout the push-up.'),
  (1218, 'en', 'knee push-ups', '• Start by kneeling on the floor, keeping your knees together. Place your hands on the floor in front of you, slightly wider than shoulder-width apart.
• Make sure your body forms a straight line from head to knees. Hands should be positioned below shoulders.
• Lower your torso towards the ground, bending your elbows while keeping your trunk stable. Keep your knees in contact with the floor.
• Push through your hands to return to the starting position. Be sure to maintain contraction of chest, shoulder and arm muscles at the top of the movement.
• Perform the desired number of repetitions, controlling the movement and maintaining good form.'),
  (1218, 'ru', 'Отжимания с колен', null),
  (1219, 'en', 'Australian pull-ups', '• Lie down under a high bar or suspension bar, positioned at an appropriate height.
• Position yourself on your back under the bar, gripping the bar with a supinated grip (palms facing you).
• Adjust your position so that your body is aligned straight from head to toe. Arms should be fully extended, shoulders stabilized, and legs aligned with the rest of the body.
• Bend your elbows and pull your chest towards the bar, contracting your back muscles. Imagine you''re trying to bring your shoulder blades together.
• Hold the contraction at the top of the movement for a moment to maximize muscle activation.
• Slowly return to the starting position, extending your elbows.'),
  (1219, 'ru', 'Австралийские подтягивания', null),
  (1223, 'en', 'Claps over the head', 'Stand with your feet shoulder width apart. Raise your arms and clap over your head'),
  (1224, 'en', 'Dumbbell drag curls', 'Hold a dumbbell in each hand with your palms facing forward. Pull your elbows back and lift the dumbbells to your chest height. Slowly lower the dumbbell and repeat the exercise.'),
  (1225, 'en', 'Dumbbell wide bicep curls', 'Hold a dumbbell in each hand with your hands slightly wider than shoulder-width apart and palms facing forward.
Bend your elbows and lift the dumbbells to your shoulders. Slowly return and repeat.'),
  (1226, 'en', 'Dumbbell bicep curl to press', 'Bend your elbows and lift the dumbbells to your shoulders.
Push the dumbbells over your head while rotating your arms to make your palms face forward. Reverse it to lower down. Repeat the exercise.'),
  (1227, 'en', 'Dumbbell rear delt row', 'Hold a dumbbell in each hand. Bend at your hips to make your back almost parallel to the floor. Let your arms hang down. Keep your arms in line with your shoulders. bend and lift your elbows out to the sides until your upper arms are parallel to the floor. Slowly return and repeat'),
  (1228, 'en', 'Dumbbell close grip bench press', 'Lie down with your back on a flat bench. Hold a dumbbell in each hand. Raise your arms towards the ceiling with your palms facing each other and dumbbells pressed together.
Slowly lower the dumbbells to your chest, then slowly push them back. Repeat the exercise.'),
  (1230, 'en', 'Triceps stretch left', 'Put your left hand on your back, use your right hand to grab your left elbow and gently pull it. Hold this position for a few seconds.'),
  (1231, 'en', 'Triceps stretch right', 'Put your right hand on your back, use your left hand to grab your right elbow and gently pull it. Hold this position for a few seconds.'),
  (1232, 'en', 'Standing biceps stretch left', 'Stand with your left arm close to a wall. Extend your left arm and put your left hand on the wall, then gently turn your body to the right.'),
  (1233, 'en', 'Standing biceps stretch right', 'Stand with your right arm close to a wall. Extend your right arm and put your right hand on the wall, then gently turn your body to the left.'),
  (1234, 'en', 'Dumbbell Single-leg Hip Thrust', 'The single-leg hip thrust is performed by placing your upper back on a weight bench, raising one leg, and extending the hip of the other leg to achieve an isolated contraction of the glute.
By working each side separately, you can fully isolate your glutes unilaterally, providing maximal training stimulus.'),
  (1238, 'en', 'Frog stand', 'Starting position:
Stand with your feet shoulder-width apart and your toes pointing forward, facing a wall or bench for support if needed.
Bend your knees into a squat position.
Place your hands on the ground in front of you, shoulder-width apart, with your fingers spread wide.
Make sure your elbows are under your shoulders and your body forms a straight line from your head to your heels.
Upward phase:
Push with your feet and hands to lift your body off the ground.
Straighten your legs and arms, keeping your body aligned.
Engage your core and glutes to maintain the position.
If needed, rest your knees on the wall or bench for assistance.'),
  (1239, 'en', 'Standing Calf Stretch', 'This stretch targets the gastrocnemius (the chief muscle of the calf of the leg, which flexes the knee and foot). It is easy to perform anywhere. All you need is a wall or a chair.'),
  (1240, 'en', 'Standing Soleus Stretch', 'This stretch targets the Soleus part of your calf. It may be performed with a wall or chair.'),
  (1241, 'en', 'Exercise Band Dorsiflexion', 'This exercise uses an exercise band. It targets the Soleus and Tibialis anterior.'),
  (1242, 'en', 'Exercise Band Plantarflexion', 'Banded plantarflexion is a great way to bridge the gap between plantarflexion range of motion and the more strenuous calf raises in weight bearing. This can help strengthen the calf muscles, load the Achilles tendon, and improve plantarflexion range of motion.'),
  (1243, 'en', 'Double Leg Calf Raise', 'The double leg heel raise is important to strengthen and create control and stability around the ankle and knee, and provide balance and control for the hip and pelvis.'),
  (1244, 'en', 'Yoga exercise: Cow-cat', 'First get into the four-footed stance. The hands are underneath the shoulders. The fingers are fanned out wide and ensure a stable stance. It is best to rest your front body weight on your thumbs and index fingers. Now place your legs hip-width apart on the yoga mat. Your thighs should be vertically below your hips. Make sure that your weight is evenly distributed between your hands and knees. Your head is an extension of your spine and you are looking down at your mat. Your back is in a neutral position. Breathe in deeply and start with the cat. With the next exhalation, round your back vertebra by vertebra. Try to pull yourself as far as possible towards the ceiling. Pull your head towards your chest and tilt your pelvis. Now inhale deeply and move into the opposite position, cow pose. Bend your back down, pull your shoulders back slightly and lift your head as far as is comfortable for you. Your gaze is directed upwards. Breathe out consciously and switch back to the cat. With the next exhalation, switch back to cow. Repeat the exercise a few times and make sure that you are in the flow.'),
  (1245, 'en', 'Front Lever', 'The front lever is a figure where the body is kept in a horizontal position parallel to the floor.'),
  (1246, 'en', 'TRX roll out', 'Hold the handles in your hands, extend your arms and keep them parallel at chest height. The movement you need to perform is to open your arms in line with your shoulders while leaning your body forward. Try not to extend your shoulders beyond 90°, and keep your abdominal muscles and glutes contracted. Muscles involved: transverse abdominis, rectus abdominis and spinal erectors.'),
  (1248, 'en', 'Ice cream maker', 'From the final phase of a pull-up, we push ourselves back with our shoulders until we reach the front lever position. From there, we pull ourselves back up to the starting position.'),
  (1252, 'en', 'Front lever pull-up', 'in the front lever position, with legs extended or easier if collected, pull by bringing the chest closer to the bar.'),
  (1259, 'en', 'TRX Obliques', '• Place your feet in the stirrups and assume a high plank with your hands directly beneath your shoulders.
• Pull your knees to your right elbow, then push them back out and to the centre.'),
  (1260, 'en', 'TRX hammer curl', 'Place the grips as if they were a continuation of the straps. We will position our arms stretched forward and our body leaning back, completely straight. The biceps muscles will activate as you bend your elbows to bring your body towards the straps. The contraction movement will end with a slight outward movement of the hands, due to the grip we are using.'),
  (1261, 'en', 'TRX gorilla biceps curl', 'We''ll stand facing the TRX straps and grab them with our fists facing each other, facing forward, with our arms fully extended at about shoulder-width apart. We''ll keep our body straight, backward, as in the previous exercises, since we''ll be lifting our body toward the TRX straps by activating our biceps. Our body will be straight, with our feet flat on the floor. This time, we''ll place our arms open to the sides and at chest height. The movement we''ll perform is a contraction toward our chest. To achieve this, we''ll bend our elbows so that, by activating our biceps, we can pull our body toward the straps.'),
  (1262, 'en', 'Trx Single Arm Bicep Curl', 'Step 1: Stand comfortably and grasp the handles of the suspension system. Step 2: Lean back resting your weight on one arm, keepng the spine neutral. Step 3: Slowly curl to pull your body weight to the up position. Supinate the arm and squeeze as you approach the end position. Step 4: Lower yourself back down and repeat.'),
  (1263, 'en', 'Back bridge', 'Lie on the floor with your back resting on the floor and your legs bent, feet flat on the floor, leaving about 20 cm between your feet and your buttocks. Your hands remain flat on the floor, pressed against your ears, with your fingers pointing toward your toes. Your elbows are bent and pointing toward the ceiling. This is the starting position. Now push your hips as high as you can, raising your body off the floor, and continue pushing through your hands, extending your elbows and knees, until your back is fully arched (lumbar bridge). Your head also comes off the floor and should be level with your elbows, looking back. This is the final position. The descent should be slow and controlled. Your spine should be in a convex curve. It''s not good to lift your back off the floor; it should remain straight. It should be well rounded. You''ll also notice a feeling of increased oxygenation in your back. After lifting off the floor, your hips should be very high, even above the level of your head. Your arms and legs should remain straight. It seems easy, but it requires a good level of flexibility. Breathing should be deep. This posture stretches the rib cage and puts pressure on the diaphragm. If the posture is performed correctly, breathing will be perfect. Never hold your breath during the exercise.'),
  (1266, 'en', 'TRX Tricep Extension', 'Attach the TRX or other suspension system overhead, having the handles hanging at chest level or slightly lower. Experiment to see what height allows you to set up in the best way.
Stand in front of the handles and grab them with your palms facing down.
Engage your abs, squeeze your glutes, take a breath and lean forward, lifting your heels off the floor. Keep your elbows straight.
Take another breath and lower yourself slowly by bending your elbows.
Go down until your elbows are at a 90-degree angle (to the point where your wrists are above your elbows). Hold the position for a moment.
Extend your arms by engaging your triceps and bring yourself to the starting position as you exhale.'),
  (1269, 'en', 'TRX dips', 'Start with the hands on the suspension trainer and feet on the ground.
Your hands should be under your shoulders with the feet slightly in front.
Lower yourself by bringing the hips between the handles and flexing the elbows.
Extend the elbows to come back to the starting position and repeat.'),
  (1270, 'en', 'Low Pulley Cable Fly', 'Adjust the cable machine: Set the pulley to the lowest setting possible.
Choose your handles: You can use neutral grip handles (palms facing each other) or straight handles depending on your preference. Neutral grip might be easier on your wrists.
Stand with proper form: Stand with your feet shoulder-width apart, knees slightly bent, and core engaged. Maintain a slight arch in your lower back throughout the exercise.
Grip the handles: Grab the handles with your chosen grip and step back a small step or two until there''s slight tension on the cables.
Initiate the movement: Keep your elbows slightly bent throughout the exercise. Imagine you''re giving someone a big hug. Squeeze your chest muscles as you bring your hands together in front of your chest.
Control the movement: Focus on squeezing your chest muscles rather than using your arms to pull the handles.
Peak contraction: Briefly hold the squeeze at the top of the movement with your hands together at chest level.
Return slowly: Slowly release the tension and return the handles back down to the starting position with your arms slightly extended but not locked out.'),
  (1273, 'en', 'Pullover', 'Doubling as a back and chest exercise, the Dumbbell Pullover can train both your pecs and lats.'),
  (1273, 'ru', 'Пуловер', null),
  (1274, 'en', 'Sitting Calf Stretch (Dorsiflexion)', 'This is a light stretch for the calf that is great for rehab.'),
  (1275, 'en', 'Plantarflexion Stretch with Band', 'This stretch is for the ankles, as well as Tibialis anterior.'),
  (1280, 'en', 'Biceps Close Grip Pull Down', 'On a lat pull down machine, hold the bar keeping your hands relatively close. Use an underhand grip (I.E.: the back of your hand must be facing the machine). Then pull down the bar in a straight line towards the ground. Make sure your biceps are the main drivers of the motion. You will probably feel your shoulders and lats working, but make sure your biceps are working more.'),
  (1282, 'en', 'Isometria trazioni impugnatura inversa', 'Trazioni in isometria con impugnatura inversa'),
  (1283, 'en', 'Incline Chest-Supported Dumbbell Row', 'Set up an adjustable bench at a 45-degree angle.
Lay on your stomach with your head hanging just above the edge of the bench.
Grab a dumbbell in each hand and set up with a good posture – core and lats engaged and shoulders neutral.
Row the dumbbells toward the top of the stomach and squeeze the back at the top of the rep.
Finally, lower the dumbbells back to the starting position and repeat until all reps are completed.'),
  (1284, 'en', 'Pseudo Planche Push-up', 'You should have the shoulder line in front of your wrists an perform a push-up, maintaining the shoulder in the same position'),
  (1285, 'en', 'Talons fesses', 'Touch your heels to your buttocks, while remaining static or moving'),
  (1286, 'en', 'Dynamic Planche', '• Start in a plank position, with your hands directly under your shoulders and your feet hip-width apart.
• Engage your core to keep your body in a straight line from head to toe.
• From this position, bend your knees slightly and jump with both feet inward, bringing them as close to your core as possible
• As soon as your feet touch the ground, push off forcefully to jump again and return to the starting plank position.
• Continue repeating this jumping motion, maintaining control and core stability throughout the exercise.
• Make sure to keep your breathing steady while jumping, breathing deeply and controlling your breathing.
• Keep your gaze fixed on the ground to maintain proper spinal alignment.
• Repeat the jumps for the desired length of time or the number of repetitions recommended for your workout program.
• To finish the exercise, rest by releasing the plank position, then stretch if necessary to loosen your muscles.'),
  (1287, 'en', 'Reach ups', 'To perform this exercise, lie on your back with your arms extended overhead. Then, contract your abdominals and lift your torso off the floor while reaching your arms toward the ceiling to "reach" as high as possible. Slowly return to the starting position, controlling the movement. Reach ups strengthen the abdominal muscles and improve the flexibility of the spine. They can be incorporated into a variety of training routines to work on core strength and stability.'),
  (1288, 'en', 'Dynamic side plank', 'The dynamic side plank involves positioning yourself on your side, supported on one elbow and the side of your foot, then dipping your hips up and down while keeping your body in a straight line.'),
  (1289, 'en', 'Seated Dumbbell Curls', 'Seated Dumbbell Curls are an effective bicep workout that isolates the muscles by stabilizing the upper body, reducing momentum that can detract from the exercise’s effectiveness. This exercise is performed sitting down with a dumbbell in each hand, focusing on controlled movement to maximize engagement of the bicep muscles.'),
  (1290, 'en', 'Reverse Grip Barbell Curls', 'Hold the barbell with an overhand grip (palms facing down) approximately shoulder-width apart. Ensure your back is straight, shoulders slightly pulled back, and arms fully extended.
Curl the barbell upwards towards your chest in a controlled motion, keeping your elbows close to your body. The motion should be smooth without any swinging or momentum use.
Once the barbell is at chest level, pause briefly to maximize contraction in the biceps and forearms.
Slowly lower the barbell back to the starting position with a controlled movement, fully extending your arms.'),
  (1292, 'en', 'Reverse-grip pull-ups', 'Pull-ups on the bar with your thumbs pointing outward.'),
  (1293, 'en', 'One armed push-ups', 'Perform push-ups with one hand, alternating the sides'),
  (1294, 'en', 'Single-leg hamstring curl', 'Specifically, the muscles involved are: biceps femoris, semimembranosus and semitendinosus.'),
  (1296, 'en', 'Low-Cable Cross-Over - NB', 'The low-cable cross-over is an isolation movement that uses a cable stack to target the upper portion of the pectoral muscles. It is common in upper-body and chest-focused muscle-building workouts, often in combination with presses or flyes from other angles to target all portions of the chest.'),
  (1298, 'en', 'High-Cable Cross Tricep Extention - NB', 'The high-cable cross tricep extension is an isolation exercise for targeting the triceps,
particularly the long head. It utilizes cables and handles grasped with opposite hands, allowing for a unique pressing motion that can be effective for building tricep strength. Unlike exercises that use a straight bar or rope, this variation can be more comfortable on your wrists and elbows'),
  (1302, 'en', 'JM Press', 'The JM press keeps your shoulders stationary, relying on the elbow flexion and extension to move the weight using your triceps strength. That means you get all the benefits of the best triceps-strengthening exercises without overtaxing that delicate shoulder joint. Classic win-win!'),
  (1303, 'en', 'Helms Row', 'Setup: Place your chest on the end of a bench, using a towel or anything soft to keep your chest protected. You want your chest to be in contact with the bench around the nipple line. Your back should be almost parallel to the floor
Execution: When you’re starting the exercise, focus on pulling your elbows back until you feel maximum tightness in the lats.
If you want to get some trap activation with the exercise, relax your shoulder blades when the weights are hanging down and then retract them as you start the rep.'),
  (1304, 'en', 'Meadows Row', 'The Meadows row is a unilateral row performed with a landmine setup, overhand grip, and staggered stance. Lean your torso forward and grip the barbell. Rest the other forearm on the forward leg. Start this movement by driving the elbow behind you while retracting the shoulder-blade. Keep the working shoulder down. Pull toward your back hip until the elbow is level with your torso.'),
  (1307, 'en', 'Front Plank', 'The plank is a bodyweight exercise. As a multi-functional movement, the plank not only targets your abdominal muscles but also the spine and hip. Plank strengthens and tightens your entire body, improves your posture and balance, reduces body fat, and can help boost your metabolism.
Exercises such as the “plank pose” help strengthen the stamina of stabilizing abdominal muscles. It can also help relieve back pain associated with a weakening of the function of the stabilizing muscles of the body.
Planks are a versatile exercise that targets many of the most important muscle groups in the body, so they can be applied by anyone to improve endurance and overall body strength.'),
  (1307, 'ru', 'Планка на предплечьях', null),
  (1312, 'en', 'Bodyweight Squat HD', 'Squat is a type of bodyweight exercise. It is one of the most popular exercises for strength and muscle growth. Squat is particularly effective for focusing on the muscles of the leg and hips.
Squat are an easy exercise for beginners to do. It can help strengthen leg muscles, tighten hip muscles and burn calories to lose weight.
It tightens the butt and legs. Squats are very effective for firming and strengthening your legs by acting on the gluteus,hip flexors, quadriceps, hamstrings and inner thigh muscles. Also, bodyweight squats can help shape your glutes and butt.'),
  (1314, 'en', 'Jumping Jack HD', 'Jumping jack are a plyometric exercise. Plyometrics are explosive aerobic moves that increase speed, quickness, and power and they work your whole body.
Jumping jack target the arm, shoulder, abdominal muscles, hip muscles and hip flexors and also work on the thighs, knee tendons and quadriceps.
Jumps are beneficial to your health because they combine cardiovascular conditioning with strength work. Since jumps elevate your heart rate, they can also improve your cardiovascular fitness.'),
  (1318, 'en', 'High Knee Skips HD', 'You can use this exercise both as a dynamic warm-up before training and add it to your cardio training routine to burn fat.
High knee skips are a plyometric exercise. Plyometrics are explosive aerobic moves that increase speed, quickness, and power and they work your whole body.
High knee skips target the oblique, leg muscles, hip muscles and hip flexors and also work on the thighs, knee tendons, quadriceps and shoulders.
Jumps are beneficial to your health because they combine cardiovascular conditioning with strength work. Since jumps elevate your heart rate, they can also improve your cardiovascular fitness.'),
  (1320, 'en', 'Bench Dips On Floor HD', 'Triceps dips on floor are a compound exercise as they worked multiple muscle groups simultaneously. Although this bodyweight exercise mainly targets the triceps, it also hits your chest and front of your shoulder.
Triceps dips on floor are one of the most effective exercises to increase arm strength and also build lean muscle in your upper arms.
Triceps dips on floor are a closed kinetic chain exercise and express that you do the movements around a fixed point. It increases compression force on your joints thereby improving stability.'),
  (1324, 'en', 'Bodyweight lunge HD', 'Bodyweight lunges are an effective calisthenic exercise for
strengthening the lower body, improving balance and stability, and
developing functional strength. They are a popular choice for bodyweight workouts, home workouts, and can also be included as part of a larger strength training routine.'),
  (1325, 'en', 'Lateral Push Off', 'Push off the ground and land on one leg and regain balance before jumping to the other leg'),
  (1333, 'en', 'Forearm Curls (underhand grip)', '• Engage the muscles
• Don''t use momentum
• Controlled movement
• Slow movement'),
  (1336, 'en', 'Triceps Overhead (Dumbbell)', '• Keep the elbows fixed
• Engage the muscles
• Don''t use momentum
• Controlled movement
• Slow movement
• Don''t overextend'),
  (1338, 'en', 'Shoulder Raise (Dumbbell)', '• Engage the muscles
• Don''t use momentum
• Controlled movement
• Slow movement
• Always keep the arms bent
• Don''t overextend'),
  (1348, 'en', 'Lower Back Extensions', '• Engage the muscles
• Lift your bottom slightly
• Controlled movement
• Slow movement
• Don''t use momentum
• Keep your upper body straight'),
  (1353, 'en', 'Dumbbell Hex Press', '• Engage the muscles
• Position your feet wide
• Controlled movement
• Slow movement
• Bring the weights toward your lower chest/stomach'),
  (1360, 'en', 'Double Kettlebell Clean and Press', 'Full-body muscles building exercise. This exercise provides a huge range of benefits in terms of strength & size and is extremely functional.'),
  (1361, 'en', 'Double Kettlebell Front Squat', 'The kettlebell front squat is a compound, multi-joint exercise that works several muscle groups.'),
  (1363, 'en', 'Blackroll', '• Controlled movements
• Slow movements
• Don''t use momentum'),
  (1366, 'en', 'Dumbbell Split Squat', '• Controlled execution
• No momentum
• Execute slowly'),
  (1370, 'en', 'Dumbbell Deadlift', '• Controlled execution
• Don''t use momentum
• Slow execution'),
  (1372, 'en', 'Triceps Dips (Assisted)', 'Assisted triceps dips is a gym work out exercise that targets triceps and also involves chest.'),
  (1373, 'en', 'box jumps', 'Jump from a standing position onto the box, stretch your body, then step down again (do not jump)'),
  (1373, 'ru', 'Прыжки на тумбу', null),
  (1374, 'en', 'Rotary Torso Machine', '• Slow and Steady
• Not too much weight'),
  (1376, 'en', 'Recumbent Bike', 'For this exercise Recumbent Bike is needed. You just sit on it, set level and time and start the workout'),
  (1377, 'en', 'Torso Twist', 'Standing Torso Twist WorkoutTarget your core and improve flexibility with this dynamic standing exercise! The Standing Torso Twist Workout involves twisting your torso while keeping your feet and hips stable, engaging your obliques, and stretching your entire upper body. This movement helps to:Strengthen core musclesIncrease flexibility in the spine and torsoImprove posture and balanceEnhance overall athletic performancePerform 3 sets of 10-15 reps, twisting to each side, to feel the benefits of this effective and efficient workout!'),
  (1378, 'en', 'Cable Lateral Raises (Single Arm)', 'The single arm cable lateral raise is a variation of the lateral raise and an exercise used to build the muscles of the shoulders.
• Position a cable at the lowest position possible and attach a single handle.
• Reach across your body and grab the handle with a neutral grip.
• Keep the elbow slightly bent and pull the handle across your body and raise laterally.
• Slowly lower the handle back to the starting position under control.'),
  (1380, 'en', 'Band pull-aparts', '• Hold the band with your arms extended in front of you at shoulder height.
• Keep your elbows slightly bent but fixed throughout the movement.
• Pull the band apart by spreading your arms until the band touches or comes close to your chest.
• Slowly bring your arms back to the starting position, controlling the tension on the band.'),
  (1381, 'en', 'Upper Back', 'Upper Back is suitable for building up the core muscles with a special focus on the deltoid and rhomboid muscles and the upper back muscles'),
  (1384, 'en', 'Pullover Machine', 'Pullover machine, sitting, elbows on pads'),
  (1387, 'en', 'Hamstring Kicks', 'Stand with your feet hip-width apart and extend one arm in front of you. Swing that leg up in front of you and back down while keeping your leg as straight as possible and your toes pointed up.Repeat with the other leg.'),
  (1388, 'en', 'Single Leg RDL', '• Stand upright and hold weights in both hands if using loads.
• Brace your core and lift one leg off the ground.
• Keep your back straight, hinge at the hips while lowering your torso forward, ensuring you don’t rotate your hips.
• Lower until you feel a stretch in your standing leg''s hamstring, then return to standing position. Repeat on both sides.'),
  (1390, 'en', 'Toe Touch', 'Stand with your feet closer together. Hinge at your hips and lower your upper body towards your toes. Reach your hands towards your feet, try to touch your toes, the ground, or as far down your legs as you can comfortably go.'),
  (1391, 'en', 'Elephant Walks', 'Hinge at your hips until you feel a stretch behind your knees. Bend one leg while the other is straight then fluidly bend the other knee while straightening the first knee.'),
  (1392, 'en', 'Good Morning', 'Stand with your feet more than shoulder-width apart (wider stance) and place your hands on your hips. Hinge at your hips and lower your upper body towards the ground while keeping your back straight then come back up.'),
  (1392, 'ru', 'Наклоны со штангой (гуд морнинг)', null),
  (1393, 'en', 'Single Leg Hamstring Stretch', 'Sit on the ground with one leg straight out in front of you and the other leg bent in toward you. Reach forward with both hands, trying to touch the toes of your straight leg.'),
  (1394, 'en', 'Sit & Reach', 'Sit on the ground with your legs extended straight in front of you. Reach both hands forward, trying to reach past your toes or as far as you can go. Return to the starting position and repeat.'),
  (1395, 'en', 'Crossbody Leg Swings', 'Hold onto a wall or something near you for support. Swing one leg across the front of your body, then back and out to the side. Repeat while slowly increasing your range of motion.'),
  (1396, 'en', 'Standing Pancake', 'Stand and open your legs as wide as possible into a straddle position. Then bend at the hips, pushing them back while keeping your back straight.'),
  (1397, 'en', 'Standing Pancake Good Morning', 'Stand with your feet wider than shoulder-width apart and toes pointed slightly outward. Place your hands on the back of your head. Hinge at your hips and lower your upper body towards the ground, keeping your back straight and chest open.'),
  (1398, 'en', 'Hamstring Chokes', 'Sit on the ground and bend one leg, bringing your knee toward you. Place your hand behind your hamstring and gently pull your leg toward your chest, feeling a stretch in the back of your thigh. Straighten your leg, extending up toward the ceiling.'),
  (1399, 'en', 'Roll Down', 'Stand with your feet hip-width apart and slowly roll your upper body forward, one vertebra at a time, until your hands touch the ground or as far as you can comfortably go. Roll back up to the starting position in the same controlled manner.'),
  (1400, 'en', 'Crossbody Hamstring Stretch', 'While standing, cross one leg behind the other (keep this leg straight). Reach downward and try to touch the toes of that leg. Slightly bend the other leg so that you can bend down.'),
  (1406, 'en', 'Plank-to-Elbow Extension', 'The Plank-to-Elbow Extension is a dynamic exercise that combines the plank with an elbow extension movement'),
  (1407, 'en', 'Cossack squat', 'The Cossack Squat is a multi-joint exercise that works mainly on the legs and buttocks, but also involves stabilizing muscles. It is an excellent exercise for improving strength, mobility and stability in a functional way.'),
  (1408, 'en', 'Wall-sit', 'The Wall Sit (or wall chair) is an isometric exercise that mainly involves the leg muscles, improving muscular endurance and stability. Here are the main and secondary muscles activated during the exercise.'),
  (1408, 'ru', 'Стульчик у стены', null),
  (1409, 'en', 'Dragon-flag', 'Keep your body completely rigid throughout the movement, avoiding sagging in your lower back.
Use a firm grip to stabilize your upper body.
Start with simpler versions (such as with bent knees) to build strength and control.'),
  (1410, 'en', 'Plank with Alternating Leg Lift', 'In a plank position, lift one leg alternately.'),
  (1411, 'en', 'Heel Touches', '•
Starting Position:
• Lie on your back on an exercise mat.
• Bend your knees, keeping your feet flat on the floor and hip-width apart.
• Place your arms along your sides, palms facing inward, just off the floor.
•
Engage Core:
• Lift your head, shoulders, and upper back slightly off the ground.
• Keep your neck neutral and chin slightly tucked.
•
Perform the Movement:
• Side-bend to the right, reaching your right hand toward your right heel.
• Return to the center, then side-bend to the left, reaching your left hand toward your left heel.
• Continue alternating sides in a controlled manner.
•
Breathing:
• Exhale as you reach toward your heel and inhale as you return to the center.'),
  (1412, 'en', 'bicycle crunches', 'Bicycle crunches are a core exercise performed on the floor. Lie on your back with your hands behind your head and legs extended. Lift your shoulders off the ground, bring one knee toward your chest, and twist your torso so your opposite elbow meets the knee. Alternate sides in a pedaling motion, ensuring controlled movements and engaging your core throughout the exercise.'),
  (1412, 'ru', 'Велосипед (скручивания)', null),
  (1414, 'en', 'Hack Squats', 'Hack squats target the lower body and are performed on a hack squat machine or with a barbell. For the machine variation, position yourself on the platform with your shoulders under the pads and feet slightly forward. Push through your heels to lift the weight, then bend your knees to lower the platform in a controlled motion until your thighs are parallel to the ground. Push back up to the starting position. For the barbell variation, hold the bar behind your legs with your arms extended and perform a squat-like motion.'),
  (1414, 'ru', 'Гакк-приседания', null),
  (1415, 'en', 'Dumbbell Crunches', 'Dumbbell crunches are a weighted variation of traditional crunches designed to target the abdominal muscles more intensely. Lie flat on your back with your knees bent and feet flat on the floor. Hold a dumbbell with both hands close to your chest or above your head. Lift your shoulders and upper back off the ground in a crunching motion, engaging your core. Slowly lower yourself back to the starting position. Ensure controlled movements throughout the exercise to prevent strain.'),
  (1424, 'en', 'Biceps Curl Machine', 'The biceps curl machine is designed to isolate the biceps muscles and provide a controlled range of motion. Sit on the machine with your back against the pad and adjust the seat so your arms are aligned with the machine''s handles or pads. Grip the handles firmly, keeping your elbows fixed in place, and curl the handles upward by contracting your biceps. Slowly lower the handles to the starting position, maintaining control throughout the movement.'),
  (1425, 'en', 'Toe Taps', 'Toe taps are a core-focused exercise performed lying on your back. Lie flat with your arms by your sides and your legs raised to a tabletop position (knees bent at 90 degrees). Slowly lower one foot to gently tap the floor, keeping your core engaged and your lower back pressed into the ground. Return to the starting position and alternate legs. This exercise strengthens the core while minimizing strain on the lower back.'),
  (1426, 'en', 'Standing Side Crunches', 'Standing side crunches are a dynamic exercise that targets the obliques while improving balance and stability. Stand upright with your feet shoulder-width apart and hands behind your head or holding a dumbbell in one hand. Lean your torso to one side, contracting your obliques, while bringing your elbow toward your hip (or crunching toward the weight if using a dumbbell). Return to the starting position and alternate sides or perform all repetitions on one side before switching.'),
  (1429, 'en', 'Dumbbell Shoulder Rotations', 'Dumbbell shoulder rotations are designed to strengthen the rotator cuff muscles and improve shoulder stability and mobility.
• External Rotation: Hold a dumbbell in one hand, keeping your elbow bent at 90 degrees and close to your body. Rotate your forearm outward, away from your body, keeping your elbow stationary. Slowly return to the starting position.
• Internal Rotation: Hold a dumbbell in one hand, keeping your elbow bent at 90 degrees and close to your body. Rotate your forearm inward, toward your body, and slowly return to the starting position. Perform the exercise with controlled movements to avoid strain.'),
  (1430, 'en', 'Plate Pinch Hold', 'The plate pinch hold is a grip strength exercise designed to target the forearms and improve grip endurance. Select one or two weight plates (smooth-edged plates work best) and pinch them together between your thumb and fingers. Hold the plates with your arm straight down by your side or extended slightly in front of you. Maintain the hold for as long as you can, keeping your shoulders relaxed and your grip firm. This exercise can be done for time or repetitions.'),
  (1433, 'en', 'Reverse Wood Chops', '• Attach a looping resistance band to a rack below knee height
• Grip the other end of the band like holding a baseball bat with both hands
• Stretch the band facing it
• Start with your hands at the side of your hips, knees bent
• Rotate your hips while moving your hands towards over the top of your opposite shoulder
• Imagine the motion as striking a baseball with a bat'),
  (1434, 'en', 'Lat Pull DB', '• Bend upper body forward
• Move dumbbells near your body with slightly bent arms towards your back'),
  (1435, 'en', 'Scapula Pulls', '• Hang straight on a pull-up bar
• Pull shoulder blades together, moving the body slightly up'),
  (1436, 'en', 'Pin Bench Press BB', '• Set security pins to about the height of your sticking point
• Lower the bar, rest on the pins for 1s while holding tension
• Move bar up with maximum force'),
  (1437, 'en', 'Pin Squat', '• Set security pins to about the height of your sticking point
• Lower the bar, rest on the pins for 2s keeping tension
• Stand up with maximum force'),
  (1438, 'en', 'Clean', 'Regular olympic lift clean.
Pull bar from ground, catch on shoulders performing a front squat.'),
  (1439, 'en', 'Pin OHP', '• Set security pins to the height of your lower chin
• Rest bar on pins keeping tension
• Raise bar over head'),
  (1440, 'en', 'Push OHP', '• Rest bar in front on your shoulders
• Bend knees while keeping upper body straight
• Extend legs pushing the bar overhead with force'),
  (1441, 'en', 'Incline OHP DB', '• Sit on a bench with 45° incline
• Ellbows 45° out
• Move dumbbells down until upper arms are parallel to shoulders
• Move dumbbells up, meeting overhead'),
  (1442, 'en', 'Kreis Press DB', '• Sit on a bench with 45° incline
• Hold dumbbells overhead
• Move dumbbells down as if doing overhead press
• Rotate dumbbells palms facing up and extend your arms in front of your body
• Move hands together until dumbbells meet, keep arms extended
• Reverse the motion until dumbbells are overhead again
• This is one repetition'),
  (1443, 'en', 'Shoulder Raise Side and Front DB', '• Stand while holding dumbbells beside body
• Keep arms almost fully extended
• Without momentum raise dumbbells to the side of your body until shoulder height, palms facing down
• Lower dumbbells beside body, palms facing inwards
• Immediately raise dumbbells in front of your body until shoulder height, palms facing down
• Down again
• This is one repetition'),
  (1445, 'en', 'Jerk OL', 'Olympic lift jerk
• Hold bar in front on shoulders like push press
• Bend and extend knees pushing bar up while diving under the bar
• Catch bar overhead with straight arms using lunge
• Move feet parallel while holding bar in lockout'),
  (1446, 'en', 'Clean and Jerk OL', 'Olympic lift clean and jerk.
Combination of clean and jerk in one motion.'),
  (1447, 'en', 'Snatch OL', 'Olympic lift snatch
• Pull barbell from ground to overhead lockout using a wide grip and overhead squat.
• Move bar slowly until cleared knees then explosively extend hips, pull bar up and dive under the bar
• Catch bar overhead with straight arms
• Push head forward during lockout'),
  (1448, 'en', 'Seated W Curl', '• Sit on bench with 60° incline
• Hold dumbbells beside body near the ground, palms facing outwards, arms fully extended
• Move dumbbells up using only biceps and without momentum'),
  (1449, 'en', 'ClimbMill', 'The ClimbMill, also known as a stair climber, is a cardio-focused machine that simulates climbing stairs. It provides an effective way to improve endurance while strengthening the lower body. To use the machine, step onto the moving stairs, maintain an upright posture, and use the handrails for balance if needed. Adjust the speed and intensity to match your fitness level. This exercise helps improve cardiovascular health, burns calories, and enhances lower body muscle endurance.'),
  (1450, 'en', 'Cobra Stretch', 'The Cobra Stretch is a back extension exercise that helps improve spinal flexibility and relieve lower back tension. To perform, lie face down on the floor with your hands placed under your shoulders. Press your palms into the floor and lift your chest while keeping your hips on the ground. Keep your elbows slightly bent and your shoulders relaxed. Hold the stretch for a few seconds, then slowly lower yourself back down. This exercise is beneficial for improving posture and reducing lower back stiffness.'),
  (1451, 'en', 'Torso rotation stretch', 'The torso rotation stretch helps improve spinal mobility and relieves tension in the lower back and obliques. It can be performed standing or seated.
• Standing Variation: Stand upright with your feet shoulder-width apart. Place your hands on your hips or extend your arms in front of you. Slowly rotate your torso to one side, keeping your hips stable. Hold for a few seconds, then rotate to the opposite side.
• Seated Variation: Sit on a chair with your feet flat on the floor. Place one hand on the outside of your opposite thigh and gently twist your torso toward that side. Hold the stretch before switching sides.'),
  (1452, 'en', 'Knee to Chest Stretch', 'The knee to chest stretch is a simple yet effective exercise for relieving lower back tension and improving hip mobility. To perform, lie flat on your back with your legs extended. Bring one knee toward your chest, wrapping your hands around your shin or behind your thigh. Gently pull the knee closer to your chest while keeping the other leg straight on the floor. Hold the stretch for 15–30 seconds, then switch sides. For a deeper stretch, both knees can be pulled toward the chest simultaneously.'),
  (1455, 'en', 'Towel Superman', 'In this exercise, you lie flat on your stomach, hold a
towel with your arms extended in front of you, and pull it apart to
create tension. Then, you move it forward and back under your stomach.
This exercise targets the back and shoulder muscles as well as core
stability.'),
  (1457, 'en', 'Cable Press Around', 'Set the cable pulley at chest height and attach a D-handle bar. Grab
the handle with a neutral grip and hold it next to your chest with your
elbow fully flexed and tight to your side. Turn away from the pulley so
your torso is at 45 degrees.
Hold the other side of the functional trainer with your corresponding hand. Assume a staggered stance for better balance.
While keeping your chest proud, extend your elbow at 45 degrees
across your midline while keeping your arm parallel to the floor. Stop
shy of lockout and contract your chest at the top of the range of motion
(ROM).'),
  (1458, 'en', 'Cross-Body Cable Y-Raise', 'Attach a D-Bar to the cable machine. Perform a motion akin to drawing a sword from across your body.'),
  (1461, 'en', 'No Leg Drive Dumbbell Chest Press', 'Set up for a normal Dumbbell chest press but lift your leg ups straight or put them on another bench to remove the leg drive.'),
  (1462, 'en', 'punches', 'stand stable and throw normal straight punches'),
  (1463, 'en', 'Dumbbell Underhand Dead Row', 'The Dumbbell Underhand Dead Row will involve the back, which means you can try a bit heavier weight. The catch is that you need to be able to control the weight for all the reps.
• Start by holding a pair of dumbbells with your feet shoulder-wide apart and your knees slightly bent.
• Hinge at your hips to lower your torse forward until it''s almost parallel to the floor, keeping your back flat and maintaining a slight bend in your knees.
• Exhale as you row the dumbbells to your sides up to chest height, leading with your elbows until your upper arms are just past parallel to the floor and the dumbbells are at ribcage level.
• Slowly lower to the starting position and repeat. Keep your back flat all the time.'),
  (1464, 'en', 'Pause Hack Squats', 'Hack Squats but with a 1-2s pause at the bottom of the movement. This makes sure that there is no more elastic energy stored in the muscles.'),
  (1465, 'en', 'Spider Curl', 'To get the most out of DB Spider Curls, you need an
adjustable weight bench set at a 45-degree incline. This inclined position
allows your arms to hang freely, putting them in an extended start position
with elbows slightly in front of your torso, which is the key to maintaining
low-level isometric tension throughout the movement pattern.
• Lie face-down on an adjustable
weight bench with your chest fully supported, holding a pair of dumbbells.
• Keep a neutral head position
and don’t crane your neck.
• Let your arms hang straight
down with your palms facing forward (for a standard Spider Curl) or palms
facing inward for a Hammer Curl exercise variation.
• Keep a stable foot position on
the floor to maintain balance and control.
• Start the curl motion by
flexing your biceps muscles and lifting the pair of dumbbells or curl bar
toward your shoulders.
• Keep your elbow flexion
controlled. Your arms should stay locked in position with no unnecessary
movement.
• Squeeze hard at the top for 1-2 seconds. This
is where maximum tension hits the biceps muscle fibers.
• Lower the weight under control
for 3-4 seconds to keep muscles under tension for the entire range of
motion.'),
  (1466, 'en', 'Calf Raise using Hack Squat Machine', 'Ideally using a trapeze addon, Lift the weight up using your calves by getting on your toes.'),
  (1467, 'en', 'Incline Close Grip Barbell Bench Press', 'Narrower grip than regular bench press, just outside shoulder width.'),
  (1468, 'en', 'Floor Skull Crusher', 'Allowing you to safely load more weight than a regular skull crusher, lie on the floor and rest the weight on the floor in between each repetition.'),
  (1469, 'en', 'Bent over Cable Flye', 'Holding your upper body at an approximate 105° angle.'),
  (1470, 'en', '1-Arm Half-Kneeling Lat Pulldown', 'Attach a D-Handle to a high pully. And use your lat muscles to pull the weight single handedly.'),
  (1471, 'en', 'Kroc Row', 'Dumbbell rows with looser technique but heavier weight.'),
  (1472, 'en', 'Cable Shrug-In', 'Attach two D-Handles to two low cables and shrug in using your upper traps.'),
  (1473, 'en', 'Reverse Cable Flye', 'Attach D-Handles to two cable pulleys in the upper position. Grab the left on with your right hand and vice-versa.'),
  (1474, 'en', 'W-Raise', 'This challenging exercise is a variation of reverse crunches that is made up of three parts in which we’re basically drawing an upside down ‘W’ with our legs.
Start position is lying face up flat on the floor with legs extended at the low point of the outer leg of the ‘W’. Keeping a strong core and legs straight, go up, rise your hips and then slowly lower your legs down halfway. Then, lifting your legs back up to the top, rise your hips again, maintaining that straight line, use your core strength to finally come back all the way down to the other outer leg of the W. Then you reverse the ‘W’ to return to the start.'),
  (1475, 'en', 'Black Widow Knee Slides', 'In
this bottom-up rotation exercise movement, you’ll cross your knee over and
drive it into that opposite elbow. Start in high plank position (or tabletop
position) with hands directly beneath your shoulders. Lift the left knee toward
the right arm and slide it up the forearm to get more of that posterior pelvic
tilt and engagement of the abdominal muscles. Then do the opposite side,
bringing your right knee toward your left hand.'),
  (1476, 'en', 'Butterfly Sit Up', 'In
this midrange exercise your arm muscles provide you with a little bit of
momentum to help to get you off the ground. You also open them up in overhead
position which engages the upper back. Start
lying with feet flat on the ground, knees at an angle, arms crossed in towards your chest. Using
your ab muscles, bring your upper body off the ground as you open your arms
into goal post position, then slowly lower yourself back down to return to
starting position.'),
  (1477, 'en', 'Seated Corkscrew', 'To
do this abs and obliques exercise, start with your hands back behind your body
and bring your knees in and across, really trying to contract the obliques.
Then extend your legs back out to starting position and repeat toward the
opposite side of the abs.
Beginners
might find that they can’t even get through the first 45 seconds of this
challenging reverse crunches variation. That’s ok because it gives you a
place to start and something to improve upon.'),
  (1478, 'en', 'Levitation Crunch', 'For
this top down movement, we’re trying to move the upper torso without moving the
lower torso. Start lying on the ground with feet flat on the floor and crossed
arms above your head with hands behind head. Lift upper body up and clear your
shoulder blades off the ground and then hold and pause at the top for a one or
two count. Try to make the upper abs work and hold that contraction for 10 good
quality reps.'),
  (1479, 'en', 'Sit Up Elbow Thrust', 'This
is a top down rotation movement, and it’s a bit more
explosive, too.
Lying with knees bent and feet on the floor, sit up and then drive your left elbow across your entire body toward the right, then come back
to center and then finally lower yourself down. Then hit the other side.'),
  (1480, 'en', 'Lying Triceps Extensions', '• Starting position for this
practical triceps exercise is lying on a standard bench holding a barbell or two dumbbells in both hands with an overhand grip, hands at shoulder width apart.
• Begin with arms over your upper
chest and elbows bent back at about a 45-degree angle.
• First bend at the elbows and
then allow the upper arm to drop back, bringing the barbell/dumbbells behind your
head and down toward the floor. In terms of upper arm position, the barbell/dumbbells should never be fully above your head, but instead behind it, to
ensure that you’re targeting the triceps.
• Keep the shoulder blades tucked
under, the elbows tight in toward your head and your core active during
this entire movement.'),
  (1481, 'en', 'Drag Pushdown', '• Starting
position for this rope pushdown is standing facing a cable machine with
the handles of a rope attachment in both hands and feet shoulder width
apart.
• Hinge
forward slightly at the hips maintaining an upright chest and bring the
shoulders and elbows behind the body so that when you push down on the
cable attachments, you can get a fully contracted triceps long head.
• Drag
the cable machine rope attachment as close to the body as possible and
straighten your elbows until lockout.'),
  (1482, 'en', 'Dumbbell Cheat Curl', '• Starting position is standing
with feet shoulder width apart.
• Hands should take an underhand
or supinated grip on the dumbbells holding them with hands shoulder
width apart.
• Keeping elbows tucked into your
sides throughout the entire movement, use momentum to curl the dumbbells,
squeezing your biceps at the top of the movement.
• Slowly lower to return to the
starting position. Keep the core tight throughout the exercise.
Cheating
through the concentric curling portion of this challenging exercise gives us a
great opportunity to increase time under tension and create eccentric overload
with heavier weight when we lower.'),
  (1483, 'en', 'Bizeps Curls Trifecta', 'This exercise is a mixture of three different curls: the Supinated Cross Body Curl, the Pronated Cross Body Curl and the No Money Curl. You
alternate between three curl variations that each accomplish different goals,
and you’ll keep the set going beyond the usual 8-12 rep range which gives
us that intensity.
• For the Supinated Cross Body
Curl, supinate the forearm with palms facing toward the ceiling and
forearms coming across the body. Lift the inner-facing weight of the dumbbell towards your shoulder.
• For the Pronated Cross Body
Curl, pronate the forearm with palms facing toward the floor (pronated
grip or overhand grip) and forearms coming across the body. Lift the inner-facing weight of the dumbbell towards your shoulder.
• For the No Money Curl, you’ll
curl the dumbbell as you outwardly rotate the shoulder. Lift the inner-facing weight of the dumbbell towards your outer side of the shoulder.'),
  (1484, 'en', 'Omni Cable Cross-over', 'Adjust the weights based on the
motion. When pulling from top to bottom, increase the weight by 20% to 40%
more than the bottom-to-top motion. This accounts for the fact that when
operating from top down, the upper chest muscles are naturally weaker than
the lower chest muscles. So, adjust your weight stack to
compensate.
• Position one cable at a high
setting and the other at the lowest level setting. Get into a staggered
stance in between the cable towers.
• For the cable set low, pull it
upward and across your body. This effectively targets the upper chest.
• For the cable set high, draw it
downward and across your body. This will primarily engage the lower chest.
Once you’re done, swap the
positions of the cables. Change the previously high cable to the lowest
position and vice versa. Repeat the exercise sequence, ensuring you’re
targeting both chest regions effectively.'),
  (1485, 'en', 'Rocking Triceps Pushdown', 'Set your feet below the rope and lean your upper body towards the rope. Set one foot back. Push down the rope and lean your entire body back onto the rear foot as you push down to get your hands behind your body. Don''t forget to bring your chest to the front during the pushdown. As you release the rope slowly, lean your body back onto the front foot.'),
  (1486, 'en', 'Alternating High Cable Row', '• Start
by putting the attachment in a high position on the cable station and step back about 1m from the attachment. Grab
the cable pulley handle in your left hand at about head height with your elbow slightly bent. Step back with your left foot.
• Pull
your elbow joint in toward the torso twisting slightly and perform a
single-arm row. Engage the lats as you twist.
• Return
to the starting position with cable pulley and left foot and grab the cable pulley handle in the right
hand. Repeat this motion on the opposite side with your right foot stepped back.'),
  (1487, 'en', 'Hyper Y W Combo', '• Use a glute-ham raise or a
stability ball for this exercise and a light weight plate in each hand.
• Raise your torso to form a straight line with your legs and raise the
arms outward slightly beyond a 90-degree angle into a W position to hit
the rotator cuff muscles, and then lower back to the starting position.
• Then raise up again with arms
in a Y position to activate the lower traps.'),
  (1489, 'en', 'Plank Jacks', 'Jumping jacks from the plank position.'),
  (1490, 'en', 'Lying Triceps Kickback', 'Set the bench to an 60deg angle. Stand still and rest your upper body on the inclined bench, ensuring a nearly straight line of your entire body. Squeeze your shoulder blades together, so that your elbows are located behind your torso with your upper arms nearly parallel to the floor. Lift the dumbbells until your arms form a straight line. Slowly lower the dumbbells back to the initial position. Initial position corresponds to an rectangular position of upper and lower arms.'),
  (1492, 'en', 'High Row', 'Kneeling down on one leg and pulling cable down while driving elbow into the lats.'),
  (1493, 'en', 'Bayesian Curl', 'Cable curl with stretched shoulder (backwards)'),
  (1496, 'en', 'DB Upper Chest Variation', 'Dumbbell in hand in a curl fashion, lean body into the arm to help the dumbbell up above the chest, next to the head, to activate chest and delt combo'),
  (1497, 'en', 'DB Underhand bench press', 'Underhand grip DB, perform a normal bench press movement, keeping the elbows close to the chest'),
  (1498, 'en', 'Elbows Tucked DB Bench Press', 'Elbows Tucked DB Bench Press, chest press movement focusing on the triceps. DB stays parallel with body'),
  (1501, 'en', 'Alternative DB Gorilla rows', 'Slightly bent down and knees to mimic a gorilla position and pull/row up the DBs to the chest. DB stay straight (thumbs pointing up)'),
  (1502, 'en', 'DB Cross Body Hammer Curls', 'Dumbbell cross body biceps curls, works on the braccialis'),
  (1503, 'en', 'Dumbbell Frog Press', 'Similar to hip thrust, but with feet put up together, lifting the butt off the ground in a frog like position.'),
  (1504, 'en', 'Dumbbell Bradford press', 'From a front hold of the DBs in a OHP, press above the head, bring back towards the rear of the shoulders, down, and press back forward.'),
  (1508, 'en', 'High-Incline Smith Machine Press', 'Set the bench to a 45-60° incline. Touch the upper chest with the bar.'),
  (1509, 'en', 'Cable Tricep Kickback', 'Grab onto the handle, and pull your elbow up and back slightly above
your torso. Keep your upper arm to be parallel to the ground for the
duration of the set'),
  (1510, 'en', 'Neutral Grip Lat Pulldown', 'Lat pull downs with a neutral grip on the bar.'),
  (1511, 'en', 'Kong Curl', 'This exercise is somewhat similar to a cable curl and a cable crossover. But instead of a chest/biceps exercise, this exercise targets the brachialis muscle, responsible for that broad arm when viewed from a front view.
During the exercise, maintain a pronated forearm position with starting position of approx. 45 degree pronated. Start with slightly bend elbows and alternately curl until your hands (your thumb first) meet your upper middle chest (similar to how Kong hits his chest, thus the name of this exercise).'),
  (1512, 'en', 'Drop Curl', 'Drop curls in a modified position at a slow pace effectively engage the brachialis for arm width.
Starting position is with both arms in a slight angle towards each other at chest height with a dumbbell in each hand. Lower one dumbbell close to full extended arm position slowly and in a controlled manner during the first half of the curl, then curl it back up to starting position, while the other dumbbell stays at its starting position. Now lower the other dumbbell down. This keeps tension on the brachialis. As we pass the 90deg mark on our way down, the biceps will take over the work.'),
  (1513, 'en', 'Overhead Cable Tricep Extension', 'Use rope handle with your back against the cable machine. Straighten your arms until they are filly extended and reverse the motion resisting on the negative.'),
  (1514, 'en', 'Lateral Walk', 'Lateral walks, also known as side steps or squat walks, are a type of exercise where you move sideways in a squatting position. They can be performed with or without resistance bands. These exercises strengthen the hip abductors, glutes, and other stabilizing muscles.'),
  (1515, 'en', 'Leg Press Toe Press', 'Move the leg press using your calves by placing your feet at the bottom of the platform.'),
  (1516, 'en', 'Handstand', 'Handstand free standing by pressing arms into the ground and contracting core and glutes'),
  (1519, 'en', 'Overhead Triceps Extension', 'Overhead Triceps Extension with EZ Bar – Quick Guide
The overhead position emphasizes the long head of the triceps (because it''s stretched under load), the exercise does engage all three triceps heads (long, lateral, and medial) to some degree during extension.
• Setup:
Sit on a bench (or stand) and hold an EZ bar with a narrow, overhand
grip. Lift the bar overhead, arms fully extended. Keep your core tight
and elbows close to your head.
• Execution:
Slowly lower the bar behind your head by bending your elbows until they
reach ~90°. Keep elbows pointed forward (not flaring out).
• Finish: Extend your arms back up to the starting position, squeezing your triceps at the top.
Tips:
• Control the movement to avoid straining your shoulders.
• Use a moderate weight for full range of motion.
• Keep your back straight and avoid arching.'),
  (1519, 'ru', 'Разгибание рук из-за головы', null),
  (1521, 'en', 'Pendular hack', 'Pendulum hack, made on a pendulum machine'),
  (1523, 'en', 'Sled Push', '• Load the sled with 25% of your maximum load. If you don’t know this, choose a weight you can push for 10 minutes with short breaks. Beginners may choose to push the sled with no weight.
• Stand behind the sled and grab the poles with a high-grip hand position.
• Engage your core muscles and start pushing the sled forward as fast as you can, powering through your entire leg. Extend your hips and knees as you move the sled forward. Your foot stance should resemble your natural running position.'),
  (1524, 'en', 'Battle Ropes', '• Hold the ends of the rope at arm''s length in front of your hips with your hands shoulder-width apart.
• Brace your core and begin alternately raising and lowering each arm explosively.
• Keep alternating arms for three to four sets of 1 to 2 minutes.'),
  (1525, 'en', 'Ball Slams', '• Stand with your feet about shoulder-width apart, your knees and hips slightly bent, holding the ball in both hands at chest height. Engage your core, and keep a good posture.
• Extend your knees and drive your hips forward while simultaneously lifting the ball. Aim for being as tall as possible, the ball overhead, arms up, hips slightly forward, and on your toes from the force of your drive.
• Use your core and arms to slam the medicine ball straight down between your feet with as much force as possible. Press your hips back and bend your knees to further power the slam. Exhale as you slam the ball down.
• Squat down to pick up the ball from the floor, then immediately move into the next slam by repeating the movement. Repeat for reps or time.'),
  (1526, 'en', 'Ski Machine', '• Start standing on the platform with your feet hip-width apart.
• Reach overhead to grip the handles with your palms facing in.
• Soften your knees, then simultaneously drive your butt back as if you''re closing a door behind you while pulling your arms straight down past your hips until your hands pass by the side of your knees.
• Next, bring your arms back overhead while thrusting your hips forward until you''re standing with your arms fully extended.
• Repeat for reps, time or distance.'),
  (1527, 'en', 'Pendulum Squat', 'Place your feet in the middle of the plate at about shoulder width. Tense your torso. Keep your neck relaxed.'),
  (1528, 'en', 'Glute Drive', 'Lie down on the back pad and strap yourself in with the waistband. Position yout feet shoulder-length apart. They should be slightly splayed.'),
  (1529, 'en', 'Toes to bar', 'The name "Toes to Bar" says it all: This exercise, in which you hang from a pull-up bar, involves bringing your toes toward the bar, pointing toward your face. This really works your abdominal muscles. "Toes to Bar" is popular in functional fitness programs like Freeletics and CrossFit, and is an effective exercise for six-pack training.'),
  (1530, 'en', 'Lying Dumbbell Curls', 'Take a
dumbbell in each hand and lie backwards on a bench, similar to a classic chest press.
Let your arms hang down at your sides, with the dumbbells possibly touching the
floor. Now start to lift the dumbbells upwards until your forearms are
perpendicular to the ceiling. Slowly lower the dumbbells until they almost
touch the floor again. Keep your ellbows in place to minimize cheating.'),
  (1531, 'en', 'Cable Curls', 'Bicep Curls using cables. Can be seated or standing'),
  (1536, 'en', 'Delt Stretch', 'Stretch your deltoids for a certain period of time.'),
  (1537, 'en', 'Pull-up Isometric Hold', 'Hold the pull-up movement in any position'),
  (1545, 'en', 'Archer Pull Up', 'An archer pull-up is an advanced bodyweight exercise that strengthens your back and biceps, serving as a progression towards a one-arm pull-up. It gets its name from the "bow-drawing" position your body takes at the top.Here''s how to do it:
• Grip: Grasp a pull-up bar with a wider-than-shoulder-width overhand grip.
• Starting Position: Hang with arms fully extended, engaging your core and keeping your shoulder blades pulled down.
• The Pull: Pull your body up towards one hand, similar to a regular pull-up. At the same time, extend the other arm out to the side, keeping it as straight as possible. Your chin should come towards the hand that is pulling.
• Hold & Lower: Briefly hold the top position where one arm is bent and pulling, and the other is extended. Slowly lower yourself back to the starting position with control.
• Alternate: Repeat the movement, pulling up towards the opposite hand.The key to this exercise is to keep the assisting arm as straight as possible to maximise the load on the working arm. This makes it a challenging but effective exercise for unilateral pulling strength.'),
  (1546, 'en', 'Larsen Press', 'Put your legs up on a separate Bench and press with no leg drive'),
  (1548, 'en', 'Stair Master', 'cardio and lower-body strength machine designed to simulate climbing stairs. It provides a low-impact, high-intensity workout that targets the legs, glutes, and core while improving cardiovascular endurance.'),
  (1551, 'en', 'Push-Up', 'The push-up is a fundamental bodyweight exercise that targets the chest, arms, and shoulders while engaging the core for stability. It requires no equipment and is excellent for building upper body strength.
Instructions:
• Start in a plank position with hands placed slightly wider than shoulder-width, feet together, and body in a straight line from head to heels.
• Engage your core and lower your body by bending your elbows, keeping them close to your body or flared slightly outward.
• Lower until your chest nearly touches the ground while maintaining a neutral spine.
• Push through your palms to return to the starting position, fully extending your arms.'),
  (1551, 'ru', 'Отжимания', null),
  (1554, 'en', 'Clap Push-UP', 'The clap push-up is an explosive upper body movement that builds power and fast-twitch muscle strength. It adds a plyometric challenge to the traditional push-up by requiring the hands to leave the ground mid-rep.
• Start in a strong push-up position with your hands slightly wider than shoulder-width and core engaged
• Lower your body explosively and push off the ground with enough force to lift your hands.
• Quickly clap your hands together at chest level before returning them to the floor.
• Land with soft elbows to absorb the impact and immediately move into the next rep'),
  (1556, 'en', 'Devil’s Press', 'The Devil’s Press is a hybrid movement combining a dumbbell burpee and a double dumbbell snatch. It’s a full-body, high-intensity exercise that develops strength, power, and metabolic conditioning.
• Start with a dumbbell in each hand and perform a burpee, letting your chest touch the ground while holding the dumbbells.
• Explosively jump your feet forward and swing the dumbbells between your legs.
• Drive the dumbbells overhead in one continuous motion, locking out your arms.
• Lower the dumbbells with control to return to the starting position and repeat'),
  (1567, 'en', 'Alternating dumbbell hammer curl', 'Stand with your knees slightly bent and your back straight. Hold a dumbbell in each hand, using a neutral grip at your sides.'),
  (1572, 'en', 'Bird Dog', 'The Bird Dog is a core stability exercise that enhances balance, coordination, and spinal alignment. It’s a low-impact movement ideal for strengthening the posterior chain and improving overall functional control.
• Begin on all fours with hands under shoulders and knees under hips, keeping your spine neutral.
• Extend your right arm forward and left leg backward simultaneously, keeping hips square.
• Pause briefly at full extension while engaging your core and glutes.
• Return to the starting position and repeat on the opposite side'),
  (1572, 'ru', 'Бёрд-дог', null),
  (1573, 'en', 'Ab wheel', '• Starting Position: Kneel on the floor with the ab wheel in front of you.
• Grip the Wheel: Hold the handles firmly.
• Roll Out: Slowly roll the wheel forward, extending your body while keeping your core tight.
• Return: Pull the wheel back towards your knees, maintaining tension in your core.'),
  (1573, 'ru', 'Ролик для пресса', null),
  (1574, 'en', 'Schwimmen', '• 800m Schwimmen in 20 Minuten'),
  (1574, 'ru', 'Плавание', null),
  (1575, 'en', 'Standing Dowel Shoulder press', 'Mobility - prone dowel press or standing dowel shoulder press alternating between front andback'),
  (1576, 'en', 'Snap Down', 'Begin in a standing position with your
arms up over your head and your toes pushing into the ground raising
your heels up becoming as tall as you can. From this position, perform a
small hop with both feet slightly coming off of the ground. As you
land, bend your knees and begin to hinge forward at your hips absorbing
the landing. Return to the starting position and repeat.
You should feel the muscles in your lower body working.
Start with your arms and knees fully
straightened out. Keep a stable balance as you land and briefly hold
that end position, don’t go too fast and become off balanced. Keep your
chest up.
For a detailed video on landing mechanics, click here: https://youtu.be/RThUCYRDyZw'),
  (1577, 'en', 'Bretzel stretch', 'How to Perform the Bretzel Stretch Starting Position: Lie on your back on a flat surface, such as a mat. Bend your knees and place your feet flat on the ground. Leg Positioning: Lift your right leg and cross it over your left leg, placing your right foot on the outside of your left knee. Your left leg should remain flat on the ground. Arm Positioning: Extend your left arm out to the side at shoulder height, keeping it straight. Use your right hand to gently pull your right knee towards the floor on the left side of your body. Stretching: As you pull your knee down, try to keep your left shoulder flat on the ground. You should feel a stretch in your hip, lower back, and possibly your chest. Hold the Position: Maintain this position for 20-30 seconds, breathing deeply and relaxing into the stretch. Switch sides and repeat the process.'),
  (1578, 'en', 'Hip hinge', 'Hip Hinge Exercise DescriptionThe hip hinge is a fundamental movement pattern that involves bending at the hips while keeping the spine neutral. It is commonly used in exercises like deadlifts, kettlebell swings, and good mornings. To perform a hip hinge: Starting Position: Stand with your feet hip-width apart and a slight bend in your knees. Hinge at the Hips: Push your hips back while maintaining a straight back. Your torso should lean forward, and your chest should stay up. Lowering Phase: Continue to hinge until your torso is nearly parallel to the ground, or until you feel a stretch in your hamstrings. Return to Standing: Drive through your heels and thrust your hips forward to return to the starting position.'),
  (1579, 'en', 'Bronco', 'Finess test for rugby.5 x shuttle runs of 20m, 40m, and 60m (20yd, 45yd, 65yd/far 45yd mark)
Complete as fast as possible'),
  (1580, 'en', 'Perpendicular Unilateral Landmine Row', 'Using a landmine attachment with the barbell running at 90 degrees to either side, hinge slightly at the hips and grip the barbell by the plate sleeve. Raise the barbell to chest height, with your upper arm parallel to the floor at the top of the movement.'),
  (1581, 'en', 'Trap press', 'Laying flat with arm pointing straight upwards, elbow fully extended, use only your shoulder to raise the weight as high as comfortable and back to rest.'),
  (1582, 'en', 'Side-laying interior rotation', 'Laying on your side and using the arm closest to the bench, maintain a 90 degree bend at the elbow and allow the weight to fall towards the ground past the bench as low as comfortable. Bring the weight up using only rotation of the shoulder to the opposing shoulder.'),
  (1583, 'en', 'Supine press', 'Take a close grip and push perpendicular to the bench. Keep back flat.'),
  (1584, 'en', 'March or jog in place', 'Low-impact cardiovascular exercise that simulates running without moving, ideal for warming up, improving endurance, or training in small spaces.'),
  (1589, 'en', 'Leg and hip stretch', 'Gentle movements to improve the flexibility of the lower body and release tension in the hips.'),
  (1590, 'en', 'Arm and neck stretch', 'Relieves tension in the upper body, especially useful for people with office jobs or prolonged postures.'),
  (1591, 'en', 'Deep breathing (standing or seated)', 'A conscious breathing technique to improve oxygenation, reduce stress and connect with the present moment.'),
  (1592, 'en', 'Guided or free meditation', 'A mental mindfulness exercise that helps reduce anxiety, improve focus and enhance overall well-being.'),
  (1593, 'en', 'Smith Machine Split Squat', 'The "Smith Machine Split Squat" is a strength exercise
performed on the Smith machine, ideal for targeting the legs and glutes.
It involves placing one foot forward and the other back, lowering the
body until the front thigh is parallel to the ground while the bar
slides vertically along the machine. This exercise helps improve
stability, correct muscle imbalances, and reduces stress on the back,
providing a safe environment for strength training.'),
  (1602, 'en', 'Dumbbell Scaption', 'Starting position:
Stand upright with your feet shoulder-width apart.
Hold a dumbbell in each hand with a neutral grip (palms facing each other).
Keep a slight bend in your elbows, shoulders relaxed and shoulder blades pulled back.
Execution:
Slowly raise the dumbbells forward and slightly to the side, at about a 30–45° angle from your body (between a front raise and a lateral raise).
Lift until your arms are about shoulder height (do not go overhead).
Pause for a second at the top and feel the activation in your shoulders and scapular stabilizers.
Lower the dumbbells back down under control to the starting position.
Breathing:
Inhale as you lower the dumbbells.
Exhale as you lift them.
Common mistakes:
Using dumbbells that are too heavy (causing jerky movements).
Lifting above shoulder height (puts unnecessary stress on the shoulder joint).
Arching the lower back instead of keeping the movement controlled at the shoulders.
Purpose of the exercise:
Activates the lower trapezius, serratus anterior, and scapular stabilizers.
Helps correct posture and improve shoulder balance.'),
  (1603, 'en', 'Leg curl with elastic', 'Standing position: Place the band under your feet in the middle of your foot and grasp it with a hammer grip.'),
  (1604, 'en', 'Sliding Lateral Lunge', 'Stand upright with your feet hip-width apart, holding a kettlebell close to your chest in goblet position. Place one foot on a slider, gliding disc, or towel. Keep your chest tall and core engaged. Slowly slide the foot outward to the side while bending the opposite knee, lowering your hips into a lateral lunge. Keep the working leg’s knee aligned with the toes and avoid letting it collapse inward. The non-working leg remains straight and slides smoothly along the floor. Push through the heel of the bent leg to return to the starting position while maintaining control of the kettlebell.'),
  (1605, 'en', 'Copenhagen Adduction Exercise', 'Lie on your side with the elbow placed directly under the shoulder, similar to a side plank position. Place the upper leg on a bench with the inside of the foot or ankle resting on it. Lift your hips and hold your body in a straight line while keeping the lower leg off the floor. The exercise strongly activates the adductors of the upper leg while also challenging the core and hip stabilizers.'),
  (1606, 'en', 'Arm Raises (T/Y/I)', 'Stand upright with feet hip-width apart, core engaged, and arms relaxed at your sides. From this position, perform three different arm raises to target the shoulders and upper back:
• T Raise: Lift your arms straight out to the sides until they are parallel to the floor, forming a “T” shape.
• Y Raise: Lift your arms upward at about a 45° angle from your body to form a “Y” shape.
• I Raise: Raise your arms straight overhead, close together, forming an “I” shape.
Maintain a neutral spine, avoid arching your lower back, and move slowly with control. Focus on squeezing your shoulder blades together and keeping your shoulders down away from your ears.'),
  (1607, 'en', 'Typewriter Pull-ups', 'Hang from a pull-up bar with an overhand grip, slightly wider than shoulder-width. Pull yourself up until your chin is above the bar. At the top position, instead of going straight down, shift your body to one side by extending one arm while keeping the other arm bent. Move smoothly from one side to the other, like a typewriter motion, before lowering yourself back down. This exercise increases time under tension and strengthens the lats, biceps, and shoulders while building unilateral pulling strength.'),
  (1608, 'en', 'Bodyweight Biceps Curl', 'Set up under a straight bar (around waist or chest height). Grip the bar with your palms facing you (supinated grip), hands about shoulder-width apart. Lean back with straight arms so that your body is at an angle to the ground. Keeping your elbows high and close to the bar, pull your upper body toward the bar by flexing your elbows, similar to a biceps curl. Lower yourself back down in a controlled manner. Keep your core tight and movement slow to maximize tension on the biceps.'),
  (1612, 'en', 'kettlebell sumo deadlift', 'Place your feet wider than shoulder-width apart, pointing your toes outward.
Keep your back straight, shoulders back, and chest up.
The knees must follow the same direction as the toes and not move forward.
When going up, it is advisable to contract your glutes to maximize the effectiveness of the exercise..'),
  (1613, 'en', 'rubber band glute kickback', 'A rubber band glute kickback is an exercise performed on hands and knees, where you anchor a resistance band to your foot and kick your heel back and up, squeezing your glute at the top of the movement, while maintaining a stable core and flat back to target and strengthen the gluteal muscles.'),
  (1615, 'en', 'Treadmill Cardio', 'It''s a cardiovascular workout performed on a treadmill to improve endurance, burn calories, and promote heart health. It offers multiple benefits, such as the ability to easily adjust speed and incline, allowing for a variety of workouts, from hill walking to high-intensity interval training (HIIT) and tempo runs. To optimize results, it''s important to vary your workouts.
Benefits of Treadmill Cardio:
• Improved Cardiovascular Health:
Regular aerobic exercise on a treadmill strengthens the heart and lungs, which can help prevent heart disease.
• Weight Loss:
By burning calories, treadmill training can be an effective tool for weight loss and maintaining a healthy weight.
• Muscle Strengthening:
It strengthens the muscles in the legs and glutes, helping to prevent muscle loss, which is especially important with age.
• Training Flexibility:
Allows you to vary speed, incline, and intervals, making your workout more dynamic and adaptable to different fitness levels.
Types of Treadmill Training:
• Hill Walking:
Increasing the incline of the treadmill and walking at a brisk pace can improve endurance and work your leg muscles.
• Endurance Jog:
A run at a comfortable, steady pace that keeps your heart rate in a target zone (such as Zone 2) to build endurance.
• Interval Training:
Alternating periods of high intensity (fast running) with periods of low intensity (easy walking or jogging) to maximize calorie burn and cardiovascular improvement.
• Tempo Run:
A run at a steady, sustained pace that is slightly faster than a normal jog, which challenges your ability to sustain a more intense effort for an extended period.'),
  (1616, 'en', 'Dumbbell donkey kick', 'The dumbbell donkey kick is an effective exercise for working the glute and hamstring muscles. This exercise is usually performed on all fours, using a dumbbell to add resistance. The steps for performing it correctly are described below.
Starting position: Get on all fours on a mat, with your hands aligned under your shoulders and your knees aligned under your hips.
Placing the dumbbell: Take a dumbbell and place it behind the knee of the leg you are going to lift. Make sure it is held securely to prevent it from falling during the exercise.
Exercise:
Inhale and, as you exhale, lift the leg with the dumbbell upward, keeping the knee bent at a 90-degree angle.
Raise the leg until it is parallel to the floor, feeling the contraction in the glutes.
Hold the position for one second at the top and then slowly lower the leg back to the starting position.
Repetitions: Perform 10 to 15 repetitions per leg, making sure to maintain good form throughout the exercise.
Sets: Complete 2 to 3 sets, depending on your fitness level.'),
  (1618, 'en', 'Stationary bike cardio', 'Benefits of Stationary Bike Cardio
Stationary bike cardio is an excellent form of exercise that offers multiple benefits for health and well-being. Here are some of the most notable ones:
Improved Cardiovascular Health
Strengthens the heart: Regular exercise helps improve the heart''s efficiency and reduce the risk of cardiovascular disease.
Increases circulation: It improves blood flow, which can help lower blood pressure.
Calorie Burning and Weight Loss
Efficient for burning calories: Depending on the intensity, you can burn between 400 and 600 calories per hour.
Helps with weight loss: Combined with a balanced diet, stationary bike cardio can be effective for losing weight.
Muscle Strengthening
Tones the legs: It mainly works the leg muscles, including the quadriceps, hamstrings and calves.
Improves muscular endurance: Over time, you can increase the endurance and strength in your legs.
Mental Health Benefits
Reduces stress: Exercise releases endorphins, which can improve your mood and reduce stress.
Boosts energy: Regular physical activity can raise your energy levels and improve sleep quality.'),
  (1620, 'en', 'Seated Dumbbell Calf Raise', 'The seated dumbbell calf raise is a targeted exercise for strengthening the lower leg muscles. It follows the same movement pattern as the machine version: you place the weight on your knees, and by extending and flexing your ankles, you move the weight.'),
  (1621, 'en', 'Unilateral Cable row', 'Put a vertical seated bench in front of the cable row machine.position it so that you can focus on one side, and then do slow pulls focusing on the lateral muscles and ensuring tention in those muscles when in a stretched position.'),
  (1630, 'en', 'Blaze', 'BLAZE is a full-body HIIT workout. Designed to supercharge your cardio fitness and strength. Delivered in its own purpose-built studio, BLAZE is a unique mix of martial arts, intense cardio and strength training.'),
  (1634, 'en', 'Rope Pullover/row', 'Set up bench in front of cable row machine. Lean over bench to do a row/pullover with rope that targets lats. See picture.'),
  (1635, 'en', 'Modified pulldown', 'With an inclined bench in front of the pulldown machine, use a close-grip to do latfocused pulldowns.'),
  (1637, 'en', 'Single arm row', 'Sitting on the ground, use a high cable in a single grip, to do lat pulldowns with a focus on a long stretch in the lats.'),
  (1638, 'en', 'Barbell Clean and press', 'This exercise involves lifting a barbell from the ground to the shoulders, then pressing it overhead. It is a compound movement that targets multiple muscle groups, including the legs, back, shoulders, and arms. It is often used in strength and conditioning programs to improve overall power and athleticism.'),
  (1639, 'en', 'Dumbbell Bent Over Face Pull', 'This exercise involves using dumbbells to perform a bent over face pull, which targets the upper back and shoulders. The movement involves pulling the weights towards the face while keeping the elbows high and squeezing the shoulder blades together.'),
  (1640, 'en', 'Dumbbell Front Squat', 'This exercise involves holding a dumbbell in each hand at shoulder height and performing a squat. It targets the lower body muscles, including the quads, hamstrings, and glutes, while also engaging the core and upper body.'),
  (1641, 'en', 'Kettlebell One Legged Deadlift', 'This exercise involves holding a kettlebell in one hand and standing on one leg while bending forward to touch the kettlebell to the ground. It targets the hamstrings, glutes, and lower back while also improving balance and stability.'),
  (1642, 'en', 'Dumbbell Hip Thrust', 'This exercise involves sitting on the ground with a dumbbell resting on the hips, then thrusting the hips upward while squeezing the glutes. It is a great exercise for strengthening the glutes and improving hip mobility.'),
  (1648, 'en', 'Weighted Crunch', 'The Weighted Crunch is a variation of the classic crunch exercise that involves adding resistance (a weight) to increase the intensity of the abdominal work.
• Lay down
• (Optional) Bend your knees to add difficulty
• (Optional) Bend your knees and let your feet rest on a bench or a box or something (90 degree angle on knees)
• Lift your head and torso while bending your back forward (if you don''t it''s a sit-up and also involves some back muscles). The higher you go, the more you should feel your abs contracting.
• Go back to starting position an repeat'),
  (1648, 'ru', 'Скручивания с весом', null),
  (1650, 'en', 'Dumbbell Side Bend', 'This exercise involves holding a dumbbell in one hand and bending sideways to work the oblique muscles on the side of the body. It can be done standing or seated and is often used as a core strengthening exercise.'),
  (1651, 'en', 'Dumbbell Rear Lunge', 'This exercise involves holding a dumbbell in each hand and stepping back into a lunge position, then returning to standing. It primarily targets the glutes, hamstrings, and quadriceps.'),
  (1652, 'en', 'Dumbbell Romanian Deadlift', 'This exercise involves holding a dumbbell in each hand and bending forward at the hips while keeping the back straight, then returning to a standing position. It primarily targets the hamstrings and glutes.'),
  (1652, 'ru', 'Румынская тяга с гантелями', null),
  (1653, 'en', 'Dumbbell Side Squat', 'This exercise involves holding a dumbbell in one hand and performing a squat while stepping to the side. It targets the legs, glutes, and core muscles.'),
  (1654, 'en', 'Machine Lateral Raise', 'The machine lateral raise is an isolation exercise that targets the medial (side) deltoid muscle to build wider, more defined shoulders. The machine''s fixed path of motion provides greater stability than dumbbells, making it ideal for beginners or those who want to focus solely on muscle activation.'),
  (1656, 'en', 'Cable Chest Press - Decline', 'Single arm chest press done with the cable machine. Use the other arm to brace bodyweight to focus on strength of the press, rather than balancing of the body. Start with the hand as close to the chest as possible, and then press against the cable at a slight decline and aiming towards the center of your chest.'),
  (1657, 'en', 'Preacher Curl - Internally Rotated', 'Single arm curl that can be done using a dumbbell and a preacher bench, or a preacher curl machine. Turn body towards the weight'),
  (1658, 'en', 'Preacher Curl - Externally Rotated', 'Single arm curl that can be done using a dumbbell and a preacher bench, or a preacher curl machine. Turn body away from the weight'),
  (1659, 'en', 'Lat Pulldown - Cross Body Single Arm', 'Sit at lat pulldown machine with body at a diagonal angle so that only one leg is under the pad. Pull the cable down with the opposite arm. this will force the cable to across your body while pulling down. Emphasises the stretch of the lat.'),
  (1660, 'en', 'Cable Chest Press - Incline', 'Single arm chest press done with the cable machine. Use the other arm to brace bodyweight to focus on strength of the press, rather than balancing of the body. Start with the hand as close to the chest as possible, and then press against the cable at a slight incline and aiming towards the center of your chest.'),
  (1661, 'en', 'Cable Triceps Press', 'A single arm exercise that starts with the hand close to the chest with with the elbows bent, and the elbow flared out. Press forward and down against the cable straightening the elbow.'),
  (1662, 'en', 'Cable Tri Extension - Internal Rotation', 'single arm exercise with cable held at opposite shoulder with elbow bent. Turn towards the cable, and the straighten the elbow across the body.'),
  (1666, 'en', 'Curl - With Shoulder Elevated', 'Place elbow so that it is about level with the shoulder. Curl the wieght to your shoulder. Focus on the stretch in the eccentric part of the curl'),
  (1668, 'en', 'One Arm Overhead Cable Tricep Extension', 'Set the pulley at the bottom of the cable machine and grab onto it without using any attachments. Extend the cable directly overhead.
While keeping your back straight and upper arm stationary, lower the cable behind your head until you feel a good stretch in your triceps, and then extend it back upward until your elbow is locked out.'),
  (1670, 'en', 'Leg Swings (Front–Back)', 'Stand tall next to a wall or stable support. Swing one leg forward and backward in a controlled motion, keeping the torso upright and the core engaged. Alternate legs after completing the repetitions.'),
  (1672, 'en', 'Seated Hip Abduction', 'Starting Position:
• Adjust the seat height so that your knees are aligned with the pivot point of the machine.
• Sit with your back flat against the backrest, maintaining good posture.
• Place the outside of your thighs against the machine''s padded levers.
• Position your feet flat on the footrests or platform of the machine.
• Grasp the handles or sides of the seat for stability.
• Ensure your spine is neutral and your core is slightly engaged.
Movement:
• Exhale as you slowly push your legs outward against the resistance pads.
• Focus on initiating the movement from your hips, not your knees.
• Continue opening your legs until you feel a strong contraction in your outer hips and thighs.
• Hold the fully abducted position briefly (1-2 seconds) to maximize muscle engagement.
• Inhale as you slowly control the return of your legs to the starting position, resisting the weight throughout the movement.
• Avoid allowing the weight stack to touch down between repetitions to maintain constant tension on the muscles.
• Repeat for the desired number of repetitions, maintaining control throughout the set.'),
  (1672, 'ru', 'Разведение ног в тренажёре сидя', null),
  (1679, 'en', 'Wall Angels', 'The Wall Angels exercise primarily targets the upper back and shoulder muscles, helping improve posture, shoulder mobility, and scapular control.'),
  (1680, 'en', 'seated figure four', 'Seat on a bench. Feet flat on the ground. Place your left ankle over your right knee. Your right knee stays flat. Keep your back straight. Gently push your left knee down.'),
  (1683, 'en', 'Zottman curl', 'With your palms facing forward, curl the weights up to your shoulders. Turn your hands so that that your palms downwards and slowly return the weights back down. Finally face your palms back forward.'),
  (1684, 'en', 'Dumbbell Thruster', 'Start with the dumbbells resting on your shoulders and squat down. Push
into standing and raise the dumbbells into an overhead position. Bring
the dumbbells back to your shoulders and repeat.'),
  (1686, 'en', 'Glute Bridge Single-Arm Press', 'With one dumbbell in hand, perform a glute bridge. Now hold the dumbbell above your chest, this is the rep starting position. Lower the dumbbell so that your elbow touches the floor or is roughly 45 degrees below your shoulder if using a bench. Push the dumbbell back into the starting position.'),
  (1687, 'en', 'Bear crawl pull through', 'Place a dumbbell at around hip level and assume a bear crawl position. Push the knees off the floor and hold.
With the opposite hand reach for the dumbbell and pull it to the other side. Place your hand back on the floor and repeat with your other hand.'),
  (1688, 'en', 'Kickstand RDL', 'use non-working leg''s toes to help with balance and perform an RDL.'),
  (1689, 'en', 'Cable Fly Middle Chest', 'Execution
•
Start position: Arms extended out to your sides (a big “T” shape), feeling a stretch in your chest.
•
Movement: Bring your hands together in front of your chest in a wide hugging motion.
• Focus on squeezing your chest at the center.
• Do not lock your elbows or turn it into a press.
•
Return: Slowly open your arms back to the start, maintaining tension on the chest.'),
  (1690, 'en', 'Cable Fly Upper Chest', 'Execution
•
Start position:
• Arms down and slightly behind your body, elbows slightly bent.
• Feel a light stretch across your chest.
•
Movement:
• Bring your hands upward and together in front of your upper chest — roughly at chin to collarbone level.
• Use a smooth, controlled motion (avoid jerking).
• Squeeze your chest at the top for 1–2 seconds.
•
Return:
• Slowly let your arms move back down and out to the sides, keeping control and tension.'),
  (1691, 'en', 'Cable Fly Lower Chest', 'Execution
•
Start position:
• Arms extended out to your sides in a “Y” shape.
• Feel a stretch in your chest (slight bend in elbows — don’t lock them).
•
Movement:
• Bring your hands downward and together in front of your lower chest or upper abs, in a smooth arc motion.
• Squeeze your chest hard at the bottom for 1–2 seconds.
•
Return:
• Slowly raise your arms back up along the same path until you feel a good stretch in your chest.
• Maintain control — don’t let the weights pull you back too quickly.'),
  (1693, 'en', 'Incline Static Hold', 'Execution
•
Hold Position:
• Lower the dumbbells a few inches above your chest — about the midpoint of a normal incline press.
• This is where your upper chest is under maximum tension.
•
Static Hold:
• Hold the position for 20–45 seconds while keeping the chest tight.
• Breathe slowly but stay tense — do not relax your chest or shoulders.
•
End the set:
• After the hold, carefully bring the dumbbells down and rest.'),
  (1694, 'en', 'Flat Machine Press', 'Execution
•
Start position:
• Elbows bent at roughly 90°, hands just outside your chest.
• Keep wrists straight and aligned with your forearms.
•
Pressing phase (concentric):
• Push the handles forward until your arms are almost fully extended — don’t lock out.
• Focus on squeezing your chest at the end of the movement.
•
Returning phase (eccentric):
• Slowly bring the handles back toward your chest, feeling the stretch in your pecs.
• Maintain tension — don’t let the weight stack touch down between reps.'),
  (1695, 'en', 'Pull-Ups (Wide Grip)', 'Execution
•
Pulling phase (concentric):
• Drive your elbows down and slightly back, pulling your chest toward the bar.
• Focus on leading with your chest, not your chin.
• Keep your shoulders depressed (avoid shrugging).
•
Top position:
• Chin should clear the bar (or at least reach bar level).
• Pause for a brief squeeze in your lats.'),
  (1695, 'ru', 'Подтягивания широким хватом', null),
  (1696, 'en', 'Pull-Ups (Neutral Grip)', 'Execution
•
Pulling phase (concentric):
• Drive your elbows down and back, pulling your chest toward your hands.
• Keep your shoulders depressed and retracted (avoid shrugging).
• Focus on squeezing your lats and upper back at the top.
•
Top position:
• Chin should clear or reach the level of your hands.
• Pause briefly and contract your lats hard.'),
  (1698, 'en', 'Barbell Row (Overhand)', 'Execution
•
Starting position:
• Hold the barbell with arms fully extended toward the floor.
• Maintain tension in your lats and back muscles.'),
  (1698, 'ru', 'Тяга штанги в наклоне', null),
  (1699, 'en', 'Barbell Row (Underhand)', 'Execution
•
Starting position:
• Hold the barbell with arms fully extended toward the floor.
• Maintain tension in your lats and back muscles.'),
  (1700, 'en', 'Barbell Romanian Deadlift (RDL)', 'Execution
•
Hinge at the hips:
• Push your hips backward, keeping a slight bend in the knees (soft knees).
• Lower the barbell along the front of your thighs/shins while maintaining a neutral spine.
• Keep the bar close to your body.'),
  (1700, 'ru', 'Румынская тяга со штангой', null),
  (1701, 'en', 'One-Arm Heavy Row', 'Execution
•
Rowing phase (concentric):
• Pull the dumbbell toward your lower chest or waist, leading with your elbow.
• Keep your torso stable — avoid twisting or rotating your shoulders.
• Pause at the top and squeeze your lats.'),
  (1702, 'en', 'Jalón al pecho con agarre ancho', 'The lat pulldown is a pulling exercise that primarily targets the latissimus dorsi muscles (commonly known as “lats”) in your back. It involves pulling a cable bar or handle down towards your chest while seated on a machine specifically designed for this exercise. The lat pulldown is typically performed with a wide grip, but can also be done with a narrow grip or underhand grip to target different muscle groups in the back and arms. It is a popular exercise for building upper body strength and improving posture.'),
  (1703, 'en', 'Patadas traseras', 'The dumbbell kickback is a popular strength training exercise that targets the triceps muscles in the back of your upper arms. It helps strengthen and tone the triceps, contributing to overall arm strength and aesthetics.
Among the exercises that work the arm muscles, kickback and its variations are very effective. You can easily apply these exercises with dumbbells, cables or resistance bands.'),
  (1704, 'en', 'Tuck L-sit', 'The tuck L-sit is a bodyweight hold where you support yourself on parallel bars, parallettes, or the floor with straight arms while pulling your knees toward your chest. Your hips stay lifted, your spine stays tall, and your feet hover off the ground. The goal is to keep your core tight, shoulders depressed, and arms locked out while maintaining the tucked position. It’s a core-intensive, shoulder-stabilizing static hold often used as a progression toward the full L-sit.'),
  (1706, 'en', 'Bulgarian Squat with Dumbbells', 'The Bulgarian split squat consists of performing a squat on one leg with the rear foot resting on a raised platform. Elevating your back leg on a bench creates instability and increases the range of motion of the exercise.'),
  (1706, 'ru', 'Болгарские выпады с гантелями', null),
  (1707, 'en', 'Elevación lateral polea', 'Lateral elevation unilateral using a polea'),
  (1709, 'en', 'Reverse Fly Standing', '• Stand with a good posture holding a cable in each hand opposite the machine
• Starting with the hands in front of your chest pull the arms out to
your side into the shape of a T with the elbows nearly straight
• Slowly release the arms forward to the start
• Repeat with the arms moving into the shape of a Y
• Repeat with the arms in the shape of a W
• Repeat with the arms in the shape of an L by your side'),
  (1710, 'en', 'Butchers Block Stretch', '• Kneel down with the hands together
• Rest the elbows on a bench in front of you and lower the chest down
• Keep the elbows bent with good posture and hold'),
  (1711, 'en', 'Sleeper Stretch', '• Lie on your side so that you are resting a little weight on your shoulder blade to keep it still
• Extend your arm to 90 degrees in front of you, resting on the floor/mat
• Lift your hand with your elbow so that your fingers point to the ceiling and your palm points towards your feet
• Keeping your elbow still, gently lower your palm toward the floor'),
  (1712, 'en', 'Horizontal Shoulder Flexion Stretch', '• Raise your arm out to the side, placing your hand on a wall or doorway beside you at shoulder height
• Turn your body away from your arm to stretch the chest, as far as is comfortable'),
  (1713, 'en', 'Doorway Pectoral Stretch', '• Place the forearm vertically on a door frame or stationary object at head height
• Step forward past the arm, keeping it still against the object to stretch the chest'),
  (1714, 'en', 'Shoulder Dumbbell Pendular Exercise', '• Lean forward to rest your hand on a chair or other object, holding a dumbbell in the other hand
• Gently swing the dumbbell in a circular motion'),
  (1715, 'en', 'Shoulder External Rotation with Dumbbell', '• Lie on your side holding a dumbbell in your upper hand
• Tuck your elbow into your side and rest the hand in front of you
• Rotate the shoulder so the hand raises up
• Lower the hand down'),
  (1716, 'en', 'Incline Shoulder Press Up', '• Place your hands on the bench in a press up position
• Push your chest away from the bench to separate your shoulder blades
• Keeping your elbows straight, lower your chest towards the bench so your shoulder blades move closer together
• Push your chest away from the bench again'),
  (1717, 'en', 'Neck extension', 'Unilateral triceps exercise with your back to the pulley, with the pulley at the top'),
  (1718, 'en', 'Remo alto polea alta', 'High pulley row with support using a single grip'),
  (1719, 'en', 'Jalon caballero unialteral', 'Pull performed in knight''s stance'),
  (1723, 'en', 'Glute Kickback (Machine)', 'Drive through your heel, not your toes, to hit the glute.
Don’t hyperextend your lower back at the top.'),
  (1724, 'en', 'Standing Adduction (Cable)', 'Keep your hips square and still, pulling the cable across your opposing leg using only your inner thigh.
Don’t let your torso lean or twist — no side bending to help the rep.'),
  (1725, 'en', 'Seated Row (Machine)', 'Keep your chest up and squeeze your shoulder blades at the end.
Don’t hunch forward or round your back during the pull.'),
  (1726, 'en', 'Straight-Arm Pulldown (Cable)', 'Keep arms straight but not locked, pulling with your lats, not your shoulders.
Don’t let your shoulders shrug up during the movement.'),
  (1726, 'ru', 'Тяга верхнего блока прямыми руками', null),
  (1727, 'en', 'Side Straight-Arm Pulldown (Cable)', 'Keep your torso still, pulling the handle down along your side using the outer lat.
Don’t twist your body or rotate your torso to cheat the rep.'),
  (1728, 'en', 'Shoulder Internal Rotation (Cable)', 'Keep your elbow tucked to your side like it''s superglued there.
Don’t rotate your torso — only your forearm should move.'),
  (1729, 'en', 'Shoulder External Rotation (Cable)', 'Keep elbow fixed at your side and rotate forearm outward smoothly.
Don’t let your wrist or elbow drift upward — stay in one plane.'),
  (1730, 'en', 'Side Lateral Raise (Cable)', 'Lift with your elbows leading, not your hands.
Don’t shrug your shoulders; keep traps quiet.'),
  (1731, 'en', 'Front Raise (Cable)', 'Raise the handle in a slight arc with controlled movement.
Don’t swing your torso to start the rep.'),
  (1732, 'en', 'Face pulls with yellow/green band', 'Face pulls with band – standing horizontal pull. Grab the band at face height, pull elbows high and wide towards your face while squeezing shoulder blades together. Trains upper back, rear shoulders and improves posture.'),
  (1733, 'en', 'Isometric Squat to Failure', 'sometric Squat to Failure: A Strength Training Technique
Definition
The isometric squat to failure is a variation of the squat exercise where you hold a static squat position at a specific angle, maintaining the position until your muscles can no longer sustain the contraction.'),
  (1734, 'en', 'Single-Leg Lunge with Kettlebell:', 'How to do a single-leg kettlebell lunge
Preparation: Stand with your feet together. Hold the kettlebell with both hands by the handle, keeping it close to your chest, or hold it with one hand (on the same side as the working leg).
Step and Lower: Take a large step forward (or backward, which is safer for your knees) with one leg, lowering your hips until both knees form a 90-degree angle.
Focus: Shift your weight onto your front (or bent) leg, keeping your back straight and your torso upright.
Return: Push off with your front leg to return to the starting position.'),
  (1735, 'en', 'Single-leg side glute press', 'The Single-Leg Side Glute Press is a leg press machine variation where you angle your body sideways on the pad, placing one foot high and slightly angled to press the weight, powerfully targeting the outer glute (gluteus medius/minimus) and hamstrings for balanced leg development and stability, requiring focus on pushing through the heel and maintaining control without locking out.
How to Perform:
Setup: Sit in the leg press machine, rotate your body to one hip, placing one foot high on the platform at about a 45-degree angle with toes pointed slightly out/forward.
Positioning: Keep your hip, knee, and ankle aligned, and ensure your lower back stays on the pad.
Descent: Slowly lower the weight, allowing your knee to bend deeply (near 90 degrees), feeling a stretch in your glute and hamstring.
Press: Drive through your heel (not your toes) to press the weight back up, squeezing your glutes and hamstrings, stopping just before your leg fully extends.
Control: Avoid bouncing and don''t let your lower back lift off the pad; maintain tension throughout the movement.'),
  (1736, 'en', 'Single-Leg Deadlift with Dumbbell', 'Starting Position: Stand upright with a slight bend in your knees, holding a dumbbell in one or both hands. Shift your weight onto your supporting leg (e.g., your right leg) and lift your non-supporting foot slightly off the floor.
The Hinge: Keeping your back flat and core engaged, hinge at your hips, pushing your glutes backward. As your torso lowers, extend your non-supporting leg straight back behind you for balance, keeping your hips square to the floor. The dumbbell(s) should lower toward the ground along the line of your supporting leg.
Range of Motion: Continue lowering your torso until it is nearly parallel to the floor, or you feel an intense stretch in your supporting hamstring, ensuring your back remains neutral throughout the movement.
Return to Start: Pause at the bottom, then contract your glutes and hamstrings to slowly raise your torso back to the starting position. Your non-supporting leg should return in line with the supporting one.
Switch Sides: After completing your desired number of repetitions on one side, switch your weight and repeat the movement on the other leg.'),
  (1737, 'en', 'Assisted chin-ups', 'Chin-ups with machine assistance (counterweights)'),
  (1738, 'en', 'Neutral-grip pull-ups or TRX rows', '•
Pull-Up: Vertical Pull — Focuses more on the Lats (back width).
TRX Row: Horizontal Pull — Focuses more on the Rhomboids/Traps (mid-back thickness and posture).'),
  (1739, 'en', 'Shrimp Squat', 'Single leg squat where one leg is behind you.'),
  (1740, 'en', 'Single Leg Glute Bridge', 'A glute bridge, where you use just one leg at a time.'),
  (1741, 'en', 'L-Sit Pull-ups', 'L-Sit Pull-ups train both upper body and core muscles.'),
  (1742, 'en', 'Back Lever', 'Hanging from a pull-up bar facing downwards with your arms extended'),
  (1743, 'en', 'Windshield Wipers', 'Hang from a pull-up bar, raise your legs to the ceiling. Move lower body from left to right with straight legs like a windshield wiper'),
  (1744, 'en', 'Machine Side Lateral Raises', 'Machine side lateral raises are an isolation exercise for the side (lateral) deltoids, performed on a machine for stability, targeting the outer shoulder by lifting pads or handles out to the sides to shoulder height, then lowering slowly, keeping elbows slightly bent and traps down to focus on the delts. This exercise helps build shoulder width by preventing swinging and providing constant tension, making it great for beginners or as a finisher.
How to Perform Machine Lateral Raises
Setup: Adjust the seat so your shoulders align with the machine''s pivot point, your chest is against the pad (or back if facing out), and your arms are at a 90-degree angle with the pads/handles.
Starting Position: Grip the handles with a relaxed grip, elbows slightly bent, and shoulders down (depressed) away from your ears.
Lifting Phase: Exhale and lift your arms out to the sides, moving your upper arms laterally, until they are parallel to the floor.
Peak Contraction: Pause briefly at the top, squeezing the side delts, but don''t shrug your shoulders up.
Lowering Phase: Inhale and slowly lower the weight back down with control, resisting the weight on the way down.'),
  (1745, 'en', 'Cable Front Raise with a small bar', 'The Cable Front Raise with a small bar isolates your anterior deltoids (front shoulders) by providing constant tension, requiring you to stand facing away from a low pulley, grab the bar with an overhand grip, and lift it in front of you to shoulder height with slightly bent arms, avoiding swinging and keeping your core tight for controlled movement up and down. Use a light-to-moderate weight, focusing on slow, controlled reps to feel the muscle work, not momentum.
How to Perform the Cable Front Raise (Bar)
Setup: Attach a small straight bar to a low cable pulley. Set the weight to a light or moderate setting.
Starting Position: Stand with your back to the machine, holding the bar with an overhand grip (palms facing down) at hip level, arms extended but not locked. Feet shoulder-width apart, core braced, shoulders back and down.
The Lift: Exhale and slowly raise the bar straight up in front of you, keeping a slight bend in your elbows, until your hands reach shoulder height (or slightly below).
The Hold: Pause briefly at the top, squeezing your front delts.
The Lower: Inhale as you slowly and controllably lower the bar back to the starting position, maintaining tension.'),
  (1747, 'en', 'Smith machine squat', 'Technique and Execution
The Smith machine squat is a variation of the traditional barbell squat that uses a guided, fixed-path barbell. Here''s a detailed breakdown of the proper technique:
Starting Position
Foot Placement: Position feet slightly forward of the bar, about shoulder-width apart
Bar Position: Rest the bar on your upper trapezius/shoulders, similar to a traditional back squat
Stance: Feet can be slightly angled outward for natural hip rotation
Squat Movement
Unrack the bar by rotating it to release from the safety hooks
Slowly lower your body by bending knees and hips
Descend until thighs are parallel to the ground (or slightly below)
Pause briefly at the bottom of the movement
Drive through your heels to return to the starting position
Benefits and Considerations
Advantages
Reduced Balance Requirements: Fixed bar path makes it easier for beginners
Controlled Movement: Less risk of improper form compared to free weight squats
Isolation: Allows focused leg muscle development'),
  (1748, 'en', 'Machine Hip Abduction', 'Technique and Execution
Starting Position
Seated Positioning: Sit in the machine with back against the pad
Leg Placement: Inner thighs against the machine''s padded resistance points
Adjust Machine: Set seat position to align your hip joint with the machine''s pivot point
Movement Technique
Start with legs together or slightly pressed against the inner pads
Slowly push legs outward, spreading them apart
Move until maximum comfortable lateral range is reached
Pause briefly at the outer point of the movement
Slowly return to the starting position with controlled movement
Biomechanical Breakdown
Muscle Engagement
Primary Activation: Gluteus Medius (side hip muscle)
Stabilization: Engages core and lower back muscles
Functional Movement: Mimics lateral leg movement used in walking, sports, and daily activities
Benefits
Strength and Stability
Improves Hip Stability
Reduces Risk of Knee Injuries
Enhances Lateral Movement Capabilities
Targets Often-Neglected Muscle Groups'),
  (1751, 'en', 'Cable pull through', 'The Cable Pull Through is a lower-body exercise that targets the glutes and hamstrings using a "hip hinge" motion. To perform it, attach a rope to the lowest pulley setting, face away from the machine with the rope between your legs, and step forward to create tension. Keeping your back flat and knees slightly soft, push your hips backward as if trying to close a door behind you until you feel a deep stretch in your hamstrings.
To finish the rep, explosively drive your hips forward to return to a standing position, squeezing your glutes hard at the top. It is vital to remember that this is not a squat; your knees should not bend deeply, and your arms should remain straight and relaxed, acting only as hooks for the rope. This movement provides constant tension on the glutes while placing less stress on the lower back than a traditional deadlift.'),
  (1752, 'en', 'Side lateral raise - Front (Cable)', 'in a cablerack do a side lateral raise with cable in front of you, with focus in tension on the back of your shoulder.'),
  (1753, 'en', 'Side lateral raise - Back (Cable)', 'on a cable rack do a side lateral raise with the cable behind you. focus on tension in the front of the shoulder.'),
  (1754, 'en', '45° lateral raises', 'dumbbell raise in the space between front and side raises'),
  (1755, 'en', 'Shoulder Y-pull cable', 'on a cable rack cross the cables and pull elbows to ceiling close to the body.'),
  (1766, 'en', 'Plank Reach', 'Position your body in plank position, keeping your eyes on the ground. Raise one arm in front of you and return it. Repeat with the other arm. Raise and return slowly while keeping your body as still as possible.'),
  (1771, 'en', 'Wrist curl, cable', '• Extend your arm down, then slightly lift your forearm
• Extend your wrist in a supinated form (palm up)
• Adjust cable height so that the cable handle is in your supinated hand
• Perform the movement by
curling your palms and wrists upwards
• (optional/variable) Pause at the top
• Slowly return to the starting position'),
  (1772, 'en', 'Reverse crunch', '• Lay down
• Place your hands near your butt (often slightly in front or under or both)
• Raise your legs, but about 70% of the way you should be able to also raise your pelvis
• (optional/variable) Hold 1/2 seconds at the top
• Go back to starting position'),
  (1772, 'ru', 'Обратные скручивания', null),
  (1773, 'en', 'Legend Incline Bench Press', 'incline bench press on LeverEdge machine.'),
  (1774, 'en', 'Chair dips', 'Starting position:
Sit down on the front edge of a chair, back straight, hands holding the front edge. Still holding the edge of the chair, arms extended, lift your butt and walk forward slightly so that it is a few inches from the chair.
Steps:
•
Slowly lower your body, keeping the back straight, until your arms are at a right angle.
•
Raise your body again to the initial position, arms extended.
•
Repeat.'),
  (1775, 'en', 'Pec deck rear delt fly', 'Seated rear delt fly on pec deck machine (facing the machine and extending arms backwards, the hands should be at the height of the shoulders)'),
  (1776, 'en', 'Suitcase Carry', 'Walk forward and backward with holding dumbbell on one side without leaning to counter the weight.'),
  (1777, 'en', 'Deficit Push ups', 'Pushup on blocks or grips, so you can dip lower than the hands in the decent.'),
  (1778, 'en', 'Supino inclinado', 'Inclinado 90 graus e movimentos leves e precisos'),
  (1779, 'en', 'Landmine Rotation', 'Start with landmine barbell straight up by using your shoulders to push it up above you. Then, from that position, bring it your side to target your abdominals and return to starting position.'),
  (1795, 'en', 'unilateral cross body cable pull down', 'on a cable rack place cable high, and with a straight arm pull that cable across you from high to low. focus on tension in back shoulder.'),
  (1801, 'en', 'Barbell Full Squat', '• The barbell full squat is a compound exercise that targets multiple muscle groups in the lower body, including the quadriceps, hamstrings, and glutes.
• Proper form is crucial for maximizing results and preventing injuries during the barbell full squat. This includes maintaining a shoulder-width stance, creating whole body tension, controlling your descent, and maintaining proper depth and knee positioning.
• Assistance moves such as the front squat, goblet squat, split squat, and Bulgarian split squat can help improve your performance in the barbell full squat by targeting specific muscle groups and improving overall technique.
• To achieve new personal records in your back squat, gradually increase weight over time, vary rep ranges and sets to stimulate muscle growth, and prioritize rest and recovery between training sessions.'),
  (1801, 'ru', 'Приседания со штангой', null),
  (1803, 'en', 'Trap Bar Squat', 'A combination of squat and deadlift principles with the use of a hex/trap bar, easing stress on the lower back by better centering the weight.'),
  (1804, 'en', 'ankle dorsiflexion rocks', 'Move your knee forward, keeping your heel on the ground. Hold the position for a couple of seconds and return to the starting position.'),
  (1807, 'en', 'Behind the Back Cable Lateral Raise', 'Lateral raises have long been a staple for building capped delts, and lifters use everything from dumbbells and bands to machines and single-arm variations to make them grow.'),
  (1808, 'en', 'Parallel Bar Hold', '• Stand between a set of parallel bars.
• Place your hands, knuckles outwards, on the bars.
• Push down on your hands to lift yourself off the floor.
• Hold yourself in this position with your arms straight for the required time.'),
  (1809, 'en', 'Reverse Hyperextension', 'Lie face-down on a bench with your legs hanging off the edge.
• Bend your hips so your thighs are vertical, bending your knees at the same time so your shins stay horizontal.
• Straighten out your legs so they are not bent and your toes are pointing backwards horizontally.
• Return to the original position, and repeat.'),
  (1810, 'en', 'Sphinx', 'Lie on your stomach flat, legs extended and the backs of your feet on
the ground. Bring your forearms under your shoulders, elbows directly
underneath. Then press your hands into the floor to lift your chest.
Draw your shoulder blades together, open your collarbones, and direct
your gaze forward, while keeping the lower back relaxed.'),
  (1822, 'en', 'Open Book', 'Basic exercise
• Focus: enhances thoracic mobility and
spinal segmentation while opening the shoulders and chest.
• **Position:**kneeling on the floor with your right side facing a wall. Hips are square and stable, with the right knee down and the left foot forward. Lengthen your spine and align your head comfortably.
Begin with your arms relaxed and open in front of your chest, palms
facing each other and hands apart.
• Inhale
to initiate the movement, allowing your left arm —the one farther from
the wall— to open outward and backward. Lead the twist from your thoracic
spine, rotating your upper back progressively while keeping your pelvis
still.
• Exhale as you complete the rotation, guiding your left hand
toward the wall as your gaze follows your hand.
• Return by inhaling and
slowly bringing your arm forward, reversing the spinal rotation segment
by segment.
• Repeat on the opposite side.
Progression
• **Position:**kneeling on the floor with your right side facing a wall. Left knee down and right foot forward.
• Before the basic exercise: inhale, exhalewhile moving the right arm along the wall with a circle upwards and backwards, inhalewhile bringing back the arm.
• Basic exercise.
• Repeat on the opposite side.'),
  (1823, 'en', 'Clamshell', 'Position
Side plank with the elbow and the forearm on the ground and the legs slightly bent.
Execution
Lift your upper knee while keeping your feet close together, like a “shell opening,” then slowly return to the starting position. Keep your core stable and your hips aligned.'),
  (1824, 'en', 'Dumbell Tate Press', '• Set Up: Lie flat with a dumbbell in each hand. Extend your arms straight up over your chest as if you were at the top of a dumbbell bench press
• Starting Position: Position the dumbbells so they are touching or very close together with a pronated grip (palms facing your feet and thumbs facing each other)
• Lowering: Without moving your upper arms or shoulders, bend your elbows and flare them outward to the sides. Lower the inner ends of the dumbbells toward the center of your chest
• Touch and Pause: Gently touch the dumbbells to your chest. Do not rest the weight on your body; maintain constant tension in your triceps
• Press: Forcefully extend your elbows to return the dumbbells to the starting position. Focus on "pushing your pinkies toward the sky" to maximize triceps engagement
https://www.youtube.com/watch?v=IgSjoXbpy1M&t=2'),
  (1825, 'en', 'Chest-Supported Rear Delt Raise', '"The Y"Position: Set an incline bench to 30-45 degrees. Lie face-down with your chest supported, keeping your head neutral or looking slightly down to avoid neck strain.Grip: Hold light dumbbells with a neutral or thumbs-up grip (thumb pointing to the ceiling).Movement: With straight or slightly bent elbows, raise the dumbbells up and out in a "Y" shape. Focus on moving the shoulders and shoulder blades rather than just lifting the arms.Top Position: Squeeze the shoulder blades together and reach high, ensuring the arms are angled to form a "Y".Control: Lower the dumbbells slowly to the starting position.'),
  (1826, 'en', 'Band pull-apart with external rotation', 'Stand tall with your feet shoulder-width apart, chest out, and shoulders back.
Hold the resistance band with both hands, palms facing up or facing each other, depending on the band type.
Bend your elbows at a 90-degree angle and glue your upper arms to your sides.
The band should have some tension in the starting position, with your hands closer together in front of your stomach.
Rotate Outward: While keeping your elbows tucked into your sides, slowly move your hands away from each other, stretching the band.
Squeeze: Squeeze your shoulder blades together and down as you rotate your hands outward.
Range of Motion: Rotate your hands as far outward as you comfortably can without allowing your elbows to leave your sides.
Hold: Hold the end position for 1–2 seconds to maximize muscle engagement.
Return: Slowly and with control, bring your hands back to the starting position.'),
  (1827, 'en', 'Double-Leg Abdominal Press', 'Lie on your back with knees and hips bent at 90 degrees (tabletop).
Place your hands on your thighs just above your knees. Push your hands against your knees as hard as possible while using your abs to pull your knees toward your hands.
Hold for 10 seconds of maximum effort. Your abs should be shaking.'),
  (1828, 'en', 'Abdominal Draw-In', 'Lie
on your back with knees bent. Gently pull your belly button toward your
spine without moving your hips or holding your breath.'),
  (1829, 'en', 'Landmine Squat to Press', 'Bar Position: Anchor one end of a barbell in a landmine attachment or a secure corner.
Stance: Stand facing the barbell with feet slightly wider than shoulder-width. Turn your toes out 10–35 degrees to allow for better pelvic movement and depth.
Grip: Cup the free end of the barbell with both hands (fingers interlaced or overlapping) and hold it at mid-chest level, just below the collarbone.
Descent: Brace your core and sit back into a squat, keeping your chest up and weight on your heels.
Depth: Lower until your thighs are at least parallel to the floor. A good reference is when your elbows touch the tops of your thighs or just inside your knees.
Posture: Ensure your back remains flat and your spine neutral throughout the movement.
Drive: Powerfully drive through your heels to stand up. Use the momentum from your legs to "thrust" the weight upward.
Extension: In one fluid motion, press the bar overhead until your arms are fully extended. At the top, your biceps should be near your ears.
The "Lean": As you reach the top of the press, lean slightly forward into the bar to encourage proper upward rotation of the shoulder blades and avoid lower back arching.
Slowly lower the barbell back to chest height in a controlled manner before immediately beginning the next repetition.'),
  (1830, 'en', 'Barbell Step Back Lunge', 'Step 1: Stand with your feet hip-width apart, holding a barbell on your upper back.
Step 2: Keep your back straight, chest up, and core engaged.
Step 3: Take a step back with one leg and lower your body by bending both knees. Ensure that your back knee nearly touches the ground.
Step 4: Push off your back foot to return to the starting position.
Step 5: Repeat the movement with the other leg.
Continue alternating between legs for the desired repetitions.'),
  (1831, 'en', 'Hammerstrength Decline Chest Press', '• Sit upright in a hammerstrength decline chest press machine while squeezing your shoulder blades together and placing your heels firmly on the ground underneath your knees.
• The back pad should be contact with your head, shoulders, and butt at all times.
• Grab ahold of the handles with an overhand grip just outside shoulder-width apart just below your chest.
• Keeping your core braced by breathing into your stomach and flexing the abdominal muscles, push through your palms to extend your elbows while keeping them at a 45 degree angle from your torso.
• Once your arms are fully extended, return to the starting position.'),
  (1832, 'en', 'Ring Support Hold', 'Hold yourself in a support position on gymnastic rings with arms straight at sides. Focus on keeping rings turned out slightly and maintaining hollow body position. This is an isometric hold for chest, shoulders, and triceps.'),
  (1833, 'en', 'Floor Glider Hamstring Curls', 'Lie on back with heels on floor gliders or towels. Lift hips into a bridge, then slide heels toward glutes while keeping hips elevated. Slowly return to the starting position while maintaining the hip bridge.'),
  (1834, 'en', 'Trap-3 Raise', '• Hinge forwards and bend your knees slightly. Depress and retract the shoulder you will use. Rest the other hand on your knee.
• Raise your hand about 15 degrees overhead, maintaining the position of your shoulder.'),
  (1835, 'en', 'External Rotation Stretch', '• Sit with your feet pressed against each other, and one knee raised all the way out to the side of your body.
• Place your elbow on your raised knee, bend it at 90 degrees, and point your hand directly forward, holding your barbell/dumbbell.
• Keep your shoulder depressed and retracted, raise your hand until your forearm is vertical, as if you were about to wave at someone like a robot.
• Lower your hand to the original position and repeat.'),
  (1838, 'en', 'Banded Shoulder Drills', '• Attach a resistance band to something solid behind you. Stand away from it, holding it in your hand so it is taut.
• See the attached youtube video: https://www.youtube.com/watch?v=zdwEWchSjrI .'),
  (1839, 'en', 'Solo Hip Flexor Stretch', 'See this instructive video: https://www.youtube.com/watch?v=qHwyBHS6MQs .'),
  (1840, 'en', 'Bent-Leg Hamstring Stretch', 'See this instructional video from Stretch Therapy: https://www.youtube.com/watch?v=CrF2iMnn09w .'),
  (1841, 'en', 'Seated Shoulder Extension Stretch', '• Sit with your hands behind you, shoulder width apart.
• Lock your elbows.
• Scoot your feet and hips out forwards, lowering your shoulders down towards ground.
• Go as far as possible to obtain a good stretch.
See the video: https://www.youtube.com/watch?v=ihUAbG0e8zw'),
  (1842, 'en', 'Banded Clamshell', 'Position
Side plank with the elbow and the forearm on the ground and the legs slightly bent. Stretch a doubled-up resistance band between your thighs, just above the knee.
Execution
Lift
your upper knee while keeping your feet close together, like a “shell
opening,” then slowly return to the starting position. Keep your core
stable and your hips aligned.'),
  (1843, 'en', 'Butterfly Stretch', '• Sit in a prayer position with the soles of your feet gently pressed together.
• Use your hands to slowly pull your feet inwards towards your groin. Hold for as long as required.'),
  (1844, 'en', 'Frog Stretch', '• Get on your hands and knees.
• Widen your knees outwards, and drop to your elbows.
• Without moving your elbows or knees, start to rock forwards and backwards, trying to get your bum closer to your feet.'),
  (1845, 'en', 'Seated Pancake Good Morning', '• Sit with your legs completely straight (knees locked), spread wide in a straddle position.
• Place your hands on the back of your neck.
• Hinge your torso and head towards the floor.'),
  (1846, 'en', 'Horse Stance (Side Splits)', '• Stand as for a squat, with your feet wide and your toes pointed slightly outwards.
• Gently squat into a deep, wide squat - your hips should be below your knees.
• Hold for 3 to 5 seconds.
• Come up under control, and repeat as needed.'),
  (1847, 'en', 'Straddle L-Sit', 'With your legs in a sitting saddle position, push your body upwards off the ground. Your legs should be horizontal and point straight outwards. Your arms should be between your legs.
Hold isometrically as long as required.'),
  (1852, 'en', 'L-sit', 'Sit on the ground with your legs together and your arms by your sides. Push your body off the ground using your hands, maintaining the same sitting position so that your legs are straight and your feet do not touch the floor.
Hold for as long as required.'),
  (1853, 'en', 'L-Sit (Foot Supported)', 'As with an L-sit, but allow your feet to touch the floor to support the some of the weight of your legs.'),
  (1854, 'en', 'Calves foam roller', 'Move your calves slowly over the foam roller'),
  (1855, 'en', 'Hamstring Foam roller', 'Move your hamstrings slowly over the foam roller'),
  (1856, 'en', 'Foam Roller Anterior tibialis', 'Use the foam roller slowly in the tibial anterioris. This is english, please'),
  (1857, 'en', 'Foam Roller Iliotibial band', 'Slide on the Foam Roller over your iliotibial band. Is english terrible checker'),
  (1858, 'en', 'Foam Roller quadriceps', 'Slide the Foam Roller over your quadriceps. Is english, please'),
  (1859, 'en', 'Foam Roller Gluteus', 'Slide on the Foam Roller over your gluteus. Is english please'),
  (1860, 'en', 'Foam Roller Adductors', 'Slide the Foam Roller over your Adductors. Is english please'),
  (1861, 'en', 'Side stretch', 'View the video to undestand the exercise'),
  (1862, 'en', 'Hip Circles', 'View the video to undestand the exercise'),
  (1863, 'en', 'Hip Crossover', 'View the video to undestand the exercise'),
  (1864, 'en', 'Ankle Roll', 'View the video to undestand the exercise'),
  (1865, 'en', 'Banded Ankle Mobility', 'View the video to undestand the exercise'),
  (1867, 'en', 'Hip Flexor Stretch', 'View the video to undestand the exercise'),
  (1868, 'en', 'Lunge with Twist Stretch', 'View the video to undestand the exercise'),
  (1869, 'en', 'Lying Figure Four Stretch', 'View the video to undestand the exercise'),
  (1870, 'en', 'Lying Hamstring Stretch with Band', 'View the video to undestand the exercise'),
  (1872, 'en', 'Pigeon Stretch', 'View the video to undestand the exercise'),
  (1873, 'en', 'Quad Stretch', 'View the video to undestand the exercise'),
  (1874, 'en', 'Runners Lunge Stretch', 'View the video to undestand the exercise'),
  (1875, 'en', 'Standing IT Band Stretch', 'View the video to undestand the exercise'),
  (1876, 'en', 'Supported Calf Stretch', 'View the video to undestand the exercise'),
  (1877, 'en', 'Banded Scapular Retraction', 'Attach one end of resistance band to wall/upright/... at shoulder height. Insert arm into the loop, at the tricep. Step back until band is pulled straight. Pull back elbow and shoulder against the resistance of the band.'),
  (1879, 'en', 'Incline DB Y-Raise', '• Set
an incline bench to a 45-degree angle and sit facing the bench, chest
against the pad, with a dumbbell in each hand, palms facing each other.
• Position your feet firmly on the ground for stability and let your arms hang down naturally with a slight bend in your elbows.
• Engage your core and keep your back straight throughout the movement.
• Raise your arms forward and out to form a Y shape, keeping the movement controlled and your elbows slightly bent.
• Lift until your arms are roughly parallel to the floor and in line with your ears.
• Pause
briefly at the top of the movement to engage your shoulder muscles
fully, then slowly lower your arms back down to the starting position.
• Ensure
the movement is slow and controlled during both the ascent and descent
to maximize engagement of the deltoids and supporting muscles.
• Repeat for the desired number of repetitions, maintaining proper form throughout.'),
  (1881, 'en', 'DB Wrist Extension', ': Grab two dumbbells with an overhand grip and lay your forearms across your knees.
: Let your wrists flex fully, then extend your wrists.'),
  (1882, 'en', 'High-Cable Lateral Raise', 'Stand next to a cable machine with the pulley set to waist height.
Grab the opposite-side handle with the hand farthest from the
pulley, keeping your palm facing in.
Keep your core engaged, chest lifted, and shoulders relaxed. Maintain a slight bend in the elbow throughout the lift.
Lift your arm out to the side until your elbow reaches shoulder height, keeping your wrist aligned with your elbow.
Briefly pause at the top, then slowly lower the handle back to your side with control. Repeat for the desired reps.'),
  (1884, 'en', 'Shinbox IR Stretch', '• Starting Position: Sit on the floor with both hips and knees bent at 90-degree angles.
• Leg Placement:
Place one leg in front of you (external rotation) and the other leg out
to the side/behind you (internal rotation). The shins and knees should
remain flat on the ground.
• The Movement:
Keeping your hips square, hinge your torso forward or tilt it laterally
(side-to-side) toward the front leg to deepen the stretch.
• Target Areas:
Stretches the glutes and piriformis (front leg) and the hip flexors and
quads (back leg). Engages the core and obliques during lateral flexion.
• Goal: Improves hip mobility, specifically internal and external rotation, and relieves lower back tension.'),
  (1885, 'en', 'YTWL Exercise', '• Purpose: Improves shoulder stability, posture, and scapular (shoulder blade) control. Often used in physical therapy and warm-ups.
• Starting Position:
Stand with feet shoulder-width apart. Hinge forward at the hips (like a
deadlift) keeping your back flat, or lie face down on an incline bench.
Keep your thumbs pointing up throughout.
• Y (Arms up):
Extend both arms straight forward and upward at a 135-degree angle from
your body, forming a "Y". Squeeze your shoulder blades together at the
top.
• T (Arms out): Open your arms straight out to the sides, perpendicular to your body, forming a "T". Focus on pinching your shoulder blades.
• W (Arms bent): Pull your elbows back, bending them to 90 degrees, and squeeze your shoulder blades to form a "W". Keep your wrists firm.
• L (Arms rotated):
Start with elbows bent at 90 degrees and close to your body. Rotate
your forearms outward (external rotation) like a goalpost, forming an
"L" or a gate.
• Key Focus:
Movements should be slow and controlled. Always lead with the thumbs
and think about moving the shoulder blades, not just the arms.'),
  (1886, 'en', 'Supine Hip Abduction', '• Starting Position:
Lie on your back (supine) on a mat, with your legs extended and
relaxed. Arms can be placed alongside your body or out to the sides for
stability.
• The Movement:
Slightly lift one leg off the floor (keeping it straight or with a
slight bend). Move it laterally outward, away from the other leg, as if
stepping over a small obstacle.
• Range of Motion:
Move the leg as far as comfortable without lifting your pelvis or
rotating your torso, feeling a stretch in the inner thigh and hip.
• Return: Slowly bring the leg back to the starting position with controlled movement.
• Goal: Improves lateral hip mobility (abduction) and strengthens the pelvic stabilizer muscles.'),
  (1889, 'en', 'Decline Bench Leg Raise', '• Setup: Lie on a decline bench with your head at the top and grip the handles.
• The Start: Extend legs fully, keeping them slightly elevated to engage your core.
• The Lift: Raise your legs toward the ceiling using your abs, not momentum.
• The Squeeze: Pause and contract your lower abdominals at the top.
• The Return: Lower your legs slowly to the starting position with control.'),
  (1893, 'en', 'Overhead Barbell Press', '• Setup: Stand with feet together and grip the bar slightly wider than shoulders.
• Position: Rest the bar on your upper chest.
• Press: Brace your core and push the bar straight up until your arms lock out.
• Finish: Control the bar back down to your chest.
• https://youtu.be/ZXpdJOLNoWw?si=u27cGyODoblXHBu1'),
  (1900, 'en', 'Tricep Rope Pushdowns', '• Setup: Stand facing the cable, feet shoulder-width apart, with a slight forward lean.
• Grip: Hold the rope with palms facing each other and elbows tucked tight to your ribs.
• Execution: Push the rope down until arms are fully straight, pulling the ends apart at the bottom.
• Control: Keep upper arms still and return to the start with a slow, controlled motion.'),
  (1900, 'ru', 'Разгибание рук на блоке с канатом', null),
  (1901, 'en', 'Clean and Press', '• The First Pull: Lift the bar from the floor to knee-height by driving with the legs, keeping the angle of your back constant.
• The "Power" Position: As the bar reaches mid-thigh, explosively shrug and extend your hips to create vertical momentum.
• The Quick Elbow Turnover: In the catch phase, rotate your elbows rapidly under the bar to create a "shelf" on your front deltoids.
• The Vertical Press: Press the bar in a straight line; your head should shift slightly forward once the bar clears your forehead to reach full lockout.'),
  (1902, 'en', 'Weighted push-ups', '• Setup: Begin in a standard plank position with a weight plate balanced securely on your upper back.
• Alignment: Maintain a straight line from your head to your heels, engaging your core to prevent your back from sagging.
• Execution: Lower your body until your chest nearly touches the floor, keeping your elbows at a forty-five degrees.
• Ascent: Press through your palms to return to the starting position, fully extending your arms.'),
  (1904, 'en', 'Pec Deck', 'Pectoral issolation exercise - full range of motion is best with full contraction and slow negative'),
  (1904, 'ru', 'Сведение рук в тренажёре (пек-дек)', null),
  (1905, 'en', 'Pullback', 'Set weight and grip for the cables in the cage. Take a few steps away, bend over, pull and extend the back at the same time.'),
  (1906, 'en', 'Hip Bridge', 'Get into bridge position, balance yourself on heels and start extending legs unilaterally.
Keep hip extended as much as possible.'),
  (1907, 'en', 'Unilateral Lunges', 'No stops during movement, hands on the hips.'),
  (1908, 'en', 'Butterfly Superman', 'Lie on stomach, intertwine fingers behind the head and start raising your head and raise elbows as far as they go.'),
  (1909, 'en', 'Leg Wheel', 'Lay on the back and lift legs in perpendicular fashion, keeping the knees together.
Start making small circles in one direction with both of your knees with very small range of motion, focusing on abs and keeping your back in contact with the floor.'),
  (1910, 'en', 'Kneeling Superman', '•
Push one foot back until leg fully extended, concentrating on the having the foot high and pushed back as if pulled.
•
Extend arm forward with focus having the shoulder high up.
Unilateral and static hold.'),
  (1911, 'en', 'Cat Plank', 'On your fours and raise the knees of the floor ever so slightly.
Curl your back out and push back from your shoulders as to resemble a cat making itself look large.'),
  (1912, 'en', 'Core Rotation', 'Sit back, raise feet above the ground with knees bent and start rotating left and right with hands touching the ground every move.'),
  (1913, 'en', 'Unilateral Hip Thrust', 'Extend one leg while laying down and start raising your body with one leg touching the ground through the heel.'),
  (1914, 'en', 'Isometria alle parallele', 'The parallel bars isometric hold is a static upper-body exercise performed on dip bars (parallel bars). Instead of moving up and down like in a traditional dip, you hold a fixed position under tension.'),
  (1915, 'en', 'Quadruped Hip Abduction', 'Distribute your body weight evenly on all knees and arms.
Keep the torso stable, with the abdomen engaged and the lumbar spine
straight without twisting the back (imagine: a glass on your lower back
won''t fall off). Raise one leg outwards without twisting it.
Pay attention to the right angle at the hips and knees. Always train both sides of the body.
To increase resistance, a resistance band can be used.'),
  (1916, 'en', 'Tuck planche', 'Basic calisthenics progression for the full planche'),
  (1918, 'en', 'Legend Chest Press', 'Plate-loaded chest press machine from Legend Fitness LeverEdge line.'),
  (1919, 'en', 'Extreme Pec Stretch', 'Deep loaded stretch for pectorals, typically performed at end of chest work.'),
  (1920, 'en', 'Extreme Shoulder Stretch', 'Deep loaded stretch for deltoids, performed after pressing movements.'),
  (1921, 'en', 'Extreme Lat Stretch', 'Deep loaded stretch for latissimus dorsi, performed after pulling movements.'),
  (1922, 'en', 'Seated Cable chest fly', '• Place a bench between two cable pulleys and adjust the pulleys so they are at chest/shoulder height when you are seated.
• Grab the handles with a neutral grip and lean against the upright backrest.
• Bring your arms together in front of your chest in a controlled motion, focusing on squeezing your chest muscles. Keep your elbows slightly bent throughout the movement.
• Pause briefly at the top position.
• Slowly lower your arms back to the starting position while maintaining control of the movement.
• Repeat for reps.'),
  (1924, 'en', '3008 Abdominal Crunch', 'This is especially for the gym80 device 3008 Abdominal Crunch.'),
  (1925, 'en', 'Barbell Silverback Shrug', '• Stand with your feet shoulder width apart holding the barbell with both hands in front just past shoulder width.
• Bend forward at the hips with a slight bend in your knees, keeping your back straight.
• Engage your shoulder blades, as if you are trying to touch them together.
• Release the shrug.
Description taken from MuscleWiki'),
  (1927, 'en', 'Inverted Lat Pull Down', 'The Inverted Lat Pull Down (most commonly known as the Reverse Grip Lat Pull Down) is a variation of the standard exercise that uses an underhand (supinated) grip with hands at shoulder-width. This position shifts more emphasis to the lower lats and increases biceps involvement, often allowing for a greater range of motion and a deeper squeeze at the bottom of the movement.'),
  (1928, 'en', 'Seated V-Grip Row', 'The Seated V-Grip Row is a compound pulling exercise performed on a cable machine using a close-grip "V" handle. While seated with your feet braced, you pull the handle toward your midsection, focusing on back thickness and mid-back development.'),
  (1929, 'en', 'Assisted Pull-Up', 'The Assisted Pull-Up is a compound vertical pulling exercise performed on a machine with a counterweight platform or by using resistance bands. It mimics the mechanics of a standard pull-up but reduces the total weight you have to lift, making it an excellent tool for building functional strength and perfecting your technique.'),
  (1929, 'ru', 'Подтягивания в гравитроне', null),
  (1931, 'en', 'Dumbbell Curl', 'The Dumbbell Curl is a classic isolation exercise for the arms. Unlike the Hammer Curl, it involves rotating your wrists (supination) as you lift the weights, which allows for a full contraction of the biceps.'),
  (1933, 'en', 'Abdominal Crunch', 'The Abdominal Crunch is a classic core isolation exercise performed on the floor or a mat. Unlike a full sit-up, it involves a smaller range of motion where you only lift your shoulders and upper back off the ground, keeping your lower back pressed firmly against the floor.'),
  (1935, 'en', 'Belt Squat', 'Belt Squat: a squat variation done with a belt attached to a loading machine or platform so the weight is supported at the hips instead of on the spine. It mainly trains the quads and glutes, with much less lower-back fatigue than a barbell squat. Use a full range of motion, keep the torso upright, and drive through the mid-foot.'),
  (1936, 'en', 'Cable Rear-Delt Fly (single arm)', 'Cable rear delt fly (single arm):
Stand sideways to a cable machine with the handle set around shoulder height. With a slight bend in the elbow, pull the handle out and back in a wide arc so the upper arm moves away from the body. Keep your torso still and focus on the rear delt doing the work. Use light to moderate weight and controlled reps.'),
  (1938, 'en', 'Cat-Cow', 'On all fours. Arch spine up (cat) then drop it down (cow). Breathe with movement.'),
  (1938, 'ru', 'Кошка-корова', null),
  (1939, 'en', 'Neck CARs', 'Controlled Articular Rotations. Slow full circles 3 each way. Cervical mobility.'),
  (1940, 'en', 'Diaphragmatic Breathing', 'Belly breathing. Hand on chest stays still, hand on belly rises. 8-10 slow breaths.'),
  (1947, 'en', 'dumbbell snatch', 'Key Steps to Execute Correctly:
Setup: Place the dumbbell between your feet, with your shoulders above your hips, chest up, and back flat.
The Pull: Explosively extend your hips, knees, and ankles (triple extension) to drive the dumbbell upward, keeping your elbow high and the dumbbell close to your body.
The Catch: Quickly flex your hips and knees to drop under the dumbbell and receive it overhead with your arm locked in position, landing in a half-squat stance.
Common Mistakes: Using your arms too much to lift the weight instead of your legs, having a low elbow during the pull phase, and misaligning your shoulder, elbow, and wrist in the final position. For beginners, it’s recommended to start with light loads, focus on technique, and perform 3 to 5 sets of 3 to 5 reps per arm.'),
  (1948, 'en', '1 Leg Box Squat', 'This exercise requires a sturdy box or a chair. Simple stand ~6 inches in front of it and balance yourself on one leg. From here, begin squatting down in a smooth controlled motion while keeping your other leg straight out in front of you for balance. Slowly sit down on the box, pause for a 1 count and push back up with the working leg, while never letting your other leg touch the ground.'),
  (1949, 'en', 'Limber 11', 'Limber 11
Source: Joe DeFranco
1. Foam Roll IT Band [soft_tissue] - 10-15 passes
2. Foam Roll Adductors [soft_tissue] - 10-15 passes
3. SMR Glutes (lax ball) [soft_tissue] - 30 sec-2 min
4. Bent-knee Iron Cross [dynamic] - 5-10 reps each side
5. Roll-overs into V-sits [dynamic] - 10 reps
6. Rocking Frog Stretch [dynamic] - 10 reps
7. Fire Hydrant Circles [dynamic] - 10 forward / 10 backward
8. Mountain Climbers [dynamic] - 10 reps each leg
9. Cossack Squats [dynamic] - 5-10 reps each side
10. Seated Piriformis Stretch [isometric] - 20-30 sec each side
11. Rear-foot-elevated Hip Flexor Stretch [dynamic + 3s hold] - 5-10 reps each side'),
  (1950, 'en', 'Foam Roll IT Band', 'Foam Roll IT Band
Part of: Limber 11
Source: Joe DeFranco
